var e={id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari`,sira:66,kurul:1,ders:`Tıbbi Patoloji`,konu:`Erkek Genital Sistem ve Prostat Hastalıkları`,ogretim_uyesi:`Prof. Dr. Hikmet Keleş`,tarih:`2026-10-19`,soru_sayisi:340,kazanimlar:[{no:1,metin:`Erkek genital sistem patolojisinin kapsamını (penis, skrotum/testis/epididim, prostat) açıklayabilmek`,sorular:[{id:`k1-66-q01`,kazanim:1,zorluk:`kolay`,soru:`Erkek genital sistem patolojisi aşağıdaki organlardan hangisini kapsamaz?`,secenekler:{A:`Skrotum`,B:`Penis`,C:`Testis ve epididim`,D:`Böbrek`,E:`Prostat`},dogru:`D`,aciklama:`Erkek genital sistem patolojisi penis, skrotum/testis/epididim ve prostatı kapsar; böbrek üriner sistem organıdır.`,sik_aciklamalari:{A:`Skrotum erkek genital sistemdedir.`,B:`Penis erkek genital sistemin parçasıdır.`,C:`Testis ve epididim erkek genital sistemdedir.`,D:`Doğru: böbrek genital değil üriner sistem organıdır.`,E:`Prostat erkek genital sistemin aksesuar bezidir.`},bilgi:[1,20],benzer_cikmis:[]},{id:`k1-66-q02`,kazanim:1,zorluk:`orta`,soru:`Erkek genital sistem lezyonları ile ilgili organ eşleştirmelerinden hangisi doğrudur?`,secenekler:{A:`Varikosel – prostat`,B:`Peyronie hastalığı – penis korpus kavernozumu`,C:`BPH – testis`,D:`Seminom – epididim`,E:`Hidrosel – prostat`},dogru:`B`,aciklama:`Peyronie hastalığı korpus kavernozumda fibröz bantlarla oluşur.`,sik_aciklamalari:{A:`Varikosel spermatik kordda gelişir.`,B:`Doğru: Peyronie penisin hastalığıdır.`,C:`BPH prostatın transisyonel zonundan gelişir.`,D:`Seminom testisin germ hücreli tümörüdür.`,E:`Hidrosel tunika vajinalis içinde sıvı birikimidir.`},bilgi:[8,10,11,27,38],benzer_cikmis:[]},{id:`k1-66-q03`,kazanim:1,zorluk:`zor`,soru:`Aşağıdaki erkek genital sistem hastalıklarından hangisi acil cerrahi müdahale gerektiren ürolojik problemdir?`,secenekler:{A:`Spermatosel`,B:`Varikosel`,C:`Testiküler torsiyon`,D:`Benign prostat hiperplazisi (erken dönem)`,E:`Peyronie hastalığı`},dogru:`C`,aciklama:`Testiküler torsiyon az sayıdaki ürolojik acillerden biridir; ilk 6 saatte cerrahi müdahale testisi kurtarabilir.`,sik_aciklamalari:{A:`Spermatosel acil değildir.`,B:`Varikosel elektif olarak düzeltilebilir.`,C:`Doğru: zamanında müdahale testisin yaşaması için kritiktir.`,D:`Erken BPH farmakolojik tedavi edilir.`,E:`Peyronie acil değildir.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k01-q04`,kazanim:1,zorluk:`orta`,soru:`Öğrenci erkek genital sistem patolojisinin bölümlerini sayıyor. Hangi kapsam doğrudur?`,secenekler:{A:`Erkek genital patoloji yalnızca prostatı kapsar`,B:`Erkek genital sistem patolojisi penis, skrotum-testis-epididim ve prostatın konjenital, inflamatuar, vasküler ve neoplastik hastalıklarını kapsar`,C:`Testis hastalıkları kapsam dışındadır`,D:`Penis hastalıkları ürolojinin değil dermatolojinin tek alanıdır`,E:`Prostat patolojisi yaşla ilişkisizdir`},dogru:`B`,aciklama:`Erkek genital patoloji penis, skrotum-testis-epididim ve prostatın konjenital-inflamatuar-vasküler-neoplastik hastalıklarını kapsar; çoğu yaş-androjen-hijyenle ilişkilidir.`,sik_aciklamalari:{A:`Üç bölge kapsanır.`,B:`Doğru: üç bölge ve dört hastalık grubu tamdır.`,C:`Merkezi bölgedir.`,D:`Patolojinin parçasıdır.`,E:`Yaş-androjenle ilişkilidir.`},bilgi:[1,12,20],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k01-q05`,kazanim:1,zorluk:`zor`,soru:`Üç bölgenin ortak belirleyicileri soruluyor. Hangi bütünleştirici açıklama doğrudur?`,secenekler:{A:`Hijyenin rolü yoktur`,B:`Androjenler yalnızca pubertede etkilidir`,C:`Çevresel etkenler tarihsel değildir`,D:`Kötü hijyen-smegma penis karsinomunda, androjen yoksunluğu BPH-kanserde belirleyicidir; skrotumun çevresel karsinomu mesleksel maruziyetin ilk kanıtıdır`,E:`Yaş dağılımı etkilemez`},dogru:`D`,aciklama:`Androjen düzeyi, lokal hijyen-çevresel etkenler ve yaş hastalık dağılımını belirler (smegma-HPV, androjen-BPH-kanser).`,sik_aciklamalari:{A:`Smegma-HPV rol oynar.`,B:`Yaşam boyu belirleyicidir.`,C:`Pott ilk kanıttır.`,D:`Doğru: üç bölge-etken ilişkisi tamdır.`,E:`Yaş temel belirleyicidir.`},bilgi:[4,24],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k01-q06`,kazanim:1,zorluk:`orta`,soru:`Erkek genital sistem patolojisinin kapsamı nedir?`,secenekler:{A:`Kapsam yalnızca prostatla sınırlıdır`,B:`Penis, skrotum-testis ve prostat patolojiyi oluşturur`,C:`Epididim kapsam dışıdır`,D:`Skrotum patolojisi yoktur`,E:`Penis kapsam dışıdır`},dogru:`B`,aciklama:`Erkek genital patoloji penis, skrotum-testis-epididim ve prostatı kapsar. Peniste konjenital malformasyonlar (hipospadias-epispadias), skrotumda hidrosel-varikosel, prostatta BPH-karsinom bu kapsamın başlıklarıdır.`,sik_aciklamalari:{A:`Penis ve skrotum-testis de dahildir.`,B:`Doğru: üç anatomik bölge birlikte doğru verilmiştir.`,C:`Epididimit-orşit kapsamdadır.`,D:`Hidrosel-varikosel skrotum başlıklarıdır.`,E:`Malformasyon ve karsinom penis başlıklarıdır.`},bilgi:[1,10,24],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k01-q07`,kazanim:1,zorluk:`orta`,soru:`Bölgelere göre baskın patolojiler nelerdir?`,secenekler:{A:`Penis tümörleri glandülerdir`,B:`Testis tümörleri benigndir`,C:`Prostat kanseri transisyoneldir`,D:`Penis skuamöz, testis germ hücreli, prostat periferik zon baskındır`,E:`Bölgeler aynı patolojiyi paylaşır`},dogru:`D`,aciklama:`Penis neoplazilerinin %95'ten fazlası skuamöz kökenlidir; testis tümörlerinin %95'i postpubertal germ hücrelidir ve maligndir. Prostat karsinomları %70-80 periferik zondan gelişir; her bölgenin baskın patolojisi farklıdır.`,sik_aciklamalari:{A:`%95'ten fazlası skuamözdür.`,B:`Postpubertal %95'i malign germ hücrelidir.`,C:`%70-80 periferik zondandır.`,D:`Doğru: üç bölgenin baskın özelliği birlikte doğru verilmiştir.`,E:`Her bölgenin patoloji spektrumu farklıdır.`},bilgi:[4,29,36],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k01-q08`,kazanim:1,zorluk:`kolay`,soru:`"BPH morfolojisi" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,B:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,E:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,A:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,D:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`},dogru:`C`,aciklama:`Doğru: BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,sik_aciklamalari:{C:`Doğru. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,B:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,E:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,A:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,D:`Yanlış. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`},bilgi:[27],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k01-q09`,kazanim:1,zorluk:`kolay`,soru:`"BPH: DHT etkisi ve α1-adrenerjik düz kas" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{A:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,B:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,E:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,C:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,D:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`},dogru:`A`,aciklama:`Doğru: DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,sik_aciklamalari:{A:`Doğru. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,B:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,E:`Yanlış. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,C:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,D:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`},bilgi:[26],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k01-q10`,kazanim:1,zorluk:`orta`,soru:`"Skrotum neoplazileri (Percival Pott)" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{D:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,C:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,A:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,E:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,B:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`},dogru:`D`,aciklama:`Doğru: Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,sik_aciklamalari:{D:`Doğru. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,C:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,A:`Yanlış. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,E:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,B:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k01-q11`,kazanim:1,zorluk:`orta`,soru:`"İnvaziv skuamöz hücreli karsinom ve prognoz" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,A:`Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,E:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,D:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,C:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`},dogru:`B`,aciklama:`Doğru: En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,sik_aciklamalari:{B:`Doğru. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,A:`Yanlış. Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,E:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,D:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,C:`Yanlış. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k01-q12`,kazanim:1,zorluk:`zor`,soru:`"Testis neoplazileri: genel özellikler ve risk faktörleri" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{E:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,C:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,A:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,D:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,B:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`},dogru:`E`,aciklama:`Doğru: Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,sik_aciklamalari:{E:`Doğru. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,C:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,A:`Yanlış. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,D:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,B:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`},bilgi:[36],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k01-q13`,kazanim:1,zorluk:`zor`,soru:`"PSA ölçümü ve sınırlamaları" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,A:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,D:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,C:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,E:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`},dogru:`B`,aciklama:`Doğru: PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,sik_aciklamalari:{B:`Doğru. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,A:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,D:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,C:`Yanlış. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,E:`Yanlış. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`},bilgi:[34],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:2,metin:`Hipospadiasta üretranın anormal açıklığının penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyonda olduğunu bilmek`,sorular:[{id:`k1-66-q04`,kazanim:2,zorluk:`kolay`,soru:`Üretranın anormal açıklığının penisin ventral yüzeyinde bulunmasına ne ad verilir?`,secenekler:{A:`Fimozis`,B:`Epispadias`,C:`Hipospadias`,D:`Parafimozis`,E:`Balanit`},dogru:`C`,aciklama:`Hipospadiasta üretral açıklık ventral yüzde, şaft boyunca herhangi bir yerdedir.`,sik_aciklamalari:{A:`Fimozis prepisyumun geri çekilememesidir.`,B:`Epispadiasta açıklık dorsal yüzdedir.`,C:`Doğru: ventral açıklık hipospadiastır.`,D:`Parafimozis geri çekilen prepisyumun glansı sıkıştırmasıdır.`,E:`Balanit glansın inflamasyonudur.`},bilgi:[1],benzer_cikmis:[`a9a0cae034ca`]},{id:`k1-66-q05`,kazanim:2,zorluk:`orta`,soru:`Hipospadias ile ilgili hangisi doğrudur?`,secenekler:{A:`Açıklık penisin dorsal yüzündedir`,B:`120.000 erkekte bir görülür`,C:`Sıklıkla mesane ekstrofisi ile birliktedir`,D:`Yaklaşık 1/300 erkek yenidoğanda görülür; inguinal herni ve inmemiş testis gibi anomalilerle birlikte olabilir`,E:`Üriner enfeksiyon riskini etkilemez`},dogru:`D`,aciklama:`Hipospadias 1/300 sıklıktadır; üretral ağız bazen konstriktedir ve obstrüksiyon ile enfeksiyon riskini artırır.`,sik_aciklamalari:{A:`Hipospadiasta açıklık ventraldir.`,B:`Bu sıklık epispadiasa aittir.`,C:`Mesane ekstrofisi epispadiasla birliktedir.`,D:`Doğru: sıklık ve eşlik eden anomaliler doğru verilmiştir.`,E:`Konstriksiyon enfeksiyon riskini artırır.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-66-q06`,kazanim:2,zorluk:`zor`,soru:`Hipospadiaslı bir yenidoğanda konstrikte üretral ağzın yol açabileceği komplikasyonlar hangileridir?`,secenekler:{A:`Mesane ekstrofisi`,B:`Üriner trakt obstrüksiyonu ve artmış üriner enfeksiyon riski`,C:`Peyronie hastalığı`,D:`Seminom`,E:`Hidrosel`},dogru:`B`,aciklama:`Hipospadiasta üretral ağzın daralması idrar akımını engeller ve enfeksiyon riskini artırır.`,sik_aciklamalari:{A:`Mesane ekstrofisi epispadias kompleksiyle ilişkilidir.`,B:`Doğru: konstriksiyonun doğrudan sonuçlarıdır.`,C:`Peyronie edinsel fibröz bir hastalıktır.`,D:`Seminom kriptorşidizmle ilişkilidir.`,E:`Hidrosel konstriksiyonun sonucu değildir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k02-q04`,kazanim:2,zorluk:`orta`,soru:`Yenidoğanın ventral yüzünde üretral açıklık ve zayıf idrar akımı saptanıyor. Hangi tanı-açıklama doğrudur?`,secenekler:{A:`Hipospadias dorsal açıklıktır`,B:`Hipospadias 1:120.000'dir`,C:`Konstriksiyon zararsızdır`,D:`Ek anomaliler görülmez`,E:`Ventral yüzde açıklığı olan, idrar akımı zayıf yenidoğanda hipospadias düşünülür (1:300); konstrikt ağız obstrüksiyon-enfeksiyon riski taşır ve inmemiş testis eşlik edebilir`},dogru:`E`,aciklama:`Hipospadiasta açıklık ventralde, şaft boyunca herhangi lokalizasyonda; 1:300 yenidoğan; konstriksiyon obstrüksiyon-enfeksiyon yapar; herni-inmemiş testisle birliktelik.`,sik_aciklamalari:{A:`Ventraldir; dorsal epispadiastır.`,B:`1:300'dür.`,C:`Obstrüksiyon yapar.`,D:`Herni-inmemiş testis olabilir.`,E:`Doğru: yüz-sıklık-sonuç üçlüsü tamdır.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k02-q05`,kazanim:2,zorluk:`zor`,soru:`Ventral ve dorsal açıklıklı iki yenidoğan karşılaştırılıyor. Hangi ayırım doğrudur?`,secenekler:{A:`Ventral açıklık-hipospadias (1:300), dorsal açıklık-epispadias (1:120.000) olarak ayrılır; epispadias sıklıkla mesane ekstrofisiyle birliktedir`,B:`Her ikisi de ventraldir`,C:`Sıklıkları eşittir`,D:`Epispadias ekstrofiyle ilişkisizdir`,E:`Hipospadias dorsaldir`},dogru:`A`,aciklama:`Epispadias dorsal, 1:120.000, ekstrofi kompleksi; hipospadias ventral 1:300; şiddet arttıkça epispadiasta orifis pubise yaklaşır, kaçırma artar.`,sik_aciklamalari:{A:`Doğru: yüz-sıklık-birliktelik üçlüsü tamdır.`,B:`Karşıt yüzlerdir.`,C:`300'e karşı 120.000'dir.`,D:`Kompleks yapar.`,E:`Ventraldir.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k02-q06`,kazanim:2,zorluk:`orta`,soru:`Hipospadias ve epispadias açıklık yönleri nelerdir?`,secenekler:{A:`Hipospadias ventral, epispadias dorsal açıklıktır`,B:`Hipospadias dorsaldır`,C:`Epispadias ventraldir`,D:`Hipospadias 120 binde 1'dir`,E:`Epispadias izoledir`},dogru:`A`,aciklama:`Hipospadiasta üretral ağız ventral yüzeyde şaft boyunca herhangi yerdedir, bazen konstriktedir; 300 erkekte 1 görülür ve herni-inmemiş testis eşlik edebilir. Epispadias dorsaldir, 120.000'de 1 ve ekstrofiyle birliktedir.`,sik_aciklamalari:{A:`Doğru: iki anomalinin yönü birlikte doğru verilmiştir.`,B:`Ventral yüzeydedir.`,C:`Dorsal kısımdadır.`,D:`300'de 1 görülür.`,E:`Sıklıkla ekstrofiyle birliktedir.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k02-q07`,kazanim:2,zorluk:`orta`,soru:`Hipospadias lokalizasyonu ve eşlik eden anomaliler nelerdir?`,secenekler:{A:`Açıklık tek noktadadır`,B:`Konstriksiyon olmaz`,C:`Açıklık şaft boyunca değişir; ek anomali aranır`,D:`Ek anomali olmaz`,E:`Sıklık 120 binde 1'dir`},dogru:`C`,aciklama:`Hipospadias şaft boyunca herhangi lokalizasyonda olabilir; konstriksiyon işemeyi etkiler. Birlikte inguinal herni ve inmemiş testis gibi anomaliler aranır.`,sik_aciklamalari:{A:`Şaft boyunca herhangi yerdedir.`,B:`Ağız bazen konstriktedir.`,C:`Doğru: lokalizasyon değişkenliği ve eşlik birlikte doğru verilmiştir.`,D:`Herni ve inmemiş testis eşlik edebilir.`,E:`1:300 görülür.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k02-q08`,kazanim:2,zorluk:`kolay`,soru:`Aşağıdakilerden "BPH: epidemiyoloji ve androjen bağımlılığı" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{B:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,A:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,E:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,D:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,C:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`},dogru:`B`,aciklama:`Doğru: Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,sik_aciklamalari:{B:`Doğru. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,A:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,E:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,D:`Yanlış. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,C:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`},bilgi:[24],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k02-q09`,kazanim:2,zorluk:`kolay`,soru:`Aşağıdakilerden "BPH: DHT etkisi ve α1-adrenerjik düz kas" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{B:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,A:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,D:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,E:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,C:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`},dogru:`B`,aciklama:`Doğru: DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,sik_aciklamalari:{B:`Doğru. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,A:`Yanlış. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,D:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,E:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,C:`Yanlış. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`},bilgi:[26],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k02-q10`,kazanim:2,zorluk:`orta`,soru:`"Testis atrofisi nedenleri" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{C:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,A:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,D:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,E:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,B:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`},dogru:`C`,aciklama:`Doğru: Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,sik_aciklamalari:{C:`Doğru. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,A:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,D:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,E:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,B:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k02-q11`,kazanim:2,zorluk:`orta`,soru:`"Testis atrofisi nedenleri" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,E:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,C:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,A:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`},dogru:`D`,aciklama:`Doğru: Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,sik_aciklamalari:{D:`Doğru. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,E:`Yanlış. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,C:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,A:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k02-q12`,kazanim:2,zorluk:`zor`,soru:`"Hidrosel, hematosel, şilosel ve elefantiazis" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{E:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,D:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,B:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,A:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,C:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`},dogru:`E`,aciklama:`Doğru: Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,sik_aciklamalari:{E:`Doğru. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,D:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,B:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,A:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,C:`Yanlış. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k02-q13`,kazanim:2,zorluk:`zor`,soru:`"Prostat zonal anatomisi ve histolojisi" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{A:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,E:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,B:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,D:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,C:`Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`},dogru:`A`,aciklama:`Doğru: Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,sik_aciklamalari:{A:`Doğru. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,E:`Yanlış. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,B:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,D:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,C:`Yanlış. Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`},bilgi:[20],benzer_cikmis:[]}],ilgili_cikmis:[{id:`a9a0cae034ca`,soru:`Üretranın anormal açıklığının penisin ventral yüzeyinde olması hangisi tanımlar?`,secenekler:{A:`Prepisyumun glans penisin üzerinden kolaylıkla geri çekilemediği durum`,B:`Korpus kavernozumda oluşan fibröz bantlar`,C:`Glans penis ve onu öten prepisyumun lokal inflamasyonu`,D:`Epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon`,E:`Korpus kavernozumda oluşan fibröz bantlar`},cevap:`E`}]},{no:3,metin:`Epispadiasta anormal üretral orifisin penisin dorsal kısmında olduğunu bilmek`,sorular:[{id:`k1-66-q07`,kazanim:3,zorluk:`kolay`,soru:`Epispadiasta anormal üretral orifis nerededir?`,secenekler:{A:`Perinede`,B:`Penisin ventral yüzünde`,C:`Skrotumda`,D:`Penisin dorsal yüzünde`,E:`Glansın tam ucunda (normal)`},dogru:`D`,aciklama:`Epispadiasta üretral orifis penisin dorsal kısmındadır.`,sik_aciklamalari:{A:`Perineal açıklık ağır hipospadias formudur.`,B:`Ventral açıklık hipospadiastır.`,C:`Skrotal açıklık ağır hipospadiasta görülebilir.`,D:`Doğru: epispadiasın tanımıdır.`,E:`Glans ucu normal yerleşimdir.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-66-q08`,kazanim:3,zorluk:`orta`,soru:`Epispadias sıklıkla hangi anomali ile birlikte görülür?`,secenekler:{A:`Kriptorşidizm`,B:`İnguinal herni`,C:`Mesane ekstrofisi`,D:`Varikosel`,E:`Spermatosel`},dogru:`C`,aciklama:`Epispadias sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi-epispadias kompleksi).`,sik_aciklamalari:{A:`Kriptorşidizm hipospadiasla birlikte görülebilir.`,B:`İnguinal herni hipospadiasla birlikte görülebilir.`,C:`Doğru: ekstrofi-epispadias kompleksi tanımlanmıştır.`,D:`Varikosel epispadiasla ilişkili değildir.`,E:`Spermatosel epispadiasla ilişkili değildir.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-66-q09`,kazanim:3,zorluk:`zor`,soru:`Epispadiasın şiddeti ile ilgili hangisi doğrudur?`,secenekler:{A:`Hafif olgularda idrar kaçırma kaçınılmazdır`,B:`Şiddet arttıkça orifis pubise yaklaşır ve idrar kaçırma olasılığı yükselir`,C:`Şiddet arttıkça orifis glansa yaklaşır`,D:`Şiddet idrar kontrolünü etkilemez`,E:`Epispadias 1/300 sıklıkta görülür`},dogru:`B`,aciklama:`Hafif olgularda idrar kontrolü tamdır; orifis pubise yaklaştıkça idrar kaçırma olasılığı artar.`,sik_aciklamalari:{A:`Hafif olgularda kontrol tamdır.`,B:`Doğru: şiddet ve kontinans ilişkisi doğru verilmiştir.`,C:`Şiddet arttıkça orifis pubise yaklaşır.`,D:`Şiddet kontinansı etkiler.`,E:`Epispadias yaklaşık 1/120.000 sıklıktadır.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k03-q04`,kazanim:3,zorluk:`orta`,soru:`Dorsal açıklık ve karın ön duvar defektiyle doğan bebek değerlendiriliyor. Hangi tanı doğrudur?`,secenekler:{A:`Epispadias ventraldir`,B:`Epispadias sıktır`,C:`Dorsal açıklıklı ve mesane ekstrofili yenidoğanda epispadias-ekstrofi kompleksi düşünülür (~1:120.000); hafif olguda kontrol tamdır`,D:`Ekstrofi birlikteliği yoktur`,E:`Sıklığı 1:300'dür`},dogru:`C`,aciklama:`Epispadias dorsal orifis, 1:120.000, ekstrofi-epispadias kompleksi; hafif tam kontrol, şiddetli pubise yakın-kaçıma eğilimli.`,sik_aciklamalari:{A:`Dorsaldir.`,B:`1:120.000 nadirdir.`,C:`Doğru: yüz-birliktelik-sıklık üçlüsü tamdır.`,D:`Sıklıkla birliktedir.`,E:`1:300 hipospadiastır.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k03-q05`,kazanim:3,zorluk:`zor`,soru:`İki malformasyonun şiddet-sonuç ilişkisi soruluyor. Hangi yorum doğrudur?`,secenekler:{A:`Orifis konumu önemsizdir`,B:`Pubise yakınlık kontrolü artırır`,C:`Konstriksiyon hipospadiasta koruyucudur`,D:`Şiddet prognozu etkilemez`,E:`Epispadiasta orifis pubise yaklaştıkça idrar kaçırma olasılığı yükselir; hipospadiasta konstrikt ağız obstrüksiyon-enfeksiyon yapar`},dogru:`E`,aciklama:`Şiddet-orifis konumu-kaçırma ilişkisi epispadiasta prognostiktir; hipospadiasta konstriksiyon obstrüktiftir.`,sik_aciklamalari:{A:`Konum belirleyicidir.`,B:`Kaçırmayı artırır.`,C:`Obstrüksiyon yapar.`,D:`Belirleyicidir.`,E:`Doğru: iki malformasyonun şiddet-sonuç ilişkisi tamdır.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k03-q06`,kazanim:3,zorluk:`orta`,soru:`Epispadias yönü ve birlikteliği nedir?`,secenekler:{A:`Epispadias ventraldir`,B:`Epispadias dorsal ve ekstrofili komplekstir`,C:`Epispadias sıktır`,D:`Ekstrofi eşlik etmez`,E:`Hipospadias daha nadirdir`},dogru:`B`,aciklama:`Epispadias dorsal açıklıktır, 120.000'de 1 görülür ve ekstrofi-epispadias kompleksiyle mesane ekstrofisi eşlik eder. Hipospadias ventral, 300'de 1 ve daha sıktır.`,sik_aciklamalari:{A:`Dorsal kısımdadır.`,B:`Doğru: yön, sıklık ve birliktelik birlikte doğru verilmiştir.`,C:`120.000'de 1 nadirdir.`,D:`Sıklıkla ekstrofiyle birliktedir.`,E:`Hipospadias 300'de 1 ile daha sıktır.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k03-q07`,kazanim:3,zorluk:`orta`,soru:`Ekstrofi-epispadias kompleksi nedir?`,secenekler:{A:`Kompleks ventraldir`,B:`Dorsal hipospadiastır`,C:`Kompleks izoledir`,D:`Mesane normaldir`,E:`Dorsal açıklık ekstrofi spektrumundadır`},dogru:`E`,aciklama:`Ekstrofi-epispadias kompleksi mesane ve üretra gelişim kusurudur; dorsal açıklık bu spektrumun parçasıdır. Ventral açıklık ise hipospadiastır ve izole ya da herni-kriptorşidizmle birliktedir.`,sik_aciklamalari:{A:`Dorsal spektrumdur.`,B:`Dorsal epispadiastır.`,C:`Mesane ekstrofisi eşlik eder.`,D:`Ekstrofi mesane kusurudur.`,E:`Doğru: kompleks tanımı doğru verilmiştir.`},bilgi:[1,2],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k03-q08`,kazanim:3,zorluk:`kolay`,soru:`"Prostatit klinik özellikleri ve tedavi" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{D:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,B:`Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,E:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,A:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,C:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`},dogru:`D`,aciklama:`Doğru: Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,sik_aciklamalari:{D:`Doğru. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,B:`Yanlış. Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,E:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,A:`Yanlış. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,C:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`},bilgi:[23],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k03-q09`,kazanim:3,zorluk:`orta`,soru:`"Seminom ve spermatositik seminom" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{C:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,A:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,B:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,D:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,E:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},dogru:`C`,aciklama:`Doğru: Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,sik_aciklamalari:{C:`Doğru. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,A:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,B:`Yanlış. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,D:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,E:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},bilgi:[38],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k03-q10`,kazanim:3,zorluk:`orta`,soru:`"DHT ve 5α-redüktaz tip 2" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,C:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,A:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,B:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,D:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`},dogru:`E`,aciklama:`Doğru: Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,sik_aciklamalari:{E:`Doğru. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,C:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,A:`Yanlış. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,B:`Yanlış. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,D:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k03-q11`,kazanim:3,zorluk:`zor`,soru:`"Prostat karsinomu: epidemiyoloji" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,A:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,B:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,E:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,D:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`},dogru:`C`,aciklama:`Doğru: Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,sik_aciklamalari:{C:`Doğru. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,A:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,B:`Yanlış. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,E:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,D:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`},bilgi:[29],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:4,metin:`Fimozisin prepisyumun glans penisin üzerinde kolaylıkla geri çekilemediği durum olduğunu tanımlayabilmek`,sorular:[{id:`k1-66-q10`,kazanim:4,zorluk:`kolay`,soru:`Prepisyumun glans penis üzerinden kolaylıkla geri çekilememesine ne ad verilir?`,secenekler:{A:`Hipospadias`,B:`Fimozis`,C:`Balanit`,D:`Peyronie hastalığı`,E:`Epispadias`},dogru:`B`,aciklama:`Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,sik_aciklamalari:{A:`Hipospadias üretral açıklığın ventral yerleşimidir.`,B:`Doğru: fimozisin tanımıdır.`,C:`Balanit glansın inflamasyonudur.`,D:`Peyronie korpus kavernozum fibrozisidir.`,E:`Epispadias dorsal üretral açıklıktır.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-66-q11`,kazanim:4,zorluk:`orta`,soru:`Edinsel fimozisin en sık nedeni hangisidir?`,secenekler:{A:`Varikosel`,B:`Testiküler torsiyon`,C:`Önceki balanopostit ataklarına sekonder nedbeleşme`,D:`Prostat karsinomu`,E:`Kriptorşidizm`},dogru:`C`,aciklama:`Fimozis konjenital olabilir ancak çoğu olgu tekrarlayan balanopostit sonrası nedbeleşmeyle gelişir.`,sik_aciklamalari:{A:`Varikosel skrotal venöz genişlemedir.`,B:`Torsiyon fimozis nedeni değildir.`,C:`Doğru: inflamasyon sonrası skarlaşma en sık nedendir.`,D:`Prostat karsinomu fimozis yapmaz.`,E:`Kriptorşidizm fimozis nedeni değildir.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-66-q12`,kazanim:4,zorluk:`zor`,soru:`Fimozisli sünnetsiz erkekte uzun dönemde artması beklenen risk hangisidir?`,secenekler:{A:`Varikosel`,B:`Seminom`,C:`Benign prostat hiperplazisi`,D:`Smegma birikimine bağlı balanopostit ve penis karsinomu`,E:`Spermatosel`},dogru:`D`,aciklama:`Fimozis smegma birikimini kolaylaştırır; kötü hijyen balanopostit ve sünnetsizlerde penis SCC gelişiminde rol oynar.`,sik_aciklamalari:{A:`Varikosel venöz genişlemedir.`,B:`Seminom kriptorşidizmle ilişkilidir.`,C:`BPH androjen bağımlı yaşla ilişkili hiperplazidir.`,D:`Doğru: smegma hem inflamasyon hem karsinogenezde rol oynar.`,E:`Spermatosel duktal kistik birikimdir.`},bilgi:[3,4],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k04-q04`,kazanim:4,zorluk:`orta`,soru:`Tekrarlayan prepisyum enfeksiyonlu çocukta geri çekilememe saptanıyor. Hangi tanı-mekanizma doğrudur?`,secenekler:{A:`Tekrarlayan balanopostitli sünnetsiz çocukta prepisyumun geri çekilememesi fimozistir ve çoğu vakada önceki ataklara sekonder nedbeleşmeyle gelişir`,B:`Fimozis glansın yokluğudur`,C:`Fimozis daima konjenitaldir`,D:`Nedbeleşme fimoziste rol oynamaz`,E:`Fimozis prepisyum fazlalığıdır`},dogru:`A`,aciklama:`Fimozis prepisyumun glans üzerinden geri çekilememesidir; çoğu vakada geçirilmiş balanopostite sekonder nedbeleşmeyle gelişir.`,sik_aciklamalari:{A:`Doğru: tanım-sekep üçlüsü tamdır.`,B:`Geri çekilememe tanımıdır.`,C:`Edinsel nedbeleşme sıktır.`,D:`Başlıca mekanizmadır.`,E:`Fonksiyonel tanımdır.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k04-q05`,kazanim:4,zorluk:`zor`,soru:`Sünnetsiz erkekte tekrarlayan akıntılı inflamasyon ve fimozis birlikteliği açıklanıyor. Hangi zincir doğrudur?`,secenekler:{A:`Balanit prepisyum yokluğudur`,B:`Smegma koruyucudur`,C:`Etkenler yalnızca viraldir`,D:`Sünnetsiz erkekte smegma birikimi lokal irritan-karsinojen olarak balanit-balanopostite (Candida, anaerob, Gardnerella) yol açar ve tekrarlayan ataklar fimozise belirgin nedbeleşmeyle zemin hazırlar`,E:`Balanopostit yalnızca glansı tutar`},dogru:`D`,aciklama:`Balanit glansın, balanopostit glans-prepisyumun inflamasyonudur; Candida-anaerob-Gardnerella-piyojenik etken; çoğu smegma birikimine bağlı.`,sik_aciklamalari:{A:`Glans inflamasyonudur.`,B:`İrritan-karsinojendir.`,C:`Bakteriyel-mantar etkenlidir.`,D:`Doğru: etken-irritan-sekel üçlüsü tamdır.`,E:`Glans+prepisyumdur.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k04-q06`,kazanim:4,zorluk:`orta`,soru:`Fimozis, balanit ve balanopostit tanımları nedir?`,secenekler:{A:`Fimozis çekilememe, balanit glans inflamasyonudur`,B:`Fimozis inflamasyondur`,C:`Balanit prepisyumdur`,D:`Smegma koruyucudur`,E:`Etken viraldir`},dogru:`A`,aciklama:`Fimozis prepisyumun glans üzerinde geri çekilememesidir. Balanit glansın, balanopostit glans-prepisyumun inflamasyonudur; Candida-anaerob-Gardnerella-piyojenler etkendir, çoğu smegma birikimindendir.`,sik_aciklamalari:{A:`Doğru: iki tanım birlikte doğru verilmiştir.`,B:`Fimozis mekanik çekilememe durumudur.`,C:`Balanopostit glans-prepisyumdur.`,D:`Çoğu olgu smegma birikimindendir.`,E:`Bakteriyel-mantar etkenler sayılmıştır.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k04-q07`,kazanim:4,zorluk:`orta`,soru:`Fimozisin sekonder inflamasyona etkisi nedir?`,secenekler:{A:`Fimozis inflamasyonu önler`,B:`Smegma birikmez`,C:`Fimozis smegma birikimiyle sekonder balanopostit zemini oluşturur`,D:`Hijyen önemsizdir`,E:`Fimozis koruyucudur`},dogru:`C`,aciklama:`Fimoziste prepisyum geri çekilemediğinden smegma birikir ve Candida-anaerob-piyojenik üreme kolaylaşarak sekonder balanopostit gelişir. Bu yüzden fimozis hijyen bozukluğu ve tekrarlayan inflamasyon zeminidir.`,sik_aciklamalari:{A:`Birikim inflamasyonu kolaylaştırır.`,B:`Çekilememe birikime yol açar.`,C:`Doğru: mekanik sonuç ve sekonder inflamasyon birlikte doğru verilmiştir.`,D:`Hijyen ve sünnet koruyucudur.`,E:`Tekrarlayan inflamasyon zeminidir.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k04-q08`,kazanim:4,zorluk:`kolay`,soru:`Aşağıdakilerden "Testis neoplazileri: genel özellikler ve risk faktörleri" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{E:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,C:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,B:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,A:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,D:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`},dogru:`E`,aciklama:`Doğru: Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,sik_aciklamalari:{E:`Doğru. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,C:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,B:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,A:`Yanlış. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,D:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`},bilgi:[36],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k04-q09`,kazanim:4,zorluk:`kolay`,soru:`"Kriptorşidizm: orşiopeksi ve morfoloji" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,A:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,C:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,B:`Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,E:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`},dogru:`D`,aciklama:`Doğru: Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,sik_aciklamalari:{D:`Doğru. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,A:`Yanlış. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,C:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,B:`Yanlış. Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,E:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k04-q10`,kazanim:4,zorluk:`orta`,soru:`"BPH: epidemiyoloji ve androjen bağımlılığı" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,E:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,D:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,C:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,A:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`},dogru:`B`,aciklama:`Doğru: Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,sik_aciklamalari:{B:`Doğru. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,E:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,D:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,C:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,A:`Yanlış. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`},bilgi:[24],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k04-q11`,kazanim:4,zorluk:`orta`,soru:`"Prostat karsinomu: epidemiyoloji" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{E:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,D:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,C:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,A:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`},dogru:`E`,aciklama:`Doğru: Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,sik_aciklamalari:{E:`Doğru. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,D:`Yanlış. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,C:`Yanlış. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,A:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Yanlış. Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k04-q12`,kazanim:4,zorluk:`zor`,soru:`"Epispadias" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{D:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,C:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,E:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,B:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,A:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`},dogru:`D`,aciklama:`Doğru: Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,sik_aciklamalari:{D:`Doğru. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,C:`Yanlış. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,E:`Yanlış. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,B:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,A:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k04-q13`,kazanim:4,zorluk:`zor`,soru:`"Testis tümörü belirteçleri, klinik ve tedavi" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,D:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,E:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,B:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,A:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},dogru:`C`,aciklama:`Doğru: hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,sik_aciklamalari:{C:`Doğru. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,D:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,E:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,B:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,A:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},bilgi:[40],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:5,metin:`Balanit ve balanopostitin tanımını ve smegmanın etiyolojideki rolünü açıklayabilmek`,sorular:[{id:`k1-66-q13`,kazanim:5,zorluk:`kolay`,soru:`Glans penis ve prepisyumun birlikte lokal inflamasyonuna ne ad verilir?`,secenekler:{A:`Epididimit`,B:`Balanit`,C:`Orşit`,D:`Balanopostit`,E:`Prostatit`},dogru:`D`,aciklama:`Balanit glans penisin, balanopostit glans ve prepisyumun inflamasyonudur.`,sik_aciklamalari:{A:`Epididimit epididim inflamasyonudur.`,B:`Balanit yalnızca glansın inflamasyonudur.`,C:`Orşit testis inflamasyonudur.`,D:`Doğru: iki yapının birlikte inflamasyonudur.`,E:`Prostatit prostat inflamasyonudur.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-66-q14`,kazanim:5,zorluk:`orta`,soru:`Balanit ve balanopostit olgularının çoğunun altında yatan etiyolojik faktör hangisidir?`,secenekler:{A:`HPV 16 enfeksiyonu`,B:`Smegma birikimi`,C:`Kabakulak virüsü`,D:`Tüberküloz`,E:`Androjen fazlalığı`},dogru:`B`,aciklama:`Balanit/balanopostit çoğunlukla smegma birikimine bağlıdır; Candida, anaeroblar, Gardnerella ve piyojenik bakteriler etkendir.`,sik_aciklamalari:{A:`HPV penis karsinomu ile ilişkilidir.`,B:`Doğru: kötü hijyen ve smegma temel nedendir.`,C:`Kabakulak orşit yapar.`,D:`Tüberküloz granülomatöz orşit/epididimit yapar.`,E:`Androjen fazlalığı balanit nedeni değildir.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-66-q15`,kazanim:5,zorluk:`zor`,soru:`Aşağıdakilerden hangisi balanit/balanopostit etkenlerinden biri değildir?`,secenekler:{A:`Candida albicans`,B:`Anaerob bakteriler`,C:`Gardnerella`,D:`Piyojenik bakteriler`,E:`Kabakulak virüsü`},dogru:`E`,aciklama:`Balanit etkenleri Candida, anaeroblar, Gardnerella ve piyojenik bakterilerdir; kabakulak virüsü orşit yapar.`,sik_aciklamalari:{A:`Kandida sık etkendir.`,B:`Anaerob bakteriler etkendir.`,C:`Gardnerella etkendir.`,D:`Piyojenik bakteriler etkendir.`,E:`Doğru: kabakulak virüsü testisi tutar.`},bilgi:[3,16],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k05-q04`,kazanim:5,zorluk:`orta`,soru:`Sünnetsiz hastada glans kızarıklığı ve akıntı değerlendiriliyor. Hangi açıklama doğrudur?`,secenekler:{A:`Balanit prostatit demektir`,B:`Smegma steril ve zararsızdır`,C:`Sünnet riski artırır`,D:`Glans kızarıklık-akıntılı sünnetsiz hastada balanit-balanopostit düşünülür; çoğu olgu smegma birikimine bağlıdır ve hijyen koruyucudur`,E:`Etken aranmaz`},dogru:`D`,aciklama:`Balanit glans, balanopostit glans+prepisyum inflamasyonu; çoğu olgu smegma birikimine bağlı; hijyen-sünnet koruyucudur.`,sik_aciklamalari:{A:`Glans inflamasyonudur.`,B:`Lokal irritandır.`,C:`Koruyucudur.`,D:`Doğru: tanım-etken-korunma üçlüsü tamdır.`,E:`Candida-bakteri aranır.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k05-q05`,kazanim:5,zorluk:`zor`,soru:`Kötü hijyenli yaşlı sünnetsiz hastada inflamasyon-kanser ilişkisi soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`Smegma yalnızca inflamasyon yapar`,B:`Kötü hijyen-smegma ve HPV 16-18 penis skuamöz karsinogenezinde birlikte rol oynar; >40 yaş sünnetsizlerde sıktır ve balanopostit-fimozis öyküsü zemin hazırlar`,C:`HPV penis kanserinde yoktur`,D:`Sünnet karsinom riskini artırır`,E:`Hijyen kanserden korumaz`},dogru:`B`,aciklama:`Smegma kötü hijyenle penis karsinogenezinde de rol oynar (HPV 16-18 ile); balanopostit-fimozis-karsinom zinciri hijyenle kırılır.`,sik_aciklamalari:{A:`Karsinojen de olabilir.`,B:`Doğru: irritan-viral-yaş üçlüsü tamdır.`,C:`Tip 16-18 rol oynar.`,D:`Koruyucudur.`,E:`Koruyucudur.`},bilgi:[3,4],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k05-q06`,kazanim:5,zorluk:`orta`,soru:`Balanit ve balanopostit tanımları nedir?`,secenekler:{A:`Balanit glans, balanopostit glans-prepisyum inflamasyonudur`,B:`Balanit prepisyumdur`,C:`Balanopostit yalnızca glandır`,D:`Etken viraldir`,E:`Enflamasyon değildir`},dogru:`A`,aciklama:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur. Etkenler Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakterilerdir.`,sik_aciklamalari:{A:`Doğru: iki tanım birlikte doğru verilmiştir.`,B:`Balanit glansın inflamasyonudur.`,C:`Glans ve prepisyum birlikte tutulur.`,D:`Mantar-bakteriyel etkenler sayılmıştır.`,E:`Lokal inflamasyonlardır.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k05-q07`,kazanim:5,zorluk:`orta`,soru:`Smegmanın balanit etiyolojisindeki rolü nedir?`,secenekler:{A:`Smegma koruyucudur`,B:`Smegma birikimi üremeyi kolaylaştırır; hijyen korur`,C:`Etkenler smegmadan bağımsızdır`,D:`Sünnet riski artırır`,E:`Birikim inflamasyonu önler`},dogru:`B`,aciklama:`Çoğu olgu smegma birikimine bağlıdır; biriken smegma Candida ve bakterilerin üremesini kolaylaştırır. Hijyen ve sünnet birikimi önleyerek koruyucudur.`,sik_aciklamalari:{A:`Birikim inflamasyon nedenidir.`,B:`Doğru: smegma rolü ve korunma birlikte doğru verilmiştir.`,C:`Çoğu olgu birikime bağlıdır.`,D:`Sünnet birikimi önler.`,E:`Birikim üremeyi kolaylaştırır.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k05-q08`,kazanim:5,zorluk:`kolay`,soru:`Aşağıdakilerden "BPH morfolojisi" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{D:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,A:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,B:`Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,C:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,E:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`},dogru:`D`,aciklama:`Doğru: BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,sik_aciklamalari:{D:`Doğru. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,A:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,B:`Yanlış. Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,C:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,E:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`},bilgi:[27],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k05-q09`,kazanim:5,zorluk:`orta`,soru:`"Prostatit klinik özellikleri ve tedavi" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{C:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,B:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,A:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,D:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,E:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`},dogru:`C`,aciklama:`Doğru: Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,sik_aciklamalari:{C:`Doğru. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,B:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,A:`Yanlış. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,D:`Yanlış. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,E:`Yanlış. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`},bilgi:[23],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k05-q10`,kazanim:5,zorluk:`orta`,soru:`"Peyronie hastalığı" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,E:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,A:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,B:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,D:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`},dogru:`C`,aciklama:`Doğru: Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,sik_aciklamalari:{C:`Doğru. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,E:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,A:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,B:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,D:`Yanlış. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k05-q11`,kazanim:5,zorluk:`zor`,soru:`"Penisin in situ skuamöz hücreli karsinomu (Bowen hastalığı)" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,E:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,D:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,A:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,C:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`},dogru:`B`,aciklama:`Doğru: Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,sik_aciklamalari:{B:`Doğru. Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,E:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,D:`Yanlış. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,A:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,C:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`},bilgi:[5],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:6,metin:`Penis neoplazilerinin %95'ten fazlasının skuamöz epitelden kaynaklandığını bilmek`,sorular:[{id:`k1-66-q16`,kazanim:6,zorluk:`kolay`,soru:`Penis neoplazilerinin %95'ten fazlası hangi epitelden kaynaklanır?`,secenekler:{A:`Glandüler epitel`,B:`Ürotelyum`,C:`Skuamöz epitel`,D:`Mezotel`,E:`Germ hücreleri`},dogru:`C`,aciklama:`Penis neoplazilerinin %95'ten fazlası skuamöz epitel kaynaklıdır.`,sik_aciklamalari:{A:`Glandüler tümörler nadirdir.`,B:`Ürotelyum üretra kaynaklı tümörlerin kökeni olabilir ama nadirdir.`,C:`Doğru: penis tümörlerinin büyük çoğunluğu SCC'dir.`,D:`Mezotel penis tümörü kaynağı değildir.`,E:`Germ hücreleri testis tümörlerinin kaynağıdır.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-66-q17`,kazanim:6,zorluk:`orta`,soru:`Penis skuamöz hücreli karsinomunun patogenezinde rol oynayan HPV tipleri hangileridir?`,secenekler:{A:`HPV 1 ve 2`,B:`HPV 6 ve 11`,C:`HPV 16 ve 18`,D:`HPV 3 ve 10`,E:`HPV 5 ve 8`},dogru:`C`,aciklama:`Penis karsinomu patogenezinde kötü hijyen (smegma) ve özellikle HPV 16 ve 18 rol oynar.`,sik_aciklamalari:{A:`HPV 1/2 deri siğilleri yapar.`,B:`HPV 6/11 kondilom yapar.`,C:`Doğru: yüksek riskli tiplerdir.`,D:`HPV 3/10 yassı siğiller yapar.`,E:`HPV 5/8 epidermodisplazi verrusiformis ile ilişkilidir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-66-q18`,kazanim:6,zorluk:`zor`,soru:`Penis karsinomu epidemiyolojisi ile ilgili hangisi yanlıştır?`,secenekler:{A:`Gelişmekte olan ülkelerde daha sıktır`,B:`Çoğu olgu 40 yaş üstündedir`,C:`Sünnetsiz erkeklerde daha sık görülür`,D:`Kötü hijyen (smegma) patogenezde rol oynar`,E:`Sünnetli genç erkeklerde en sık görülür`},dogru:`E`,aciklama:`Penis karsinomu çoğunlukla 40 yaş üstü sünnetsiz hastalarda görülür.`,sik_aciklamalari:{A:`Doğru ifade: gelişmekte olan ülkelerde sıktır.`,B:`Doğru ifade: ileri yaş hastalığıdır.`,C:`Doğru ifade: sünnetsizlik risk faktörüdür.`,D:`Doğru ifade: smegma birikimi rol oynar.`,E:`Yanlış ifade (aranan cevap): sünnetsiz ileri yaş erkeklerde sıktır.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k06-q04`,kazanim:6,zorluk:`orta`,soru:`Yaşlı sünnetsiz hastanın glansındaki ülsere lezyonun histolojisi tahmin ediliyor. Hangi tahmin doğrudur?`,secenekler:{A:`Penis tümörleri çoğunlukla glandülerdir`,B:`55 yaşında sünnetsiz hastanın glans lezyonunda ilk akla skuamöz hücreli karsinom gelir (%95'ten fazla); smegma ve HPV 16-18 etyolojide rol oynar`,C:`Genç sünnetlide sıktır`,D:`HPV ilişkisizdir`,E:`Gelişmiş ülkelerde sıktır`},dogru:`B`,aciklama:`%95'ten fazlası skuamöz; >40 yaş sünnetsizde, gelişmekte olan ülkelerde sık; smegma-HPV 16-18 etyolojide.`,sik_aciklamalari:{A:`Skuamözdür.`,B:`Doğru: histoloji-yaş-etyoloji üçlüsü tamdır.`,C:`>40 sünnetsizde sıktır.`,D:`Tip 16-18 rol oynar.`,E:`Gelişmekte olanda sıktır.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k06-q05`,kazanim:6,zorluk:`zor`,soru:`Şaft plağı ile itici tarzda büyüyen verrüköz lezyonun seyri karşılaştırılıyor. Hangi yorum doğrudur?`,secenekler:{A:`Evre prognozu etkilemez`,B:`Bowen daima benign kalır`,C:`Verrüköz sık metastaz yapar`,D:`Nodal hastalık prognozu iyileştirir`,E:`Şafttaki soliter plak (Bowen, in situ) %10 invazive ilerler; verrüköz lokal invaziv-metastazsızdır; lokalizede %66, inguinal nodda %27 beş yıllık yaşam vardır`},dogru:`E`,aciklama:`Erken tanı-evreleme prognozu belirler; Bowen %10 invazive ilerler; verrüköz metastaz yapmaz; lokalize %66, nodal %27.`,sik_aciklamalari:{A:`Evreye bağlıdır.`,B:`%10 ilerler.`,C:`Metastaz yapmaz.`,D:`%27'ye düşürür.`,E:`Doğru: in situ-varyant-evre üçlüsü tamdır.`},bilgi:[5,6,7],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k06-q06`,kazanim:6,zorluk:`orta`,soru:`Penis tümörlerinin kökeni ve risk grubu nedir?`,secenekler:{A:`Penis tümörleri glandülerdir`,B:`Skuamöz nadirdir`,C:`Gelişmiş ülkede sıktır`,D:`Gençte sıktır`,E:`%95'ten fazlası skuamözdür; 40 yaş üstü sünnetsizde sıktır`},dogru:`E`,aciklama:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; glandüler tümörler nadirdir. Gelişmekte olan ülkelerde daha sık, çoğu 40 yaş üstü sünnetsiz hastalarda ortaya çıkar.`,sik_aciklamalari:{A:`%95'ten fazlası skuamözdür.`,B:`Glandüler köken nadirdir.`,C:`Gelişmekte olan ülkelerde sıktır.`,D:`Çoğu 40 yaş üstüdür.`,E:`Doğru: köken oranı ve risk grubu birlikte doğru verilmiştir.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k06-q07`,kazanim:6,zorluk:`orta`,soru:`Penis karsinomu etkenleri ve korunma nedir?`,secenekler:{A:`Smegma koruyucudur`,B:`HPV ilişkisizdir`,C:`Sünnet riski artırır`,D:`Smegma irritasyonu ve HPV 16-18 patogenezde rol oynar`,E:`Hijyen önemsizdir`},dogru:`D`,aciklama:`Kötü hijyenle biriken smegma kronik irritasyon yapar; HPV özellikle tip 16 ve 18 skuamöz karsinom patogenezinde rol oynar. Sünnet ve hijyen bu yüzden koruyucudur.`,sik_aciklamalari:{A:`Birikim kronik irritasyondur.`,B:`Tip 16 ve 18 rol oynar.`,C:`Çoğu vaka sünnetsizlerdedir.`,D:`Doğru: iki etken birlikte doğru verilmiştir.`,E:`Hijyen koruyucudur.`},bilgi:[4],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k06-q08`,kazanim:6,zorluk:`kolay`,soru:`Aşağıdakilerden "Spermatosel ve varikosel" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{D:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,B:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,E:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,A:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,C:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`},dogru:`D`,aciklama:`Doğru: Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,sik_aciklamalari:{D:`Doğru. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,B:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,E:`Yanlış. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,A:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,C:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k06-q09`,kazanim:6,zorluk:`orta`,soru:`"BPH klinik özellikleri ve tedavi" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{D:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,C:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,A:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,B:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,E:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`},dogru:`D`,aciklama:`Doğru: Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,sik_aciklamalari:{D:`Doğru. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,C:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,A:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,B:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,E:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k06-q10`,kazanim:6,zorluk:`orta`,soru:`"Testis tümörü belirteçleri, klinik ve tedavi" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{D:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,C:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,A:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,E:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,B:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`},dogru:`D`,aciklama:`Doğru: hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,sik_aciklamalari:{D:`Doğru. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,C:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,A:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,E:`Yanlış. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,B:`Yanlış. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k06-q11`,kazanim:6,zorluk:`zor`,soru:`"Seminom ve spermatositik seminom" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{D:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,C:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,B:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,A:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,E:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`},dogru:`D`,aciklama:`Doğru: Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,sik_aciklamalari:{D:`Doğru. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,C:`Yanlış. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,B:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,A:`Yanlış. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,E:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`},bilgi:[38],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:7,metin:`Penisin in situ ve invaziv skuamöz hücreli karsinomunun klinik ve patolojik özelliklerini ayırt edebilmek`,sorular:[{id:`k1-66-q19`,kazanim:7,zorluk:`kolay`,soru:`Penis şaftında soliter plak şeklinde, epidermisi tam kat tutan ancak stromaya invazyon göstermeyen malign hücrelerden oluşan lezyon hangisidir?`,secenekler:{A:`Peyronie hastalığı`,B:`Verrüköz karsinom`,C:`Kondiloma akuminata`,D:`Bowen hastalığı (in situ SCC)`,E:`Balanopostit`},dogru:`D`,aciklama:`Bowen hastalığı penisin in situ skuamöz hücreli karsinomudur; olguların ~%10'unda invaziv SCC'ye ilerler.`,sik_aciklamalari:{A:`Peyronie fibröz bant hastalığıdır.`,B:`Verrüköz karsinom invaziv bir varyanttır.`,C:`Kondilom koilositozlu benign lezyondur.`,D:`Doğru: in situ SCC'nin tanımıdır.`,E:`Balanopostit inflamatuar bir durumdur.`},bilgi:[5],benzer_cikmis:[]},{id:`k1-66-q20`,kazanim:7,zorluk:`orta`,soru:`İnvaziv penis skuamöz hücreli karsinomunun tipik klinik görünümü hangisidir?`,secenekler:{A:`Korpus kavernozumda fibröz bant`,B:`Glans veya prepisyumda gri, pürtüklü papüler lezyon; ileri olguda ortası ülsere, düzensiz sınırlı endüre lezyon`,C:`Skrotumda translüminasyon veren kistik şişlik`,D:`Penis şaftında düz, ince plak, invazyonsuz`,E:`Ventral yüzde üretral açıklık`},dogru:`B`,aciklama:`İnvaziv SCC en çok glans veya prepisyumda yerleşir; ileri olguda ülsere, endüre lezyon olur.`,sik_aciklamalari:{A:`Fibröz bant Peyronie hastalığıdır.`,B:`Doğru: invaziv SCC'nin klinik görünümüdür.`,C:`Translüminasyon veren şişlik hidroseldir.`,D:`Şaftta invazyonsuz plak Bowen hastalığıdır.`,E:`Bu hipospadiastır: ventral yüzde üretral açıklık.`},bilgi:[5,6],benzer_cikmis:[]},{id:`k1-66-q21`,kazanim:7,zorluk:`zor`,soru:`Penisin in situ ve invaziv SCC'si karşılaştırıldığında hangisi doğrudur?`,secenekler:{A:`İnvaziv SCC hiçbir zaman ülsere olmaz`,B:`Bowen hastalığında stromal invazyon vardır`,C:`Bowen hastalığı şaftta soliter plak yapar ve ~%10'u invaziv SCC'ye ilerler; invaziv SCC en çok glans/prepisyumda keratinize karsinom görünümündedir`,D:`Bowen hastalığı genç sünnetli erkeklerde görülür`,E:`İnvaziv SCC'nin prognozu evreden bağımsızdır`},dogru:`C`,aciklama:`Bowen hastalığı invazyonsuz in situ lezyondur; invaziv SCC glans/prepisyumda ülsere-endüre lezyon yapar ve prognozu evreye bağlıdır.`,sik_aciklamalari:{A:`İleri olgularda ülserasyon olur.`,B:`Bowen hastalığı in situ olup invazyon göstermez.`,C:`Doğru: iki lezyonun farkları doğru verilmiştir.`,D:`Yaşlı sünnetsiz erkeklerde görülür.`,E:`Prognoz evreye bağlıdır.`},bilgi:[5,6],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k07-q04`,kazanim:7,zorluk:`orta`,soru:`Şaft plağı ile glans ülserinin histoloji farkı soruluyor. Hangi ayırım doğrudur?`,secenekler:{A:`Bowen invazivdir`,B:`İnvaziv şaftta plak yapar`,C:`Bowen stromayı tutar`,D:`İnvaziv keratinize değildir`,E:`Şafttaki tam kat atipili-invazyonsuz plak in situ (Bowen), glanstaki ülsere-endure keratinize lezyon invaziv skuamöz karsinomdur`},dogru:`E`,aciklama:`Bowen yaşlı sünnetsiz şaftında soliter plak, tam kat malign-invazyonsuz; invaziv glans-prepisyumda gri-pürtüklü papüler, ileride ülsere-endure, keratinize histolojili.`,sik_aciklamalari:{A:`İnvazyonsuzdur.`,B:`Glans-prepisyumdadir.`,C:`Stromaya inmez.`,D:`Tipik keratinizedir.`,E:`Doğru: yerleşim-invazyon-histoloji üçlüsü tamdır.`},bilgi:[5,6],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k07-q05`,kazanim:7,zorluk:`zor`,soru:`Verrüköz varyantın benign görünümlü ancak invaziv davranışı açıklanıyor. Hangi açıklama doğrudur?`,secenekler:{A:`Bowen %90 ilerler`,B:`Verrüközde sitolojik atipi belirgindir`,C:`Papiller yapılanmalı, sitolojik atipisiz, itici sınırlı verrüköz varyant lokal invazivdir ancak metastaz yapmaz; Bowen %10 invazive ilerler`,D:`Verrüköz infiltratif değildir`,E:`Bowen metastaz yapar`},dogru:`C`,aciklama:`Bowen %10 ilerler; invazivde prognoz evreye bağlı; verrüköz sitolojik atipisiz-itici tarzda, lokal invaziv-metastazsız.`,sik_aciklamalari:{A:`%10'dur.`,B:`Atipi içermez.`,C:`Doğru: morfoloji-davranış-oran üçlüsü tamdır.`,D:`Lokal invazivdir.`,E:`İn situ metastaz yapmaz.`},bilgi:[5,6,7],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k07-q06`,kazanim:7,zorluk:`orta`,soru:`İn situ ve invaziv penis karsinomu nasıl ayrılır?`,secenekler:{A:`İn situ invazyonsuz plak, invaziv ülsere keratinizedir`,B:`İn situ invazivdir`,C:`İnvaziv plaktır`,D:`Bowen gençtedir`,E:`İkisi aynıdır`},dogru:`A`,aciklama:`İn situ (Bowen) yaşlı sünnetsizde şaftta soliter plak, epidermiste tam kat malign morfoloji ve stromal invazyonsuzluktur. İnvazivde keratinizasyon, ülserasyon ve düzensizlik vardır.`,sik_aciklamalari:{A:`Doğru: iki formun invazyon-klinik farkı doğru verilmiştir.`,B:`Alttaki stromaya invazyon yapmaz.`,C:`Gri pürtüklü-ülsere lezyondur.`,D:`Yaşlı sünnetsiz erkeklerdedir.`,E:`İnvazyon varlığı ayırır.`},bilgi:[5,6],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k07-q07`,kazanim:7,zorluk:`orta`,soru:`İn situ ve invaziv lezyonların yerleşimi nedir?`,secenekler:{A:`Bowen glanstadır`,B:`İnvaziv şafttadır`,C:`Bowen şaftta plak, invaziv glans-prepisyumdadır`,D:`Yerleşim aynıdır`,E:`Bowen prepisyumdadır`},dogru:`C`,aciklama:`Bowen yaşlı sünnetsizde penis şaftında soliter plak yaparken invaziv karsinom en çok glans-prepisyumda gri pürtüklü papül olarak başlar. Yerleşim farkı muayenede lezyonun nerede aranacağını belirler.`,sik_aciklamalari:{A:`Şaftta soliter plaktır.`,B:`Glans ya da prepisyum üzerindedir.`,C:`Doğru: iki formun yerleşimi doğru karşılaştırılmıştır.`,D:`Yerleşimler farklıdır.`,E:`Şaft yerleşimlidir.`},bilgi:[5,6],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k07-q08`,kazanim:7,zorluk:`kolay`,soru:`"Prostatit klinik özellikleri ve tedavi" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,E:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,B:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,A:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,D:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`},dogru:`C`,aciklama:`Doğru: Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,sik_aciklamalari:{C:`Doğru. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,E:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,B:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,A:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,D:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`},bilgi:[23],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k07-q09`,kazanim:7,zorluk:`kolay`,soru:`Aşağıdakilerden "Skrotum neoplazileri (Percival Pott)" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{A:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,B:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,D:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,E:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,C:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`},dogru:`A`,aciklama:`Doğru: Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,sik_aciklamalari:{A:`Doğru. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,B:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,D:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,E:`Yanlış. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,C:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k07-q10`,kazanim:7,zorluk:`orta`,soru:`"Torsiyon: klinik ve tedavi" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{C:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,B:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,E:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,A:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,D:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`},dogru:`C`,aciklama:`Doğru: Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,sik_aciklamalari:{C:`Doğru. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,B:`Yanlış. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,E:`Yanlış. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,A:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,D:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k07-q11`,kazanim:7,zorluk:`orta`,soru:`"Seminom ve spermatositik seminom" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,A:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,D:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,B:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,C:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`},dogru:`E`,aciklama:`Doğru: Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,sik_aciklamalari:{E:`Doğru. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,A:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,D:`Yanlış. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,B:`Yanlış. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,C:`Yanlış. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`},bilgi:[38],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k07-q12`,kazanim:7,zorluk:`zor`,soru:`"i(12p) ve intratubuler germ hücre neoplazisi" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,E:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,A:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,C:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,D:`Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`},dogru:`B`,aciklama:`Doğru: 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,sik_aciklamalari:{B:`Doğru. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,E:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,A:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,C:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,D:`Yanlış. Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`},bilgi:[37],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k07-q13`,kazanim:7,zorluk:`zor`,soru:`"Penisin in situ skuamöz hücreli karsinomu (Bowen hastalığı)" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{B:`Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,E:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,D:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,A:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,C:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`},dogru:`B`,aciklama:`Doğru: Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,sik_aciklamalari:{B:`Doğru. Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,E:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,D:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,A:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,C:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`},bilgi:[5],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:8,metin:`Penis karsinomunun prognozunu ve verrüköz karsinomun biyolojik davranışını açıklayabilmek`,sorular:[{id:`k1-66-q22`,kazanim:8,zorluk:`kolay`,soru:`Verrüköz karsinomun biyolojik davranışı ile ilgili hangisi doğrudur?`,secenekler:{A:`Her zaman inguinal lenf nodlarına yayılır`,B:`Erken ve yaygın metastaz yapar`,C:`Benign bir siğildir`,D:`Lokal invazivdir ancak metastaz yapmaz`,E:`İn situ karsinomdur`},dogru:`D`,aciklama:`Verrüköz karsinom papiller, sitolojik atipisi minimal, itici sınırlı bir SCC varyantıdır; lokal invazivdir, metastaz yapmaz.`,sik_aciklamalari:{A:`Lenf nodu metastazı beklenmez.`,B:`Metastaz yapmaz: erken ve yaygın metastaz yapar.`,C:`Lokal invaziv bir karsinomdur.`,D:`Doğru: verrüköz karsinomun davranışıdır.`,E:`İtici tarzda invaziv büyür.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-66-q23`,kazanim:8,zorluk:`orta`,soru:`İnguinal lenf nodu metastazı olan penis SCC'sinde 5 yıllık yaşam oranı yaklaşık ne kadardır?`,secenekler:{A:`%66`,B:`%27`,C:`%95`,D:`%5`,E:`%100`},dogru:`B`,aciklama:`Lokalize lezyonlarda 5 yıllık yaşam %66 iken inguinal lenf nodu metastazında %27'ye düşer.`,sik_aciklamalari:{A:`%66 lokalize hastalığa aittir.`,B:`Doğru: nodal metastazda sağkalım belirgin düşer.`,C:`%95 bu tablo için çok yüksektir.`,D:`%5 verilen veriye uymaz.`,E:`%100 gerçekçi değildir.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-66-q24`,kazanim:8,zorluk:`zor`,soru:`Verrüköz karsinomun histolojik özellikleri hangisidir?`,secenekler:{A:`Koilositoz ile sınırlı benign papillom`,B:`Belirgin anaplazi ve infiltratif tek hücreler`,C:`Papiller yapılanma, belirgin sitolojik atipi olmaması ve derin, yuvarlak, itici sınırlar`,D:`Kazeöz nekrozlu granülomlar`,E:`Glikojenden zengin berrak hücreler ve lenfosit infiltrasyonu`},dogru:`C`,aciklama:`Verrüköz karsinom papiller, atipisi minimal, itici sınırlı bir varyanttır.`,sik_aciklamalari:{A:`Kondilom benign lezyondur.`,B:`Belirgin anaplazi klasik SCC'yi düşündürür.`,C:`Doğru: tanımlayıcı histolojidir.`,D:`Granülomlar tüberkülozu düşündürür.`,E:`Bu seminomun histolojisidir.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k08-q04`,kazanim:8,zorluk:`orta`,soru:`Nodal pozitif ve lokalize iki hastanın sağkalımı karşılaştırılıyor. Hangi bilgi doğrudur?`,secenekler:{A:`İnguinal nodu pozitif penis kanserlide beş yıllık yaşam %27'ye düşerken lokalizede %66'dır; bu yüzden evreleme ve erken tanı belirleyicidir`,B:`Nodal hastalık fark etmez`,C:`Lokalize %27'dir`,D:`Evreleme gereksizdir`,E:`Prognoz histolojiden bağımsızdır`},dogru:`A`,aciklama:`Prognoz evreye bağlı: lokalize %66, inguinal metastazda %27 beş yıllık yaşam.`,sik_aciklamalari:{A:`Doğru: evre-sağkalım ikilisi tamdır.`,B:`%66'dan %27'ye düşürür.`,C:`%66'dır.`,D:`Belirleyicidir.`,E:`Evreye bağlıdır.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k08-q05`,kazanim:8,zorluk:`zor`,soru:`Atipisiz papiller lezyonun yönetimi tartışılıyor. Hangi yaklaşım doğrudur?`,secenekler:{A:`Verrüköz uzak metastazlıdır`,B:`Geniş papiller-itici lezyonun biyopsisinde sitolojik atipi yokluğu verrüközü düşündürür; lokal invazivdir, metastaz yapmaz ve geniş eksizyon gerekir`,C:`Verrüköz sistemik kemoterapi gerektirir`,D:`Atipi verrüközde şarttır`,E:`Eksizyon kontrendikedir`},dogru:`B`,aciklama:`Verrüköz derin-yuvarlak-itici, atipisiz; metastazsız ama lokal destrüktif; eksizyonla tedavi edilir.`,sik_aciklamalari:{A:`Metastaz yapmaz.`,B:`Doğru: morfoloji-davranış-tedavi üçlüsü tamdır.`,C:`Lokal tedavidir.`,D:`İçermez.`,E:`Eksizyonla tedavi edilir.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k08-q06`,kazanim:8,zorluk:`orta`,soru:`Penis karsinomu prognozu ve verrüköz davranış nedir?`,secenekler:{A:`Prognoz grade bağımsızdır`,B:`Prognoz evrelidir; verrüköz itici-atipisizdir`,C:`Verrüköz agresiftir`,D:`Verrüköz infiltratiftir`,E:`Evre önemsizdir`},dogru:`B`,aciklama:`Prognoz evreye bağlıdır; ileri lezyon ülsere-endure ve keratinizedir. Verrüköz sitolojik atipi içermeyen, yuvarlak itici sınırlı, derin papiller varyanttır ve infiltratif metastatik davranış göstermez.`,sik_aciklamalari:{A:`Evreye bağlıdır.`,B:`Doğru: prognoz ilkesi ve varyant davranışı birlikte doğru verilmiştir.`,C:`Atipi içermeyen itici varyanttır.`,D:`Sınırları yuvarlak itici tarzdadır.`,E:`Evre belirleyicidir.`},bilgi:[6,7],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k08-q07`,kazanim:8,zorluk:`orta`,soru:`Verrüköz karsinomun biyolojik davranışı nedir?`,secenekler:{A:`Verrüköz atipilidir`,B:`Verrüköz infiltratiftir`,C:`Verrüköz metastatiktir`,D:`Verrüköz atipisiz itici sınırlı, metastazsız varyanttır`,E:`Verrüköz yüzeyseldir`},dogru:`D`,aciklama:`Verrüköz karsinom papiller yapılanmalı, sitolojik atipi içermeyen, derin ve yuvarlak itici sınırlı varyanttır; infiltratif yayılım ve uzak metastaz davranışı göstermez. Bu yüzden eksizyonla kontrolü klasik invazivden daha yüz güldürücüdür.`,sik_aciklamalari:{A:`Gerçekte sitolojik atipi içermez.`,B:`Sınırları yuvarlak itici tarzdadır.`,C:`Uzak metastaz davranışı göstermez.`,D:`Doğru: varyantın üç özelliği birlikte doğru verilmiştir.`,E:`Derin varyanttır.`},bilgi:[7],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k08-q08`,kazanim:8,zorluk:`kolay`,soru:`Aşağıdakilerden "DHT ve 5α-redüktaz tip 2" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{B:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,A:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,E:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,C:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,D:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},dogru:`B`,aciklama:`Doğru: Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,sik_aciklamalari:{B:`Doğru. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,A:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,E:`Yanlış. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,C:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,D:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},bilgi:[25],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k08-q09`,kazanim:8,zorluk:`orta`,soru:`"Prostat karsinomu morfolojisi ve PİN" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{D:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,E:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,A:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,C:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,B:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`},dogru:`D`,aciklama:`Doğru: Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,sik_aciklamalari:{D:`Doğru. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,E:`Yanlış. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,A:`Yanlış. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,C:`Yanlış. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,B:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k08-q10`,kazanim:8,zorluk:`zor`,soru:`"Nonspesifik epididimit ve orşit, kabakulak orşiti" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,C:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,B:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,D:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,E:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`},dogru:`A`,aciklama:`Doğru: Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,sik_aciklamalari:{A:`Doğru. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,C:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,B:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,D:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,E:`Yanlış. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`},bilgi:[16],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:9,metin:`Peyronie hastalığının korpus kavernozumda oluşan fibröz bantlar sonucu geliştiğini bilmek`,sorular:[{id:`k1-66-q25`,kazanim:9,zorluk:`kolay`,soru:`Peyronie hastalığı hangi yapıda oluşan fibröz bantlar sonucu gelişir?`,secenekler:{A:`Prostat periferik zonu`,B:`Tunika vajinalis`,C:`Spermatik kord`,D:`Korpus kavernozum`,E:`Epididim`},dogru:`D`,aciklama:`Peyronie hastalığı korpus kavernozumdaki fibröz bantlarla gelişir; fibromatozis varyantı olarak kabul edilebilir.`,sik_aciklamalari:{A:`Periferik zon prostat karsinomunun yerleşim yeridir.`,B:`Tunika vajinalis hidrosel ile ilişkilidir.`,C:`Spermatik kord varikosel ve torsiyonla ilişkilidir.`,D:`Doğru: korpus kavernozum tutulur.`,E:`Epididim epididimitle ilişkilidir.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-66-q26`,kazanim:9,zorluk:`orta`,soru:`Peyronie hastalığının klinik bulguları hangileridir?`,secenekler:{A:`Ağrısız hematüri`,B:`Peniste eğrilik ve cinsel ilişki sırasında ağrı`,C:`Skrotal translüminasyon`,D:`Ani başlangıçlı skrotal ağrı`,E:`Gece idrara kalkma`},dogru:`B`,aciklama:`Fibröz bantlar peniste eğrilik ve ilişki sırasında ağrı yapar.`,sik_aciklamalari:{A:`Ağrısız hematüri ürotelyal karsinomu düşündürür.`,B:`Doğru: tipik klinik bulgulardır.`,C:`Translüminasyon hidroselde görülür.`,D:`Ani skrotal ağrı torsiyonu düşündürür.`,E:`Noktüri BPH bulgusudur.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-66-q27`,kazanim:9,zorluk:`zor`,soru:`Peyronie hastalığının sınıflandırılmasında bazı kaynakların kabul ettiği yaklaşım hangisidir?`,secenekler:{A:`Bakteriyel bir enfeksiyon`,B:`Bir germ hücreli tümör`,C:`Fibromatozisin bir varyantı`,D:`Konjenital bir üretra anomalisi`,E:`Bir prostat hiperplazisi formu`},dogru:`C`,aciklama:`Etiyolojisi tam bilinmeyen Peyronie hastalığını bazı kaynaklar fibromatozis varyantı olarak sınıflar.`,sik_aciklamalari:{A:`Enfeksiyöz değildir.`,B:`Tümör değildir: bir germ hücreli tümör.`,C:`Doğru: fibroproliferatif bir süreçtir.`,D:`Konjenital üretral anomali değildir.`,E:`Prostat ile ilişkili değildir.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k09-q04`,kazanim:9,zorluk:`orta`,soru:`Ereksiyonda eğrilik yakınmalı hastada tanı soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`Peyronie üretral darlıktır`,B:`Peyronie enfeksiyözdür`,C:`Peyronie maligndir`,D:`Ereksiyonda eğrilik ve ilişkide ağrılı hastada korpus kavernozumdaki fibröz bantlara bağlı Peyronie düşünülür`,E:`Peyronie konjenitaldir`},dogru:`D`,aciklama:`Korpus kavernozumda fibröz bantlar; eğrilik-ilişkide ağrı; fibromatozis varyantı sayılır.`,sik_aciklamalari:{A:`Kavernozal fibrözdür.`,B:`Fibromatozis varyantıdır.`,C:`Benign fibrözdür.`,D:`Doğru: lezyon-klinik ikilisi tamdır.`,E:`Edinsel fibrözdür.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k09-q05`,kazanim:9,zorluk:`zor`,soru:`Peyronie plağının doğası soruluyor. Hangi bilgi doğrudur?`,secenekler:{A:`Etyolojisi kesindir`,B:`Plaklar maligndir`,C:`Ağrı ereksiyondan bağımsızdır`,D:`Fibröz bantlar kavernozum dışındadır`,E:`Nedeni tam bilinmeyen kavernozal fibröz bantlar fibromatozis varyantı sayılır ve ereksiyonda eğrilik-ağrı yapar`},dogru:`E`,aciklama:`Etyoloji tam bilinmez; plaklar fibromatozis spektrumunda; ağrı-eğrilik ereksiyonda belirginleşir.`,sik_aciklamalari:{A:`Tam bilinmez.`,B:`Benign fibrözdür.`,C:`İlişkide belirgindir.`,D:`Kavernozumdadır.`,E:`Doğru: etyoloji-sınıf-klinik üçlüsü tamdır.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k09-q06`,kazanim:9,zorluk:`orta`,soru:`Peyronie, spermatosel ve varikosel tanımları nedir?`,secenekler:{A:`Peyronie enfeksiyözdür`,B:`Peyronie venözdür`,C:`Spermatosel venözdür`,D:`Varikosel kistiktir`,E:`Peyronie fibröz bant; spermatosel kistik, varikosel venözdür`},dogru:`E`,aciklama:`Peyronie korpus kavernozumdaki fibröz bantlardandır; etiyoloji bilinmemekle fibromatozis varyantı sayılır. Spermatosel efferent-retede semenin kistik birikimi, varikosel kordda genişlemiş venlerdir.`,sik_aciklamalari:{A:`Fibromatozis varyantı sayılır.`,B:`Fibröz bant hastalığıdır.`,C:`Semenin kistik birikimidir.`,D:`Genişlemiş venöz yapılardır.`,E:`Doğru: üç skrotal-penil tanım birlikte doğru verilmiştir.`},bilgi:[8,11],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k09-q07`,kazanim:9,zorluk:`orta`,soru:`Peyronie kliniği ve sınıflaması nedir?`,secenekler:{A:`Bantlar eğrilik yapmaz`,B:`Peyronie enfeksiyözdür`,C:`Fibröz bant eğrilik-ağrı yapar; etiyoloji fibromatozislidir`,D:`Plak hissedilmez`,E:`Peyronie maligndir`},dogru:`C`,aciklama:`Fibröz bantlar ereksiyonda penil eğriliğe ve ağrıya yol açar; etiyoloji tam bilinmemekle fibromatozis varyantı sayılır. Palpasyonda kavernozal plak hissedilir.`,sik_aciklamalari:{A:`Eğriliğe neden olur.`,B:`Fibromatozis varyantı sayılır.`,C:`Doğru: klinik sonuç ve sınıflama birlikte doğru verilmiştir.`,D:`Fibröz plak palpe edilir.`,E:`Benign fibröz hastalıktır.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k09-q08`,kazanim:9,zorluk:`kolay`,soru:`"BPH: DHT etkisi ve α1-adrenerjik düz kas" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{D:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,C:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,E:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,B:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,A:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`},dogru:`D`,aciklama:`Doğru: DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,sik_aciklamalari:{D:`Doğru. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,C:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,E:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,B:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,A:`Yanlış. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`},bilgi:[26],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k09-q09`,kazanim:9,zorluk:`orta`,soru:`"DHT ve 5α-redüktaz tip 2" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,C:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,D:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,B:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,E:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`},dogru:`A`,aciklama:`Doğru: Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,sik_aciklamalari:{A:`Doğru. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,C:`Yanlış. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,D:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,B:`Yanlış. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,E:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k09-q10`,kazanim:9,zorluk:`orta`,soru:`"Prostat karsinomu patogenezi ve genetiği" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{D:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,C:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,B:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,E:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,A:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`},dogru:`D`,aciklama:`Doğru: Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,sik_aciklamalari:{D:`Doğru. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,C:`Yanlış. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,B:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,E:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,A:`Yanlış. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k09-q11`,kazanim:9,zorluk:`zor`,soru:`"Verrüköz karsinom" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,A:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,E:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,C:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,D:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`},dogru:`B`,aciklama:`Doğru: Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,sik_aciklamalari:{B:`Doğru. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,A:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,E:`Yanlış. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,C:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,D:`Yanlış. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`},bilgi:[7],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:10,metin:`Skrotal büyüme nedenlerini (hidrosel, hematosel, şilosel, elefantiazis, spermatosel, varikosel) açıklayabilmek`,sorular:[{id:`k1-66-q28`,kazanim:10,zorluk:`kolay`,soru:`Skrotal büyümenin en sık nedeni hangisidir?`,secenekler:{A:`Hematosel`,B:`Hidrosel`,C:`Şilosel`,D:`Elefantiazis`,E:`Seminom`},dogru:`B`,aciklama:`Tunika vajinalis içinde seröz sıvı birikimi olan hidrosel skrotal büyümenin en sık nedenidir.`,sik_aciklamalari:{A:`Hematosel kan birikimidir ve daha seyrektir.`,B:`Doğru: en sık nedendir ve translüminasyon verir.`,C:`Şilosel lenf birikimidir ve seyrektir.`,D:`Elefantiazis ileri lenfatik obstrüksiyonda görülür.`,E:`Seminom solid kitle yapar ve daha seyrektir.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-66-q29`,kazanim:10,zorluk:`orta`,soru:`Hidroseli hematosel ve şiloselden ayırmada kullanılan özellik hangisidir?`,secenekler:{A:`Serum AFP düzeyi`,B:`Ağrı varlığı`,C:`Serum PSA düzeyi`,D:`Translüminasyon (ışık geçirgenliği)`,E:`Hastanın yaşı`},dogru:`D`,aciklama:`Hidrosel seröz sıvı içerdiğinden translüminasyon verir; kan, püy ve lenf sıvısı ışığı geçirmez.`,sik_aciklamalari:{A:`AFP germ hücreli tümör belirtecidir.`,B:`Ağrı spesifik değildir.`,C:`PSA prostat belirtecidir.`,D:`Doğru: translüminasyon ayırıcı özelliktir.`,E:`Yaş tek başına ayırıcı değildir.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-66-q30`,kazanim:10,zorluk:`zor`,soru:`Skrotal patolojiler ile tanımları eşleştirildiğinde hangisi yanlıştır?`,secenekler:{A:`Spermatosel – dilate efferent duktus veya rete testiste semen birikimi`,B:`Varikosel – spermatik kordda genişlemiş venler, infertilite ile ilişkili olabilir`,C:`Şilosel – tunika vajinalis içinde lenf birikimi`,D:`Hematosel – tunika vajinalis içinde kan birikimi`,E:`Hidrosel – translüminasyon vermeyen solid testis kitlesi`},dogru:`E`,aciklama:`Hidrosel seröz sıvı birikimidir ve translüminasyon verir; translüminasyon vermeyen solid kitle testis tümörünü düşündürür.`,sik_aciklamalari:{A:`Doğru eşleştirme: spermatoselin tanımıdır.`,B:`Doğru eşleştirme: varikosel cerrahi düzeltilebilir.`,C:`Doğru eşleştirme: şiloselin tanımıdır.`,D:`Doğru eşleştirme: hematoselin tanımıdır.`,E:`Yanlış eşleştirme (aranan cevap): hidrosel kistik ve translüminasyon pozitiftir.`},bilgi:[10,11,40],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k10-q04`,kazanim:10,zorluk:`orta`,soru:`Ağrısız translüminens skrotal şişlikli hastada ayırıcı tanı soruluyor. Hangi eşleşme doğrudur?`,secenekler:{A:`Skrotal büyümenin en sık nedeni tümördür`,B:`Hidrosel translüminens değildir`,C:`Işık geçiren (translüminens) ağrısız skrotal şişlik hidroseldir (en sık neden); kan birikimi hematosel, lenf birikimi şiloseldir`,D:`Hematosel seröz sıvıdır`,E:`Şilosel kandır`},dogru:`C`,aciklama:`Hidrosel tunika vajinaliste seröz, en sık neden, translüminens; hematosel kan, şilosel lenf; elefantiazis ileri lenfatik obstrüksiyon.`,sik_aciklamalari:{A:`Hidroseldir.`,B:`Translüminensdir.`,C:`Doğru: test-sıvı üçlüsü tamdır.`,D:`Kandır.`,E:`Lenftir.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k10-q05`,kazanim:10,zorluk:`zor`,soru:`İnfertilite araştırmasında skrotal muayene bulguları yorumlanıyor. Hangi yorum doğrudur?`,secenekler:{A:`İnfertil çiftte kordda varikosel (genişlemiş venler) saptanması cerrahi düzeltilebilir nedendir; üst polde kistik kitle spermatoseldir; hidrosel tümör-enfeksiyon yanıtı da olabilir`,B:`Varikosel arteriyeldir`,C:`Spermatosel maligndir`,D:`Varikosel infertiliteyle ilişkisizdir`,E:`Hidrosel daima idiopatiktir`},dogru:`A`,aciklama:`Spermatosel efferent-rete kistik semen birikimi; varikosel kordda genişlemiş venler, infertiliteyle ilişkili-düzeltilebilir; hidrosel komşu enfeksiyon-tümöre yanıt veya idiopatik.`,sik_aciklamalari:{A:`Doğru: venöz-kistik-reaktif üçlüsü tamdır.`,B:`Venözdür.`,C:`Benign kisttir.`,D:`İlişkili olabilir.`,E:`Yanıt da olabilir.`},bilgi:[10,11],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k10-q06`,kazanim:10,zorluk:`orta`,soru:`Skrotal büyüme nedenleri sıvı tipine göre nelerdir?`,secenekler:{A:`En sık hematoseldir`,B:`Sıvı tipine göre altı neden ayrılır; hidrosel translüminensdir`,C:`Şilosel serözdür`,D:`Translüminens ayrım yapmaz`,E:`Varikosel lenfatiktir`},dogru:`B`,aciklama:`Skrotal büyümede seröz hidrosel en sık, kan hematosel, lenf şilosel-elefantiazis, semen spermatosel, ven varikoseldir. Translüminens hidroseli diğerlerinden ayırır.`,sik_aciklamalari:{A:`En fazla sebep hidroseldir.`,B:`Doğru: altı nedenin sıvı eşleşmesi doğru verilmiştir.`,C:`Lenf sıvısı birikimidir.`,D:`Püy-kan-lenften ayırır.`,E:`Venöz yapılardır.`},bilgi:[10,11],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k10-q07`,kazanim:10,zorluk:`orta`,soru:`Elefantiazis, hematosel ve şilosel nedenleri nelerdir?`,secenekler:{A:`Elefantiazis akutdur`,B:`Hematosel lenfatiktir`,C:`Şilosel travmasızdır`,D:`Elefantiazis kronik obstrüksiyon, hematosel kan, şilosel lenftir`,E:`Spermatosel venözdür`},dogru:`D`,aciklama:`Elefantiazis ileri lenfatik obstrüksiyondur; hematosel travma-kanama, şilosel lenf kaçağı sonrası gelişir. Spermatosel rete-efferent dilatasyonudur.`,sik_aciklamalari:{A:`İleri obstrüksiyon sonucudur.`,B:`Kan birikimidir.`,C:`Lenf sıvısı birikimidir.`,D:`Doğru: üç tablonun nedeni birlikte doğru verilmiştir.`,E:`Semenin kistik birikimidir.`},bilgi:[10,11],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k10-q08`,kazanim:10,zorluk:`kolay`,soru:`"Prostat karsinomu morfolojisi ve PİN" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,C:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,E:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,B:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,A:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},dogru:`D`,aciklama:`Doğru: Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,sik_aciklamalari:{D:`Doğru. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,C:`Yanlış. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,E:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,B:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,A:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},bilgi:[31],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k10-q09`,kazanim:10,zorluk:`kolay`,soru:`Aşağıdakilerden "İnvaziv skuamöz hücreli karsinom ve prognoz" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{B:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,C:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,E:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,A:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,D:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`},dogru:`B`,aciklama:`Doğru: En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,sik_aciklamalari:{B:`Doğru. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,C:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,E:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,A:`Yanlış. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,D:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`},bilgi:[6],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k10-q10`,kazanim:10,zorluk:`orta`,soru:`"Nonspesifik epididimit ve orşit, kabakulak orşiti" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{E:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,B:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,C:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,D:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,A:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`},dogru:`E`,aciklama:`Doğru: Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,sik_aciklamalari:{E:`Doğru. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,B:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,C:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,D:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,A:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k10-q11`,kazanim:10,zorluk:`orta`,soru:`"Prostat karsinomu klinik özellikleri ve metastaz" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{D:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,A:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,C:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,E:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,B:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`},dogru:`D`,aciklama:`Doğru: Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,sik_aciklamalari:{D:`Doğru. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,A:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,C:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,E:`Yanlış. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,B:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`},bilgi:[33],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k10-q12`,kazanim:10,zorluk:`zor`,soru:`"Hidrosel, hematosel, şilosel ve elefantiazis" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,E:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,D:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,C:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`},dogru:`A`,aciklama:`Doğru: Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,sik_aciklamalari:{A:`Doğru. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,E:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,D:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,C:`Yanlış. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k10-q13`,kazanim:10,zorluk:`zor`,soru:`"Granülomatöz orşit (tüberküloz)" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{E:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,A:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,D:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,C:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,B:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`},dogru:`E`,aciklama:`Doğru: Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,sik_aciklamalari:{E:`Doğru. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,A:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,D:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,C:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,B:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`},bilgi:[17],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:11,metin:`Skrotumun çevresel kaynaklı skuamöz hücreli karsinomunun tarihsel önemini bilmek`,sorular:[{id:`k1-66-q31`,kazanim:11,zorluk:`kolay`,soru:`Skrotumun skuamöz hücreli karsinomu tarihsel olarak hangi meslek grubunda yüksek oranda gözlenmiştir?`,secenekler:{A:`Madenciler`,B:`Baca temizleyicileri`,C:`Çiftçiler`,D:`Boya işçileri`,E:`Radyoloji teknisyenleri`},dogru:`B`,aciklama:`Sir Percival Pott, baca temizleyicilerinde skrotal SCC'yi yüksek oranda gözlemiştir.`,sik_aciklamalari:{A:`Madencilik bu tarihsel gözlemle ilişkili değildir.`,B:`Doğru: kurum maruziyeti ile ilişkilidir.`,C:`Çiftçilik bu tarihsel gözlemle ilişkili değildir.`,D:`Boya işçileri mesane kanseri (aromatik aminler) ile ilişkilidir.`,E:`Radyoloji teknisyenleri bu gözlemle ilişkili değildir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-66-q32`,kazanim:11,zorluk:`orta`,soru:`Percival Pott'un skrotal karsinom gözleminin tarihsel önemi nedir?`,secenekler:{A:`İlk kalıtsal kanser sendromunun bulunması`,B:`İlk viral kanserin tanımlanması`,C:`Çevresel etkilerle ilişkili ilk insan malignitesini temsil etmesi`,D:`İlk tümör belirtecinin keşfi`,E:`İlk kemoterapinin uygulanması`},dogru:`C`,aciklama:`Baca temizleyicilerindeki skrotal SCC, mesleki/çevresel karsinogenezin tarihteki ilk kanıtıdır.`,sik_aciklamalari:{A:`Kalıtsal bir sendrom değildir.`,B:`Viral etiyoloji ile ilgili değildir.`,C:`Doğru: çevresel karsinogenezin ilk örneğidir.`,D:`Tümör belirteci ile ilişkili değildir.`,E:`Tedavi ile ilgili bir gözlem değildir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-66-q33`,kazanim:11,zorluk:`zor`,soru:`Skrotum neoplazileri ile ilgili hangisi doğrudur?`,secenekler:{A:`Çevresel faktörlerle hiçbir ilişkisi yoktur`,B:`Skrotumun en sık tümörü seminomdur`,C:`Skrotal tümörlerin çoğu adenokarsinomdur`,D:`Az görülür; en sık tipi skuamöz hücreli karsinomdur`,E:`Çocuklukta sık görülür`},dogru:`D`,aciklama:`Skrotal kese neoplazileri nadirdir; en çok görülen tipi skuamöz hücreli karsinomdur.`,sik_aciklamalari:{A:`Çevresel kurum maruziyetiyle ilişkisi tarihsel olarak gösterilmiştir.`,B:`Seminom testis tümörüdür.`,C:`Adenokarsinom skrotumda tipik değildir.`,D:`Doğru: skrotum derisinin en sık malign tümörü SCC'dir.`,E:`Çocuklukta sık değildir.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k11-q04`,kazanim:11,zorluk:`orta`,soru:`Meslek hastalıkları tarihinde skrotum kanserinin yeri soruluyor. Hangi bilgi doğrudur?`,secenekler:{A:`Skrotum kanseri sıktır`,B:`Çevresel ilişki yoktur`,C:`İlk tanımlayan Hipokrat'tır`,D:`Mesleksel kanser kavramı yenidir`,E:`Baca temizleyicilerinde skrotal skuamöz karsinomu tanımlayan Percival Pott'un gözlemi çevresel etkilerle ilişkili ilk insan malignitesidir`},dogru:`E`,aciklama:`Pott'un baca temizleyicilerinde gözlediği skrotal skuamöz karsinom çevresel ilk insan malignitesidir; mesleksel karsinojenez kanıtı.`,sik_aciklamalari:{A:`Az rastlanır.`,B:`Çevreseldir.`,C:`Pott'tur.`,D:`Tarihi ilk kanıttır.`,E:`Doğru: kişi-meslek-ilk üçlüsü tamdır.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k11-q05`,kazanim:11,zorluk:`zor`,soru:`Kurum maruziyetinin karsinojenez kavramına katkısı soruluyor. Hangi yorum doğrudur?`,secenekler:{A:`Kurum koruyucudur`,B:`Skrotumda glandüler sıktır`,C:`Tarihsel değeri yoktur`,D:`Skrotal kesede en çok skuamöz hücreli karsinom görülmesi ve kurum maruziyetiyle ilişkisi mesleksel-çevresel karsinojenez kavramının doğmasına yol açmıştır`,E:`Modern korunma gereksizdir`},dogru:`D`,aciklama:`Kurum maruziyeti-skuamöz karsinom ilişkisi modern mesleksel korunmanın temelidir; skrotal kese neoplazilerinde en çok skuamöz görülür.`,sik_aciklamalari:{A:`Karsinojendir.`,B:`Skuamözdür.`,C:`İlk kanıttır.`,D:`Doğru: histoloji-maruziyet-kavram üçlüsü tamdır.`,E:`Temelidir.`},bilgi:[9,4],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k11-q06`,kazanim:11,zorluk:`orta`,soru:`Pott gözleminin tarihsel önemi nedir?`,secenekler:{A:`Pott çevresel ilk maligniteyi skrotumda tanımladı`,B:`Pott enfeksiyon tanımladı`,C:`Skrotumda melanom sıktır`,D:`Çevresel ilişki yoktur`,E:`Skrotal tümör sıktır`},dogru:`A`,aciklama:`Pott baca temizleyicilerinde skrotal skuamöz karsinomu tanımlayarak çevresel ilk insan malignitesini bildirmiştir. Skrotal neoplaziler az, en sık skuamözdür.`,sik_aciklamalari:{A:`Doğru: tarihsel önem birlikte doğru verilmiştir.`,B:`Skuamöz karsinomu tanımladı.`,C:`En sık skuamözdür.`,D:`Çevresel etkilerle ilk malignitedir.`,E:`Az rastlanır.`},bilgi:[9],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k11-q07`,kazanim:11,zorluk:`orta`,soru:`Skrotal ve penil karsinom etkenleri nelerdir?`,secenekler:{A:`Kurum koruyucudur`,B:`Mesleksel kanser yoktur`,C:`Kurum skrotal, smegma-HPV penil karsinom etkenidir`,D:`Penis çevreselden etkilenmez`,E:`HPV skrotaldır`},dogru:`C`,aciklama:`Baca temizleyicilerinde kurum maruziyeti skrotal kansere yol açtı; bu mesleksel kanser kavramının doğuşudur. Peniste de smegma-HPV çevresel-viral etkenlerdir.`,sik_aciklamalari:{A:`Maruziyet kansere yol açtı.`,B:`İlk mesleksel kanser örneğidir.`,C:`Doğru: iki bölgenin etkenleri birlikte doğru verilmiştir.`,D:`Smegma-HPV rol oynar.`,E:`HPV 16-18 penil patogenezdedir.`},bilgi:[4,9],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k11-q08`,kazanim:11,zorluk:`kolay`,soru:`"Testis atrofisi nedenleri" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{B:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,D:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,A:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,C:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,E:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`},dogru:`B`,aciklama:`Doğru: Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,sik_aciklamalari:{B:`Doğru. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,D:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,A:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,C:`Yanlış. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,E:`Yanlış. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k11-q09`,kazanim:11,zorluk:`orta`,soru:`"Prostat zonal anatomisi ve histolojisi" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,E:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,D:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,B:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,A:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`},dogru:`C`,aciklama:`Doğru: Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,sik_aciklamalari:{C:`Doğru. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,E:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,D:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,B:`Yanlış. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,A:`Yanlış. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k11-q10`,kazanim:11,zorluk:`orta`,soru:`"Kriptorşidizm: tanım, iniş ve sıklık" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{B:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,A:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,C:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,E:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,D:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`},dogru:`B`,aciklama:`Doğru: Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,sik_aciklamalari:{B:`Doğru. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,A:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,C:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,E:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,D:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k11-q11`,kazanim:11,zorluk:`zor`,soru:`"Skrotum neoplazileri (Percival Pott)" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,E:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,C:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,D:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`},dogru:`A`,aciklama:`Doğru: Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,sik_aciklamalari:{A:`Doğru. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,E:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,C:`Yanlış. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,D:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`Yanlış. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`},bilgi:[9],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:12,metin:`Kriptorşidizmin tanımını, testis iniş mekanizmasını ve sıklığını açıklayabilmek`,sorular:[{id:`k1-66-q34`,kazanim:12,zorluk:`kolay`,soru:`Kriptorşidizm aşağıdakilerden hangisini tanımlar?`,secenekler:{A:`Tunika vajinaliste sıvı birikimi`,B:`Spermatik kordun kıvrılması`,C:`Testisin skrotuma inmesindeki yetersizlik`,D:`Testisin iltihabı`,E:`Üretral açıklığın ventral yerleşimi`},dogru:`C`,aciklama:`Kriptorşidizm testisin skrotuma inememesidir; 1 yaş civarında erkeklerin %1'inde görülür.`,sik_aciklamalari:{A:`Sıvı birikimi hidroseldir.`,B:`Kordun kıvrılması torsiyondur.`,C:`Doğru: kriptorşidizmin tanımıdır.`,D:`Testis iltihabı orşittir.`,E:`Ventral açıklık hipospadiastır.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-66-q35`,kazanim:12,zorluk:`orta`,soru:`Testislerin inguinal kanal boyunca skrotuma inişi normalde ne zaman gerçekleşir?`,secenekler:{A:`Gebeliğin ilk ayında`,B:`İntrauterin yaşamın son 2 ayında`,C:`Pubertede`,D:`Doğumdan 5 yıl sonra`,E:`Gebeliğin üçüncü ayında skrotuma ulaşır`},dogru:`B`,aciklama:`Testisler 3. ayda sölom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner.`,sik_aciklamalari:{A:`İlk ayda iniş başlamaz.`,B:`Doğru: inguinoskrotal faz son 2 aydadır.`,C:`Pubertede iniş beklenmez.`,D:`İniş doğum öncesi tamamlanır; gecikme 1 yaşa kadar değerlendirilir.`,E:`Üçüncü ayda pelvise iner, skrotuma değil.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-66-q36`,kazanim:12,zorluk:`zor`,soru:`Kriptorşidizm epidemiyolojisi ile ilgili hangisi yanlıştır?`,secenekler:{A:`1 yaş civarında erkeklerin ~%1'inde görülür`,B:`Olguların ~%10'u bilateraldir`,C:`Sağ tarafta daha sıktır`,D:`Erken doğan bebeklerde 1 yaşından önce tanı koymak zordur`,E:`Olguların çoğu bilateral ve sol taraflıdır`},dogru:`E`,aciklama:`Kriptorşidizmin yalnızca ~%10'u bilateraldir ve sağda daha sıktır.`,sik_aciklamalari:{A:`Doğru ifade: sıklık ~%1'dir.`,B:`Doğru ifade: %10 bilateraldir.`,C:`Doğru ifade: sağda daha sıktır.`,D:`Doğru ifade: iniş doğumda her zaman tamamlanmamış olabilir.`,E:`Yanlış ifade (aranan cevap): çoğu tek taraflı ve sağdadır.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k12-q04`,kazanim:12,zorluk:`orta`,soru:`1 yaşındaki çocuğun boş skrotumu değerlendiriliyor. Hangi açıklama doğrudur?`,secenekler:{A:`Kriptorşidizm testis yokluğudur`,B:`1 yaşındaki çocuğun boş skrotumunda kriptorşidizm düşünülür (%1, %10 bilateral, sağda sık); iniş 3. ayda pelvise, son 2 ayda skrotumadır`,C:`İniş doğumda tamamlanır`,D:`Bilateralite %50'dir`,E:`Solda sıktır`},dogru:`B`,aciklama:`Skrotuma inememe; 3. ay pelvise, son 2 ay inguinal kanaldan skrotuma; %1 (1 yaş), %10 bilateral, sağda sık; erken doğanda tanı zor.`,sik_aciklamalari:{A:`İnme yetersizliğidir.`,B:`Doğru: tanım-zaman-sıklık üçlüsü tamdır.`,C:`Her zaman tamamlanmaz.`,D:`%10'dur.`,E:`Sağda sıktır.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k12-q05`,kazanim:12,zorluk:`zor`,soru:`Prematüre bebekte inmemiş testis takibi tartışılıyor. Hangi yaklaşım doğrudur?`,secenekler:{A:`Prematürede tanı kesindir`,B:`Histoloji erişkinde bozulur`,C:`Erken doğan bebekte iniş tamamlanmamış olabileceğinden 1 yaşından önce tanı zordur; histolojik germ arrest-hiyalinizasyon 2 yaş gibi erken başlar`,D:`Bekleme gereksizdir`,E:`Histoloji normal kalır`},dogru:`C`,aciklama:`Prematürede iniş tamamlanmamış olabilir; 1 yaşından önce tanı zor; histolojik değişiklik 2 yaşta başlar.`,sik_aciklamalari:{A:`Zordur.`,B:`2 yaşta başlar.`,C:`Doğru: tanı zorluğu-erken histoloji ikilisi tamdır.`,D:`Takip gerekir.`,E:`Bozulur.`},bilgi:[12,14],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k12-q06`,kazanim:12,zorluk:`orta`,soru:`Kriptorşidizm inişi ve sıklığı nedir?`,secenekler:{A:`İniş yetmezliği %1, sağda sık ve %10 bilateraldir`,B:`İniş doğumda tamamlanır`,C:`Solda sıktır`,D:`Bilateral %50'dir`,E:`İniş pelviste biter`},dogru:`A`,aciklama:`Kriptorşidizm testisin skrotuma inememesidir; 3. ayda abdomenden pelvise, son 2 ayda inguinal kanaldan skrotuma iner. Bir yaşta %1, %10 bilateral ve sağda sıktır.`,sik_aciklamalari:{A:`Doğru: tanım, zamanlama ve sıklık birlikte doğru verilmiştir.`,B:`Son 2 ayda skrotuma iner.`,C:`Sağda daha sıktır.`,D:`%10 bilateraldir.`,E:`Skrotuma iniş esastır.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k12-q07`,kazanim:12,zorluk:`orta`,soru:`Kriptorşidizm histolojisi ve orşiopeksi zamanlaması nedir?`,secenekler:{A:`Değişim erişkindedir`,B:`Orşiopeksi pubertededir`,C:`Histoloji 2 yaşta başlar; erken orşiopeksi korur`,D:`Leydig azalır`,E:`Cerrahi etkisizdir`},dogru:`C`,aciklama:`Histoloji 2 yaşta başlar: germ arrest, bazal membran hiyalinizasyon-kalınlaşma, stromal artış ve Leydig belirginliği. Puberte öncesi orşiopeksi atrofiyi azaltır.`,sik_aciklamalari:{A:`2 yaş gibi erken başlar.`,B:`Puberteden önce yapılmalıdır.`,C:`Doğru: histoloji ve cerrahi zamanlaması birlikte doğru verilmiştir.`,D:`Leydig hücre belirginliği olur.`,E:`Atrofi ihtimalini azaltır.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k12-q08`,kazanim:12,zorluk:`kolay`,soru:`"Testis neoplazileri: genel özellikler ve risk faktörleri" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,A:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,C:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,E:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,D:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`},dogru:`B`,aciklama:`Doğru: Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,sik_aciklamalari:{B:`Doğru. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,A:`Yanlış. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,C:`Yanlış. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,E:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,D:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`},bilgi:[36],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k12-q09`,kazanim:12,zorluk:`orta`,soru:`"Prostat karsinomu patogenezi ve genetiği" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,B:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,C:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,A:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,E:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`},dogru:`D`,aciklama:`Doğru: Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,sik_aciklamalari:{D:`Doğru. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,B:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,C:`Yanlış. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,A:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,E:`Yanlış. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k12-q10`,kazanim:12,zorluk:`zor`,soru:`"BPH klinik özellikleri ve tedavi" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,E:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,D:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,A:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,C:`Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`},dogru:`B`,aciklama:`Doğru: Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,sik_aciklamalari:{B:`Doğru. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,E:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,D:`Yanlış. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,A:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,C:`Yanlış. Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`},bilgi:[28],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:13,metin:`Kriptorşidizmin sterilite ve artmış testiküler kanser riski ile ilişkisini kavramak`,sorular:[{id:`k1-66-q37`,kazanim:13,zorluk:`kolay`,soru:`Kriptorşidizmde testiküler kanser riski yaklaşık kaç kat artar?`,secenekler:{A:`0,5 kat (azalır)`,B:`100 kat`,C:`Risk artmaz`,D:`3–5 kat`,E:`50 kat`},dogru:`D`,aciklama:`Testis inişindeki yetmezlik 3–5 kat artmış testiküler kanser riski ile birliktedir.`,sik_aciklamalari:{A:`Risk azalmaz: 0,5 kat (azalır).`,B:`100 kat gerçekçi değildir.`,C:`Risk belirgin artar.`,D:`Doğru: risk 3–5 kat artar.`,E:`50 kat verilen veriye uymaz.`},bilgi:[13,36],benzer_cikmis:[]},{id:`k1-66-q38`,kazanim:13,zorluk:`orta`,soru:`Bilateral kriptorşidizmin üreme açısından en önemli sonucu hangisidir?`,secenekler:{A:`BPH`,B:`Hipospadias`,C:`Peyronie hastalığı`,D:`Testislerin atrofisine bağlı sterilite`,E:`Hidrosel`},dogru:`D`,aciklama:`İnmemiş testis atrofiye uğrar; bilateral olgularda sterilite gelişir.`,sik_aciklamalari:{A:`BPH ilişkili değildir.`,B:`Hipospadias eşlik edebilir ama sonuç değildir.`,C:`Peyronie ilişkili değildir.`,D:`Doğru: atrofi steriliteye yol açar.`,E:`Hidrosel kriptorşidizmin tipik sonucu değildir.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-66-q39`,kazanim:13,zorluk:`zor`,soru:`Tek taraflı kriptorşidizmde normal inmiş karşı testiste de kanser riskinin artması neyi düşündürür?`,secenekler:{A:`Kanserin enfeksiyöz olduğunu`,B:`Riskin yalnızca testis sıcaklığından kaynaklandığını`,C:`Kriptorşidizmin bir gelişim/diferansiyasyon defektini yansıttığını`,D:`Karşı testisin her zaman atrofik olduğunu`,E:`Kanserin yalnızca orşiopeksi sonrası geliştiğini`},dogru:`C`,aciklama:`Karşı taraftaki inmiş testiste de risk artışı, kriptorşidizmin altta yatan bir gelişim defektinin parçası olduğunu düşündürür.`,sik_aciklamalari:{A:`Testis kanseri enfeksiyöz değildir.`,B:`Yalnızca sıcaklık karşı testis riskini açıklayamaz.`,C:`Doğru: gelişimsel defekt hipotezini destekler.`,D:`Karşı testiste atrofi gelişebilir ancak her zaman değil.`,E:`Risk orşiopeksiden bağımsız olarak vardır.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k13-q04`,kazanim:13,zorluk:`orta`,soru:`Bilateral kriptorşidizmli erişkinin fertilite-kanser danışmanlığı soruluyor. Hangi bilgi doğrudur?`,secenekler:{A:`Bilateral inmemiş testisli erişkinde atrofi steriliteye yol açar; kanser riski 3-5 kat artar ve karşı inmiş testiste de yüksektir`,B:`Tek taraflı karşı testi etkilemez`,C:`Kanser riski artmaz`,D:`Atrofi fertiliteyi artırır`,E:`Risk yalnızca inmemiş taraftadır`},dogru:`A`,aciklama:`Bilateral atrofi sterilite; 3-5 kat kanser riski, karşı inmiş testiste de artar (gelişim defekti); IGCN odağı kaynak olabilir.`,sik_aciklamalari:{A:`Doğru: sterilite-risk-karşı taraf üçlüsü tamdır.`,B:`Karşıda da artar.`,C:`3-5 kat artar.`,D:`Sterilite yapar.`,E:`Gelişim defekti nedenlidir.`},bilgi:[13,14],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k13-q05`,kazanim:13,zorluk:`zor`,soru:`Orşiopeksili hastanın uzun dönem takibi tartışılıyor. Karşı testis değerlendirmesiyle birlikte hangi yaklaşım doğrudur?`,secenekler:{A:`Orşiopeksi riski sıfırlar`,B:`Karşı testis izlenmez`,C:`IGCN benigndir`,D:`Takip gereksizdir`,E:`Orşiopeksili hastada bile karşı testis dahil kanser riski sürdüğünden izlem gerekir; intratubuler germ hücre neoplazisi in situ kaynak olabilir`},dogru:`E`,aciklama:`IGCN in situ lezyonu normal görünümlü komşu dokuda bulunabilir; orşiopeksi riski düşürür-ortadan kaldırmaz; takip gerekir.`,sik_aciklamalari:{A:`Düşürür, sıfırlamaz.`,B:`İzlenir.`,C:`Prekürsördür.`,D:`Gerekir.`,E:`Doğru: kalıcı risk-izlem ikilisi tamdır.`},bilgi:[13,14,37],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k13-q06`,kazanim:13,zorluk:`orta`,soru:`Kriptorşidizm sterilite ve kanser ilişkisi nedir?`,secenekler:{A:`Sterilite olmaz`,B:`Bilateral sterilite, 3-5 kat kanser riski yapar`,C:`Kontralateral etkilenmez`,D:`Risk artmaz`,E:`Hikâye %50'dir`},dogru:`B`,aciklama:`Bilateral inmemiş testis atrofisi sterilite yapar; tek taraflıda kontralateral inmiş testiste de atrofi olabilir. İniş yetmezliği 3-5 kat kanser riski taşır; testis tümörlerinin %10'unda hikâye vardır.`,sik_aciklamalari:{A:`Bilateralde sterilite olur.`,B:`Doğru: sterilite ve risk katı birlikte doğru verilmiştir.`,C:`Kontralateralde de atrofi gelişebilir.`,D:`3-5 kat artmıştır.`,E:`Vakaların %10'unda hikâye vardır.`},bilgi:[13,36],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k13-q07`,kazanim:13,zorluk:`orta`,soru:`Kontralateral testis etkisi ve hikâye oranı nedir?`,secenekler:{A:`Kontralateral daima normaldir`,B:`Hikâye %50'dir`,C:`Tek taraflıda fertilite garantidir`,D:`Kanser ilişkisi yoktur`,E:`Kontralateral de atrofiye uğrar; tümörlerin %10'unda hikâye vardır`},dogru:`E`,aciklama:`Tek taraflı inmemiş testiste bile kontralateral inmiş testiste atrofi gelişebilir; bu yüzden fertilite tek testisle garanti değildir. Testis tümörlü vakaların %10'unda kriptorşidizm hikâyesi vardır.`,sik_aciklamalari:{A:`Kontralateralde de atrofi gelişebilir.`,B:`%10'unda hikâye vardır.`,C:`Atrofi bilateral etki yapabilir.`,D:`3-5 kat risk artışı vardır.`,E:`Doğru: kontralateral etki ve hikâye oranı birlikte doğru verilmiştir.`},bilgi:[13,36],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k13-q08`,kazanim:13,zorluk:`kolay`,soru:`Aşağıdakilerden "Kriptorşidizm: sterilite ve kanser riski" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{D:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,A:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,C:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,E:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`},dogru:`D`,aciklama:`Doğru: İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,sik_aciklamalari:{D:`Doğru. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,A:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,C:`Yanlış. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,E:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k13-q09`,kazanim:13,zorluk:`orta`,soru:`"Prostat karsinomu klinik özellikleri ve metastaz" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,D:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,C:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,A:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,B:`Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`},dogru:`E`,aciklama:`Doğru: Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,sik_aciklamalari:{E:`Doğru. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,D:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,C:`Yanlış. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,A:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,B:`Yanlış. Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`},bilgi:[33],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k13-q10`,kazanim:13,zorluk:`orta`,soru:`"PSA ölçümü ve sınırlamaları" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,E:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,B:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,A:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,D:`Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`},dogru:`C`,aciklama:`Doğru: PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,sik_aciklamalari:{C:`Doğru. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,E:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,B:`Yanlış. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,A:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,D:`Yanlış. Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k13-q11`,kazanim:13,zorluk:`zor`,soru:`"Prostat karsinomu morfolojisi ve PİN" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{A:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,B:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,D:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,C:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,E:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`},dogru:`A`,aciklama:`Doğru: Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,sik_aciklamalari:{A:`Doğru. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,B:`Yanlış. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,D:`Yanlış. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,C:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,E:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`},bilgi:[31],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:14,metin:`Orşiopeksinin kriptorşidizmdeki rolünü açıklayabilmek`,sorular:[{id:`k1-66-q40`,kazanim:14,zorluk:`kolay`,soru:`İnmemiş testisin cerrahi olarak skrotuma yerleştirilmesine ne ad verilir?`,secenekler:{A:`Orşiektomi`,B:`Orşiopeksi`,C:`Vazektomi`,D:`Sirkümsizyon`,E:`Prostatektomi`},dogru:`B`,aciklama:`Orşiopeksi inmemiş testisin skrotuma cerrahi olarak yerleştirilmesidir.`,sik_aciklamalari:{A:`Orşiektomi testisin çıkarılmasıdır.`,B:`Doğru: orşiopeksinin tanımıdır.`,C:`Vazektomi vas deferensin kesilmesidir.`,D:`Sirkümsizyon prepisyumun çıkarılmasıdır.`,E:`Prostatektomi prostatın çıkarılmasıdır.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-66-q41`,kazanim:14,zorluk:`orta`,soru:`Kriptorşid testiste histolojik değişikliklerin başlama zamanı ve orşiopeksinin önemi ile ilgili hangisi doğrudur?`,secenekler:{A:`Değişiklikler yalnızca 40 yaşından sonra başlar`,B:`Değişiklikler 2 yaş gibi erken başlar; puberteden önce orşiopeksi atrofi ihtimalini azaltır`,C:`Orşiopeksi atrofiyi artırır`,D:`Orşiopeksi yalnızca erişkinlikte yapılmalıdır`,E:`Kriptorşid testiste histolojik değişiklik olmaz`},dogru:`B`,aciklama:`Germ hücre arrest, bazal membran kalınlaşması ve stroma artışı 2 yaş gibi erken başlar; puberte öncesi orşiopeksi atrofi riskini azaltır.`,sik_aciklamalari:{A:`Değişiklikler erken çocuklukta başlar.`,B:`Doğru: erken cerrahi önemlidir.`,C:`Orşiopeksi atrofi ihtimalini azaltır.`,D:`Puberteden önce yapılmalıdır.`,E:`Belirgin histolojik değişiklikler gelişir.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-66-q42`,kazanim:14,zorluk:`zor`,soru:`Kriptorşid testiste görülebilen histolojik değişiklikler arasında aşağıdakilerden hangisi yer almaz?`,secenekler:{A:`Germ hücre gelişiminde arrest`,B:`Bazal membranda hiyalinizasyon ve kalınlaşma`,C:`İnterstisyel stromada artış`,D:`Leydig hücre belirginliği`,E:`Seminifer tübüllerde aktif spermatogenez artışı`},dogru:`E`,aciklama:`Kriptorşid testiste germ hücre arresti, bazal membran kalınlaşması, stroma artışı ve Leydig hücre belirginliği görülür; spermatogenez artmaz.`,sik_aciklamalari:{A:`Görülen bir değişikliktir.`,B:`Görülen bir değişikliktir.`,C:`Görülen bir değişikliktir.`,D:`Görülen bir değişikliktir.`,E:`Doğru: spermatogenez azalır, artmaz.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k14-q04`,kazanim:14,zorluk:`orta`,soru:`İnmemiş testisli çocuğun cerrahi zamanlaması ve beklentisi soruluyor. Hangi danışmanlık doğrudur?`,secenekler:{A:`Orşiopeksi erişkinde yapılır`,B:`Orşiopeksi riski artırır`,C:`Orşiopeksi atrofiyi artırır`,D:`Puberteden önce inmemiş testisin skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır, kanser-infertilite riskini düşürür ancak ortadan kaldırmaz`,E:`Cerrahi gereksizdir`},dogru:`D`,aciklama:`Puberteden önce skrotuma yerleştirme atrofiyi azaltır; kanser-infertiliteyi düşürür-sıfırlamaz.`,sik_aciklamalari:{A:`Puberteden öncedir.`,B:`Düşürür.`,C:`Azaltır.`,D:`Doğru: zaman-etki-sınır üçlüsü tamdır.`,E:`Gerekir.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k14-q05`,kazanim:14,zorluk:`zor`,soru:`Kriptorşid testis biyopsisi yorumlanıyor. Hangi yorum doğrudur?`,secenekler:{A:`Biyopside germ arrest-bazal membran kalınlaşması-Leydig belirginliği kriptorşid teste aittir ve erken orşiopeksi atrofi sürecini yavaşlatır`,B:`Histoloji normaldir`,C:`Leydig azalır`,D:`Membran incelir`,E:`Cerrahi histolojiyi bozar`},dogru:`A`,aciklama:`Histoloji: germ arrest, bazal membran hiyalinizasyon-kalınlaşma, stromal artış, Leydig belirginliği; erken cerrahi bu süreci yavaşlatır.`,sik_aciklamalari:{A:`Doğru: histoloji-cerrahi etkisi ikilisi tamdır.`,B:`2 yaşta bozulur.`,C:`Belirginleşir.`,D:`Kalınlaşır.`,E:`Yavaşlatır.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k14-q06`,kazanim:14,zorluk:`orta`,soru:`Orşiopeksinin rolü ve zamanlaması nedir?`,secenekler:{A:`Erken orşiopeksi atrofiyi azaltır`,B:`Orşiopeksi kanseri önler`,C:`Puberte sonrası yapılır`,D:`İzlem gerekmez`,E:`Orşiopeksi orşiektomidir`},dogru:`A`,aciklama:`Puberte öncesi skrotuma yerleştirme (orşiopeksi) atrofiyi azaltır ve izlemi kolaylaştırır. Gecikmede germ arrest ve membran kalınlaşması ilerler.`,sik_aciklamalari:{A:`Doğru: zamanlama ve fayda birlikte doğru verilmiştir.`,B:`Riski azaltmaz, izlemi sağlar.`,C:`Puberteden önce yapılmalıdır.`,D:`Kanser riski izlemi sürer.`,E:`Skrotuma yerleştirmedir.`},bilgi:[14],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k14-q07`,kazanim:14,zorluk:`orta`,soru:`Orşiopeksi sonrası izlem neden sürer?`,secenekler:{A:`Orşiopeksi kanseri önler`,B:`İzlem gerekmez`,C:`Orşiopeksi atrofiyi azaltır ama risk sürer, izlem gerekir`,D:`Cerrahi geç yapılmalıdır`,E:`Orşiopeksi orşiektomidir`},dogru:`C`,aciklama:`Orşiopeksi atrofiyi azaltır ancak artmış kanser riskini ortadan kaldırmaz; skrotuma inen testis yaşam boyu muayene ve izlem gerektirir. Erken cerrahi germ arrest ve membran kalınlaşmasını sınırlar.`,sik_aciklamalari:{A:`Riski ortadan kaldırmaz.`,B:`Yaşam boyu izlem gerekir.`,C:`Doğru: fayda ve sınır birlikte doğru verilmiştir.`,D:`Puberteden önce yapılmalıdır.`,E:`Skrotuma yerleştirmedir.`},bilgi:[13,14],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k14-q08`,kazanim:14,zorluk:`kolay`,soru:`Aşağıdakilerden "Balanit, balanopostit ve fimozis" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{C:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,A:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,E:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,B:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,D:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`},dogru:`C`,aciklama:`Doğru: Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,sik_aciklamalari:{C:`Doğru. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,A:`Yanlış. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,E:`Yanlış. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,B:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,D:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`},bilgi:[3],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k14-q09`,kazanim:14,zorluk:`orta`,soru:`"Testis atrofisi nedenleri" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{D:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,E:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,C:`Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,A:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,B:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`},dogru:`D`,aciklama:`Doğru: Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,sik_aciklamalari:{D:`Doğru. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,E:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,C:`Yanlış. Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,A:`Yanlış. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,B:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k14-q10`,kazanim:14,zorluk:`orta`,soru:`"Prostat karsinomu morfolojisi ve PİN" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,E:`Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,C:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,B:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,D:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`},dogru:`A`,aciklama:`Doğru: Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,sik_aciklamalari:{A:`Doğru. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,E:`Yanlış. Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,C:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,B:`Yanlış. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,D:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k14-q11`,kazanim:14,zorluk:`zor`,soru:`"Kriptorşidizm: sterilite ve kanser riski" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,E:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,D:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,A:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,C:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`},dogru:`B`,aciklama:`Doğru: İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,sik_aciklamalari:{B:`Doğru. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,E:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,D:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,A:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,C:`Yanlış. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`},bilgi:[13],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:15,metin:`Testis atrofisinin başlıca nedenlerini sayabilmek`,sorular:[{id:`k1-66-q43`,kazanim:15,zorluk:`kolay`,soru:`Aşağıdakilerden hangisi testis atrofisi nedenlerinden biri değildir?`,secenekler:{A:`Klinefelter sendromu`,B:`Ateroskleroz`,C:`Radyasyon`,D:`Hidrosel`,E:`Siroz`},dogru:`D`,aciklama:`Testis atrofisi ateroskleroz, orşit, radyasyon, antiandrojenler, tükenme atrofisi, siroz ve Klinefelter sendromu ile gelişir.`,sik_aciklamalari:{A:`Klinefelter genetik atrofi nedenidir.`,B:`Ateroskleroz kan akımını azaltır.`,C:`Radyasyon germ hücrelerini hasarlar.`,D:`Doğru: hidrosel atrofi nedeni olarak sayılmaz.`,E:`Sirozda östrojen artışı atrofi yapar.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-66-q44`,kazanim:15,zorluk:`orta`,soru:`İlerlemiş prostat kanseri nedeniyle uzun süre tedavi alan hastada testis atrofisinin olası nedeni hangisidir?`,secenekler:{A:`Varikosel`,B:`Hidrosel`,C:`Antiandrojen tedavisi`,D:`Spermatosel`,E:`Fimozis`},dogru:`C`,aciklama:`İlerlemiş prostat kanserinde uzun süreli antiandrojen kullanımı testis atrofisi nedenidir.`,sik_aciklamalari:{A:`Varikosel infertiliteyle ilişkili olabilir; burada açıklayıcı değildir.`,B:`Hidrosel atrofi nedeni olarak sayılmaz.`,C:`Doğru: hormonal baskılama atrofi yapar.`,D:`Spermatosel atrofi yapmaz.`,E:`Fimozis testis atrofisi yapmaz.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-66-q45`,kazanim:15,zorluk:`zor`,soru:`Yüksek FSH ile sürekli uyarıma bağlı gelişen testis atrofisi türüne ne ad verilir?`,secenekler:{A:`Granülomatöz orşit`,B:`Kriptorşidizm`,C:`Tükenme atrofisi`,D:`Torsiyon`,E:`Seminom`},dogru:`C`,aciklama:`Yüksek FSH ile sürekli uyarı tükenme atrofisine yol açar.`,sik_aciklamalari:{A:`Granülomatöz orşit enfeksiyöz/otoimmün süreçtir.`,B:`Kriptorşidizm iniş bozukluğudur.`,C:`Doğru: tükenme atrofisinin tanımıdır.`,D:`Torsiyon venöz infarkt yapar.`,E:`Seminom tümördür: seminom.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k15-q04`,kazanim:15,zorluk:`orta`,soru:`Küçük testisli hastada etiyoloji listesi soruluyor. Hangi liste doğrudur?`,secenekler:{A:`Atrofinin nedeni yoktur`,B:`Klinefelter testisi büyütür`,C:`Küçük-sert testisli yaşlıda aterosklerotik akım azalması, Klinefelterde genetik, sirozda östrojen yüksekliği ve uzun antiandrojen-radyasyon atrofi nedenleridir`,D:`Orşit testisi büyütür`,E:`FSH düşüklüğü atrofi yapar`},dogru:`C`,aciklama:`Ateroskleroz, ileri orşit, radyasyon, uzun antiandrojen, tükenme (yüksek FSH), siroz-östrojen yüksekliği, Klinefelter.`,sik_aciklamalari:{A:`Çok nedenlidir.`,B:`Atrofi nedenidir.`,C:`Doğru: vasküler-genetik-hormonal-iyatrojenik dörtlüsü tamdır.`,D:`İleri evresi atrofi yapar.`,E:`Yüksek FSH'lı tükenme yapar.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k15-q05`,kazanim:15,zorluk:`zor`,soru:`Farklı atrofi mekanizmaları karşılaştırılıyor. Hangi açıklama doğrudur?`,secenekler:{A:`Atrofi geri dönüşlüdür`,B:`Sirozlu hastada östrojen yüksekliği, kastrasyonlu hastada antiandrojen ve yaşlıda ateroskleroz germ hücre kaybı-fibrozisle atrofi yapar`,C:`Antiandrojen testisi büyütür`,D:`Siroz testisi korur`,E:`Fibrozis atrofide yoktur`},dogru:`B`,aciklama:`Germ kaybı-fibrozis küçülmeye yol açar; sirozda östrojen, tükenmede sürekli uyarım-yüksek FSH mekanizmadır.`,sik_aciklamalari:{A:`Kalıcı küçülmedir.`,B:`Doğru: üç mekanizma-sonuç üçlüsü tamdır.`,C:`Atrofi yapar.`,D:`Östrojenle atrofi yapar.`,E:`Temel sonuçtur.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k15-q06`,kazanim:15,zorluk:`orta`,soru:`Testis atrofisi neden grupları nelerdir?`,secenekler:{A:`Yalnızca yaşlılıktır`,B:`Vasküler-enfeksiyöz-iyonizan-hormonal-genetik nedenlidir`,C:`Radyasyon korur`,D:`Klinefelter korur`,E:`Orşit korur`},dogru:`B`,aciklama:`Atrofi yaşlılık aterosklerozu, ileri orşit, radyasyon, antiandrojen, tükenme, siroz ve Klinefelter'dendir. Her biri germ-stroma dengesini bozarak hacim kaybı yapar.`,sik_aciklamalari:{A:`Yedi grup neden vardır.`,B:`Doğru: neden grupları birlikte doğru verilmiştir.`,C:`Radyasyon nedendir.`,D:`Genetik nedenlerdendir.`,E:`İleri evre orşit nedendir.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k15-q07`,kazanim:15,zorluk:`orta`,soru:`Hormonal-genetik atrofi nedenleri nelerdir?`,secenekler:{A:`Klinefelter korur`,B:`Siroz korur`,C:`Antiandrojen korur`,D:`Klinefelter-siroz-antiandrojen-tükenme atrofi yapar`,E:`FSH düşüklüğü yapar`},dogru:`D`,aciklama:`Hormonal-genetik nedenler Klinefelter sendromu, sirozda östrojen yükselmesi, ilerlemiş kanserde uzun antiandrojen ve tükenme atrofisidir (sürekli yüksek FSH uyarımı). Bunlar germ epitelini baskılayarak hacim kaybettirir.`,sik_aciklamalari:{A:`Genetik nedenlerdendir.`,B:`Östrojen yükselmesi nedendir.`,C:`Uzun kullanım atrofi nedenidir.`,D:`Doğru: hormonal-genetik grup birlikte doğru verilmiştir.`,E:`Tükenmede yüksek FSH uyarımı vardır.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k15-q08`,kazanim:15,zorluk:`kolay`,soru:`"Testis tümörü belirteçleri, klinik ve tedavi" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,A:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,B:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,C:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,D:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`},dogru:`E`,aciklama:`Doğru: hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,sik_aciklamalari:{E:`Doğru. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,A:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,B:`Yanlış. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,C:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,D:`Yanlış. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k15-q09`,kazanim:15,zorluk:`orta`,soru:`"BPH klinik özellikleri ve tedavi" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{D:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,E:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,B:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,C:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,A:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`},dogru:`D`,aciklama:`Doğru: Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,sik_aciklamalari:{D:`Doğru. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,E:`Yanlış. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,B:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,C:`Yanlış. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,A:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k15-q10`,kazanim:15,zorluk:`orta`,soru:`"Prostatit klinik özellikleri ve tedavi" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,C:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,E:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,D:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`},dogru:`A`,aciklama:`Doğru: Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,sik_aciklamalari:{A:`Doğru. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,C:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,E:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,D:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`},bilgi:[23],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k15-q11`,kazanim:15,zorluk:`zor`,soru:`"Non-seminomatöz germ hücre tümörleri" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,D:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,E:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,B:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,C:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`},dogru:`A`,aciklama:`Doğru: Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,sik_aciklamalari:{A:`Doğru. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,D:`Yanlış. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,E:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,B:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,C:`Yanlış. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`},bilgi:[39],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:16,metin:`Testis ve epididimin başlıca iltihabi hastalıklarını (nonspesifik epididimit/orşit, kabakulak orşiti, tüberküloz) tanımlayabilmek`,sorular:[{id:`k1-66-q46`,kazanim:16,zorluk:`kolay`,soru:`Testisin en sık granülomatöz iltihabı hangisidir?`,secenekler:{A:`Kabakulak orşiti`,B:`Tüberküloz`,C:`Nonspesifik bakteriyel epididimit`,D:`Sifiliz`,E:`Gonore`},dogru:`B`,aciklama:`Testiste granülomatöz reaksiyonun en sık nedeni tüberkülozdur; genellikle epididimitle başlar.`,sik_aciklamalari:{A:`Kabakulak lenfoplazmositik infiltrasyon yapar.`,B:`Doğru: kazeöz nekrozlu granülomlar görülür.`,C:`Nonspesifik epididimit nötrofilik infiltrat içerir.`,D:`Sifiliz bu derste en sık neden olarak verilmemiştir.`,E:`Gonore süpüratif inflamasyon yapar.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-66-q47`,kazanim:16,zorluk:`orta`,soru:`Kabakulak orşiti ile ilgili hangisi doğrudur?`,secenekler:{A:`Çocuklarda erişkinlerden daha sık orşit yapar`,B:`Başlıca nötrofilik infiltrat içerir`,C:`Kazeöz nekrozlu granülomlar oluşturur`,D:`Kabakulak geçiren erişkin erkeklerin ~%20'sinde görülür ve lenfoplazmositik infiltrasyon yapar`,E:`Hiçbir zaman nekroz yapmaz`},dogru:`D`,aciklama:`Kabakulak orşiti erişkin erkeklerin ~%20'sinde gelişir; ağır olgularda nekroz ve seminifer epitel kaybı olabilir.`,sik_aciklamalari:{A:`Orşit erişkinlerde önemlidir.`,B:`Nötrofilik infiltrat nonspesifik epididimit/orşite aittir.`,C:`Granülom tüberküloza aittir.`,D:`Doğru: sıklık ve infiltrat tipi doğru verilmiştir.`,E:`Ağır olgularda nekroz gelişebilir.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-66-q48`,kazanim:16,zorluk:`zor`,soru:`Testis ve epididimin iltihabi hastalıkları ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur`,B:`Nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar`,C:`Tüberküloz genellikle epididimitle başlar, testis sekonder tutulur`,D:`Granülomatöz orşitte kazeöz nekroz görülebilir`,E:`Tüberküloz önce testisi tutar, epididim hiçbir zaman tutulmaz`},dogru:`E`,aciklama:`Testis tüberkülozu genellikle epididimitle başlar ve testis sekonder olarak tutulur.`,sik_aciklamalari:{A:`Doğru ifade: epididim sık tutulur.`,B:`Doğru ifade: idrar yolu enfeksiyonu kaynaklıdır.`,C:`Doğru ifade: tüberkülozun yayılım sırasıdır.`,D:`Doğru ifade: kazeöz nekroz tüberküloz bulgusudur.`,E:`Yanlış ifade (aranan cevap): epididim önce tutulur.`},bilgi:[16,17],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k16-q04`,kazanim:16,zorluk:`orta`,soru:`Kabakulak sonrası testis şişliği gelişen erişkinde hücre tipi soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`Testis iltihabı epididimi tutmaz`,B:`Nonspesifik epididimit granülomatözdür`,C:`Kabakulak orşiti çocuklarda sıktır`,D:`Kabakulak orşiti nötrofillidir`,E:`Kabakulak sonrası testis ağrılı-şiş erişkinde (%20) lenfoplazmositik orşit düşünülür; nonspesifik epididimit idrar yolu kaynaklı nötrofillidir`},dogru:`E`,aciklama:`İltihap çoğunlukla epididimde; nonspesifik idrar yolu kaynaklı nötrofilli; kabakulak erişkin %20 lenfoplazmositik, ağırda nekroz-atrofi-sterilite.`,sik_aciklamalari:{A:`Çoğunlukla epididimdedir.`,B:`Nötrofillidir.`,C:`Erişkinde %20'dir.`,D:`Lenfoplazmositiktir.`,E:`Doğru: iki iltihap-hücre eşleşmesi tamdır.`},bilgi:[16],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k16-q05`,kazanim:16,zorluk:`zor`,soru:`Granülomatöz epididimo-orşitli hastada etiyoloji ve seyir soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`Granülomatöz-kazeöz epididimo-orşitli hastada tüberküloz ilk akla gelir (epididimitle başlar, testis sekonder tutulur); ağır kabakulak orşiti nekroz-tubuler atrofi-steriliteye ilerleyebilir`,B:`Granülomatöz orşitin en sık nedeni kabakulaktır`,C:`Tüberküloz testiste kazeifikasyon yapmaz`,D:`Kabakulak sterilite yapmaz`,E:`Epididimit testisi tutmaz`},dogru:`A`,aciklama:`Granülomatöz orşitin en sık nedeni tüberküloz (epididimitle başlar, kazeöz nekroz); ağır kabakulak nekroz-atrofi-sterilite yapar.`,sik_aciklamalari:{A:`Doğru: granülom-sekil ikilisi tamdır.`,B:`Tüberkülozdur.`,C:`Kazeöz nekroz yapar.`,D:`Ağırda yapar.`,E:`Sekonder tutulur.`},bilgi:[16,17],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k16-q06`,kazanim:16,zorluk:`orta`,soru:`Testis iltihaplarının doku yanıtları nelerdir?`,secenekler:{A:`Nonspesifik nötrofilik, kabakulak lenfositik, granülomatöz TB'dir`,B:`Nonspesifik granülomatözdür`,C:`Kabakulak nötrofiliktir`,D:`TB nadirdir`,E:`Epididim korunur`},dogru:`A`,aciklama:`Nonspesifik tablo primer İYE olarak nötrofilik başlar. Kabakulakta lenfoplazmositik orşit erişkin %20'dir. Granülomatöz reaksiyonun en sık nedeni tüberkülozdur.`,sik_aciklamalari:{A:`Doğru: üç tablonun doku yanıtı doğru eşleştirilmiştir.`,B:`Nötrofilli infiltrat içerir.`,C:`Lenfoplazmositik infiltrasyon yapar.`,D:`En sık granülomatöz nedendir.`,E:`Çoğunlukla epididimdedir.`},bilgi:[16,17],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k16-q07`,kazanim:16,zorluk:`orta`,soru:`Tüberküloz yayılımı ve diğer granülomatöz neden nedir?`,secenekler:{A:`TB testisle başlar`,B:`TB granülom yapmaz`,C:`TB epididimal başlar sekonder tutar; otoimmün de granülom yapar`,D:`Granülom nadirdir`,E:`Epididim korunur`},dogru:`C`,aciklama:`Tüberküloz epididimitle başlar, testis sekonder tutulur ve granülomatöz reaksiyonun en sık nedenidir. Otoimmün hastalıklar da testiste granülomatöz reaksiyon oluşturabilir.`,sik_aciklamalari:{A:`Epididimitle başlar.`,B:`En sık granülomatöz nedendir.`,C:`Doğru: yayılım yönü ve ikinci neden birlikte doğru verilmiştir.`,D:`En sık görülenidir.`,E:`Genellikle epididimit ile başlar.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k16-q08`,kazanim:16,zorluk:`kolay`,soru:`Aşağıdakilerden "Granülomatöz orşit (tüberküloz)" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{A:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,B:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,C:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,D:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,E:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`},dogru:`A`,aciklama:`Doğru: Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,sik_aciklamalari:{A:`Doğru. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,B:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,C:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,D:`Yanlış. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,E:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k16-q09`,kazanim:16,zorluk:`kolay`,soru:`Aşağıdakilerden "Spermatosel ve varikosel" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{C:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,B:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,D:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,A:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,E:`Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`},dogru:`C`,aciklama:`Doğru: Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,sik_aciklamalari:{C:`Doğru. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,B:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,D:`Yanlış. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,A:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,E:`Yanlış. Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k16-q10`,kazanim:16,zorluk:`orta`,soru:`"Prostat karsinomu patogenezi ve genetiği" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{B:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,C:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,D:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,A:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,E:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`},dogru:`B`,aciklama:`Doğru: Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,sik_aciklamalari:{B:`Doğru. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,C:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,D:`Yanlış. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,A:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,E:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k16-q11`,kazanim:16,zorluk:`orta`,soru:`"Kriptorşidizm: sterilite ve kanser riski" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{D:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,E:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,C:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,A:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,B:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`},dogru:`D`,aciklama:`Doğru: İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,sik_aciklamalari:{D:`Doğru. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,E:`Yanlış. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,C:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,A:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,B:`Yanlış. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k16-q12`,kazanim:16,zorluk:`zor`,soru:`"Prostat karsinomu klinik özellikleri ve metastaz" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{A:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,C:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,E:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,D:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,B:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`},dogru:`A`,aciklama:`Doğru: Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,sik_aciklamalari:{A:`Doğru. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,C:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,E:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,D:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,B:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`},bilgi:[33],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k16-q13`,kazanim:16,zorluk:`zor`,soru:`"Testiküler torsiyon: mekanizma ve tipler" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{A:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,C:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,E:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,D:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`},dogru:`A`,aciklama:`Doğru: Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,sik_aciklamalari:{A:`Doğru. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,C:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Yanlış. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,E:`Yanlış. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,D:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`},bilgi:[18],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:17,metin:`Testiküler torsiyonun mekanizmasını, tiplerini ve acil tedavisini açıklayabilmek`,sorular:[{id:`k1-66-q49`,kazanim:17,zorluk:`kolay`,soru:`Testiküler torsiyonda testis hasarının temel mekanizması hangisidir?`,secenekler:{A:`Lenfatik obstrüksiyon`,B:`Arteriyel emboli`,C:`Bakteriyel enfeksiyon`,D:`Hormonal baskılama`,E:`Venöz drenajın obstrüksiyonu ve venöz infarkt`},dogru:`E`,aciklama:`Kordun kıvrılması kalın duvarlı arterleri açık bırakırken venöz drenajı tıkar; düzelmezse venöz infarkt gelişir.`,sik_aciklamalari:{A:`Lenfatik obstrüksiyon elefantiaziste önemlidir.`,B:`Arterler genellikle açık kalır.`,C:`Torsiyon enfeksiyöz değildir.`,D:`Hormonal mekanizma söz konusu değildir.`,E:`Doğru: torsiyonun patofizyolojisidir.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-66-q50`,kazanim:17,zorluk:`orta`,soru:`Uykudan ani skrotal ağrıyla uyanan adolesanda testiküler torsiyon düşünülüyor. Yetişkin tip torsiyonla ilişkili anatomik defekt hangisidir?`,secenekler:{A:`Varikosel`,B:`Hipospadias`,C:`Bilateral çan tokmağı (bell-clapper) anomalisi`,D:`İnguinal herni`,E:`Anatomik defekt yoktur`},dogru:`C`,aciklama:`Yetişkin tip torsiyon adolesanlarda görülür ve bilateral çan tokmağı anomalisi ile birliktedir; neonatal torsiyonda anatomik defekt yoktur.`,sik_aciklamalari:{A:`Varikosel torsiyon nedeni değildir.`,B:`Hipospadias torsiyonla ilişkili değildir.`,C:`Doğru: bilateral defekt torsiyona yatkınlık yapar.`,D:`Herni torsiyonun bu tipik defekti değildir.`,E:`Anatomik defekt yokluğu neonatal torsiyona aittir.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-66-q51`,kazanim:17,zorluk:`zor`,soru:`Testiküler torsiyon tedavisi ile ilgili hangisi doğrudur?`,secenekler:{A:`Karşı testise müdahale gerekmez`,B:`Elektif olarak birkaç hafta içinde ameliyat yeterlidir`,C:`Yalnızca antibiyotik tedavisi uygulanır`,D:`İlk 6 saat içinde cerrahi uygulanmalı ve karşı taraf testis de orşiopeksi ile sabitlenmelidir`,E:`Kord elle düzeltilse bile testisin yaşama şansı yoktur`},dogru:`D`,aciklama:`Torsiyon acildir; ilk 6 saatte müdahale testisi kurtarabilir ve bilateral defekt nedeniyle karşı testis de sabitlenir.`,sik_aciklamalari:{A:`Bilateral anomali nedeniyle karşı testis de sabitlenir.`,B:`Gecikme infarkta yol açar.`,C:`Torsiyon enfeksiyon değildir.`,D:`Doğru: acil cerrahi ve kontralateral fiksasyon gerekir.`,E:`Erken düzeltmede testis yaşayabilir.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k17-q04`,kazanim:17,zorluk:`orta`,soru:`Gece ani testis ağrısıyla uyanan adolesanda mekanizma soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`Torsiyon arteryel infarkttır`,B:`Uykudan uyandıran ani testis ağrılı adolesanda çan tokmağı anomalili yetişkin tip torsiyon düşünülür; venöz drenaj tıkanır, düzelmezse venöz infarkt gelişir`,C:`Neonatalde bilateral defekt vardır`,D:`Ağrı sinsi başlar`,E:`Venöz drenaj korunur`},dogru:`B`,aciklama:`Kord kıvrılması arteri açık bırakıp veni tıkar-venöz infarkt; neonatalde defekt yok; yetişkin tip adolesanda çan tokmağı bilateral defektiyle ani-uykudan uyandıran ağrı.`,sik_aciklamalari:{A:`Venöz infarkttır.`,B:`Doğru: tip-defekt-mekanizma üçlüsü tamdır.`,C:`Defekt yoktur.`,D:`Anidir.`,E:`Tıkanır.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k17-q05`,kazanim:17,zorluk:`zor`,soru:`Torsiyon şüphesinde zamanlama ve karşı testis yönetimi soruluyor. Hangi plan doğrudur?`,secenekler:{A:`Torsiyon elektif izlenir`,B:`6 gün beklenir`,C:`Karşı testise dokunulmaz`,D:`Testis torsiyonunda ilk 6 saatte cerrahi uygulanır ve etkilenmemiş karşı testis orşiopeksiyle sabitlenir`,E:`Elle düzeltme kontrendikedir`},dogru:`D`,aciklama:`Ürolojik acil; ilk 6 saatte girişim, elle detorsiyon şans verebilir; nüksü önlemek için karşı testise orşiopeksi yapılır.`,sik_aciklamalari:{A:`Acildir.`,B:`6 saattir.`,C:`Sabitlenir.`,D:`Doğru: zaman-karşı taraf ikilisi tamdır.`,E:`Şans verebilir.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k17-q06`,kazanim:17,zorluk:`orta`,soru:`Torsiyon tipleri ve mekanizması nedir?`,secenekler:{A:`Arter tıkanır`,B:`Venöz tıkanır; neonatalde defekt yok, adolesanda bilateral anomali`,C:`İnfarkt olmaz`,D:`Neonatalde anomali var`,E:`Unilateraldir`},dogru:`B`,aciklama:`Kord kıvrılması kalın arterleri açık bırakıp venözü tıkar ve infarkt yapar. Neonatal torsiyonda defekt yok; yetişkin tip adolesanda çan tokmağı anomalisiyle bilateraldir.`,sik_aciklamalari:{A:`Arterler açık kalır.`,B:`Doğru: mekanizma ve tip farkı birlikte doğru verilmiştir.`,C:`Düzelmezse venöz infarkt gelişir.`,D:`Anatomik defekt yoktur.`,E:`Çan tokmağı bilateraldir.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k17-q07`,kazanim:17,zorluk:`orta`,soru:`Torsiyon tedavisi ve zamanlaması nedir?`,secenekler:{A:`Elektiftir`,B:`Detorsiyon zararlıdır`,C:`6 gün beklenir`,D:`Atrofi olmaz`,E:`6 saatte cerrahi; elle düzeltme şans verir`},dogru:`E`,aciklama:`Torsiyon ürolojik acildir; 6 saatte cerrahi, elle detorsiyon şans verebilir. Gecikmede infarkt ve atrofi kaçınılmazdır.`,sik_aciklamalari:{A:`Acil problemlerdendir.`,B:`Yaşama şansı verebilir.`,C:`İlk 6 saatte uygulanır.`,D:`İnfarkt atrofiye gider.`,E:`Doğru: zamanlama ve manevra birlikte doğru verilmiştir.`},bilgi:[19],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k17-q08`,kazanim:17,zorluk:`kolay`,soru:`"Testis neoplazileri: genel özellikler ve risk faktörleri" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{A:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,D:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,E:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,C:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,B:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`},dogru:`A`,aciklama:`Doğru: Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,sik_aciklamalari:{A:`Doğru. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,D:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,E:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,C:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,B:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`},bilgi:[36],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k17-q09`,kazanim:17,zorluk:`orta`,soru:`"Epispadias" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{C:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,E:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,D:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,B:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,A:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`},dogru:`C`,aciklama:`Doğru: Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,sik_aciklamalari:{C:`Doğru. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,E:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,D:`Yanlış. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,B:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,A:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k17-q10`,kazanim:17,zorluk:`orta`,soru:`"Peyronie hastalığı" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,E:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,A:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,C:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,D:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`},dogru:`B`,aciklama:`Doğru: Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,sik_aciklamalari:{B:`Doğru. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,E:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,A:`Yanlış. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,C:`Yanlış. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,D:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k17-q11`,kazanim:17,zorluk:`zor`,soru:`"Testis tümörü belirteçleri, klinik ve tedavi" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,C:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,D:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,E:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,B:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`},dogru:`A`,aciklama:`Doğru: hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,sik_aciklamalari:{A:`Doğru. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,C:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,D:`Yanlış. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,E:`Yanlış. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,B:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`},bilgi:[40],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:18,metin:`Prostatın zonal anatomisini ve hastalıkların yerleşimini ilişkilendirebilmek`,sorular:[{id:`k1-66-q52`,kazanim:18,zorluk:`kolay`,soru:`Prostat karsinomlarının çoğu prostatın hangi zonundan gelişir?`,secenekler:{A:`Periüretral bezler`,B:`Transisyonel zon`,C:`Santral zon`,D:`Anterior fibromüsküler stroma`,E:`Periferik zon`},dogru:`E`,aciklama:`Karsinomların %70–80'i periferik zondan gelişir ve rektal muayenede palpe edilebilir.`,sik_aciklamalari:{A:`Periüretral bezler BPH ile ilişkilidir.`,B:`Transisyonel zon BPH'nin yerleşim yeridir.`,C:`Santral zon karsinomun en sık yeri değildir.`,D:`Anterior stroma glandüler değildir.`,E:`Doğru: periferik zon karsinomun ana yeridir.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-66-q53`,kazanim:18,zorluk:`orta`,soru:`BPH'nin erken dönemde idrar akımını engellemesi, prostat karsinomunun ise başlangıçta daha az üretral obstrüksiyon yapmasının nedeni hangisidir?`,secenekler:{A:`BPH'nin periferik zondan gelişmesi`,B:`BPH'nin iç transisyonel zondan, karsinomun periferik zondan gelişmesi`,C:`Karsinomun yalnızca santral zonda olması`,D:`BPH'nin malign olması`,E:`Karsinomun üretrayı her zaman sararak başlaması`},dogru:`B`,aciklama:`BPH üretrayı çevreleyen transisyonel zondan gelişerek erken obstrüksiyon yapar; karsinom periferik zonda olduğundan geç obstrüksiyon yapar.`,sik_aciklamalari:{A:`BPH transisyonel zondan gelişir.`,B:`Doğru: zonal yerleşim klinik farkı açıklar.`,C:`Karsinom çoğunlukla periferik zondadır.`,D:`BPH benigndir: BPH'nin malign olması.`,E:`Karsinom başlangıçta periferik yerleşimlidir.`},bilgi:[20,27,33],benzer_cikmis:[]},{id:`k1-66-q54`,kazanim:18,zorluk:`zor`,soru:`Normal prostat glandlarının histolojisi ile ilgili hangisi doğrudur?`,secenekler:{A:`Ürotelyum ile döşeli glandlar`,B:`Tek sıralı küboidal epitel, bazal tabaka yok`,C:`Çok katlı keratinize yassı epitel`,D:`Basık bazal hücre tabakası üzerinde kolumnar sekretuar epitelden oluşan iki tabakalı glandlar`,E:`Silyalı psödostratifiye epitel`},dogru:`D`,aciklama:`Normal prostat glandları iki hücre tabakalıdır; bazal tabakanın kaybı karsinom için önemli bir ipucudur.`,sik_aciklamalari:{A:`Prostat glandları ürotelyumla döşeli değildir.`,B:`Bazal tabaka yokluğu karsinomun özelliğidir.`,C:`Keratinize yassı epitel prostatta normal değildir.`,D:`Doğru: normal prostat glandının yapısıdır.`,E:`Silyalı epitel prostat glandının normal epiteli değildir.`},bilgi:[20,31],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k18-q04`,kazanim:18,zorluk:`orta`,soru:`Obstrüksiyonlu ve rektal nodüllü iki hastanın zonal kaynağı karşılaştırılıyor. Hangi eşleşme doğrudur?`,secenekler:{A:`Hiperplazi periferiktir`,B:`Karsinom transisyoneldir`,C:`Bazal tabaka malignitede korunur`,D:`Obstrüktif büyümeli hastada iç transisyonel kaynaklı BPH, rektal nodüllü hastada periferik kaynaklı karsinom (%70-80) düşünülür; benign glandda bazal tabaka vardır, malignde yoktur`,E:`Zonlar hastalığı belirlemez`},dogru:`D`,aciklama:`Periferik-transisyonel en önemli; hiperplazi iç transisyonel, karsinom %70-80 periferik; benignde bazal tabaka korunur, malignde kaybolur.`,sik_aciklamalari:{A:`Transisyoneldir.`,B:`Periferiktir.`,C:`Kaybolur.`,D:`Doğru: zon-hastalık-histoloji üçlüsü tamdır.`,E:`Belirler.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k18-q05`,kazanim:18,zorluk:`zor`,soru:`BPH'ın erken, karsinomun geç obstrüksiyon yapması açıklanıyor. Hangi açıklama doğrudur?`,secenekler:{A:`Normal gland tek tabakalıdır`,B:`Periferik tümör erken obstrüksiyon yapar`,C:`BPH iç yerleşimiyle erken obstrüksiyon, periferik karsinom rektal palpabilite verir; bu yüzden karsinom BPH'dan daha az üretral obstrüksiyon yapar`,D:`Transisyonel tümör palpe edilir`,E:`Bazal tabaka tanıda kullanılmaz`},dogru:`C`,aciklama:`Normal iki tabakalı (bazal+kolumnar sekretuar) gland; periferik yerleşim rektal palpasyonu, transisyonel üretral obstrüksiyonu açıklar.`,sik_aciklamalari:{A:`İki tabakalıdır.`,B:`Geç obstrüksiyon yapar.`,C:`Doğru: yerleşim-klinik ikilisi tamdır.`,D:`Derinde kalır.`,E:`Benignite-malignite ayrımıdır.`},bilgi:[20,33],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k18-q06`,kazanim:18,zorluk:`orta`,soru:`BPH ve kanser zon yerleşimleri nelerdir?`,secenekler:{A:`BPH transisyonel, kanser periferik zon kaynaklıdır`,B:`BPH periferiktir`,C:`Kanser transisyoneldir`,D:`Gland tek katlıdır`,E:`Zon farkı yoktur`},dogru:`A`,aciklama:`Hiperplazi iç transisyonel, karsinom %70-80 periferik zondandır. Normal gland iki katmanlıdır: bazal yassı, sekretuar kolumnar epitel.`,sik_aciklamalari:{A:`Doğru: iki hastalığın zonu birlikte doğru verilmiştir.`,B:`Hemen daima iç transisyoneldir.`,C:`%70-80 periferiktir.`,D:`İki hücre tabakalıdır.`,E:`Yerleşim tanı ve muayeneyi belirler.`},bilgi:[20],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k18-q07`,kazanim:18,zorluk:`orta`,soru:`Prostat histolojisi ve muayene ilişkisi nedir?`,secenekler:{A:`Gland tek katlıdır`,B:`Periferik palpe edilmez`,C:`İki katmanlı gland; periferik lezyon rektal nodüldür`,D:`Bazal yoktur`,E:`Zon muayeneyi etkilemez`},dogru:`C`,aciklama:`Normal prostat basık bazal tabaka üstünde kolumnar sekretuar epitelden iki katmanlı glandlar içerir. Periferik zon lezyonları rektal tuşede sert düzensiz nodül olarak palpe edilir; bu zon-klinik ilişkisi muayeneyi yönlendirir.`,sik_aciklamalari:{A:`İki hücre tabakalıdır.`,B:`Sert düzensiz nodül palpe edilir.`,C:`Doğru: histoloji ve muayene ilişkisi birlikte doğru verilmiştir.`,D:`Basıklaşmış bazal tabaka vardır.`,E:`Periferik yerleşim tuşe bulgusu verir.`},bilgi:[20,33],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k18-q08`,kazanim:18,zorluk:`kolay`,soru:`Aşağıdakilerden "Hidrosel, hematosel, şilosel ve elefantiazis" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{D:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,E:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,B:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,C:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,A:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`},dogru:`D`,aciklama:`Doğru: Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,sik_aciklamalari:{D:`Doğru. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,E:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,B:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,C:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,A:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`},bilgi:[10],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k18-q09`,kazanim:18,zorluk:`orta`,soru:`"BPH: epidemiyoloji ve androjen bağımlılığı" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{B:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,C:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,E:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,A:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,D:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`},dogru:`B`,aciklama:`Doğru: Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,sik_aciklamalari:{B:`Doğru. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,C:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,E:`Yanlış. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,A:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,D:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`},bilgi:[24],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k18-q10`,kazanim:18,zorluk:`orta`,soru:`"Prostat karsinomu patogenezi ve genetiği" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{E:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,D:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,A:`Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,C:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,B:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`},dogru:`E`,aciklama:`Doğru: Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,sik_aciklamalari:{E:`Doğru. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,D:`Yanlış. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,A:`Yanlış. Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,C:`Yanlış. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,B:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k18-q11`,kazanim:18,zorluk:`zor`,soru:`"Prostat zonal anatomisi ve histolojisi" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{A:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,E:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,D:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,C:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`},dogru:`A`,aciklama:`Doğru: Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,sik_aciklamalari:{A:`Doğru. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,E:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,D:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Yanlış. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,C:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`},bilgi:[20],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:19,metin:`Prostatitin dört kategorisini ve klinik özelliklerini açıklayabilmek`,sorular:[{id:`k1-66-q55`,kazanim:19,zorluk:`kolay`,soru:`Prostatit kategorileri arasında en sık görüleni hangisidir?`,secenekler:{A:`Asemptomatik inflamatuar prostatit`,B:`Akut bakteriyel prostatit`,C:`Kronik bakteriyel prostatit`,D:`Granülomatöz prostatit`,E:`Kronik nonbakteriyel prostatit/kronik pelvik ağrı sendromu`},dogru:`E`,aciklama:`Kronik nonbakteriyel prostatit/kronik pelvik ağrı sendromu olguların %90–95'ini oluşturur.`,sik_aciklamalari:{A:`Asemptomatik form en sık kategori olarak verilmemiştir.`,B:`Akut bakteriyel prostatit %2–5'tir.`,C:`Kronik bakteriyel prostatit %2–5'tir.`,D:`Granülomatöz prostatit dört ana kategoriden biri değildir.`,E:`Doğru: en sık kategoridir.`},bilgi:[21],benzer_cikmis:[]},{id:`k1-66-q56`,kazanim:19,zorluk:`orta`,soru:`Rektal muayenede hassas ve yumuşak prostat, dizüri ve ateş bulunan hastada en olası tanı ve dikkat edilmesi gereken komplikasyon hangisidir?`,secenekler:{A:`Kronik nonbakteriyel prostatit; hidronefroz`,B:`Akut bakteriyel prostatit; sepsis`,C:`BPH; akut retansiyon`,D:`Prostat karsinomu; kemik metastazı`,E:`Granülomatöz prostatit; tüberküloz menenjiti`},dogru:`B`,aciklama:`Akut bakteriyel prostatit dizüri, ateş ve hassas yumuşak prostat ile seyreder; sepsis gelişebilir.`,sik_aciklamalari:{A:`Kronik nonbakteriyel formda kültür negatiftir ve ateş beklenmez.`,B:`Doğru: tablo ve komplikasyon uyumludur.`,C:`BPH ateş ve hassasiyet yapmaz.`,D:`Karsinom sert düzensiz nodül yapar.`,E:`Granülomatöz prostatit endürasyon yapar.`},bilgi:[21,23],benzer_cikmis:[]},{id:`k1-66-q57`,kazanim:19,zorluk:`zor`,soru:`ABD'de granülomatöz prostatitin en yaygın nedeni ve biyopsi endikasyonunun gerekçesi hangisidir?`,secenekler:{A:`Kabakulak virüsü; ateş`,B:`Akut bakteriyel prostatit; sepsis riski`,C:`Mesane içine uygulanan BCG; prostatta endürasyon yaparak karsinomu taklit etmesi`,D:`Gonore; akıntı`,E:`BPH; nodül oluşumu`},dogru:`C`,aciklama:`Mesane içi BCG granülomatöz prostatitin en sık nedenidir; endürasyon yaptığından karsinomdan ayırmak için biyopsi gerekir.`,sik_aciklamalari:{A:`Kabakulak prostatit nedeni değildir.`,B:`Akut prostatitte sepsis riski nedeniyle biyopsi yapılmaz.`,C:`Doğru: BCG tüberküloza benzer histoloji oluşturur.`,D:`Gonore granülomatöz prostatit yapmaz.`,E:`BPH granülomatöz değildir.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k19-q04`,kazanim:19,zorluk:`orta`,soru:`Kültür negatif kronik pelvik ağrılı hastada kategori soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`Kültür negatif pelvik ağrılı hastada %90-95'lik kronik nonbakteriyel prostatit düşünülür; akut-kronik bakteriyel %2-5'er ve üropatojenlidir`,B:`Bakteriyel çoğunluktadır`,C:`Nonbakteriyelde üropatojen vardır`,D:`Kategori ikidir`,E:`Asemptomatik kategori yoktur`},dogru:`A`,aciklama:`Akut-kronik bakteriyel %2-5'er üropatojenli; kronik nonbakteriyel-pelvik ağrı %90-95 kültür negatif; asemptomatik inflamatuar dördüncü.`,sik_aciklamalari:{A:`Doğru: oran-kültür ikilisi tamdır.`,B:`%90-95 nonbakteriyeldir.`,C:`Tespit edilmez.`,D:`Dörttür.`,E:`Dördüncü kategoridir.`},bilgi:[21,23],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k19-q05`,kazanim:19,zorluk:`zor`,soru:`Ateşli prostatit ile BCG öykülü endurasyon karşılaştırılıyor. Hangi yönetim çifti doğrudur?`,secenekler:{A:`Akut prostatitte biyopsi ilk basamaktır`,B:`Kronik pelvik ağrının kanıtlı tedavisi vardır`,C:`Granülomatöz prostatitte biyopsi gerekmez`,D:`BCG prostatiti etkilemez`,E:`Ateşli-hassas prostatlı hastada akut bakteriyel (antibiyotik), endurasyonlu-BCG öykülüde granülomatöz (biyopsi) düşünülür; kronik pelvik ağrıda kanıtlanmış tedavi yoktur`},dogru:`E`,aciklama:`Akut hassas-yumuşak prostat-sepsis, kronik tekrarlayan İYE-bel ağrısı; nonbakteriyelde >10 lökosit; bakteriyel antibiyotikli, pelvik ağrı kanıtsız; granülomatöz endurasyonda (BCG) biyopsi gerekir.`,sik_aciklamalari:{A:`Sepsis riskiyle yapılmaz.`,B:`Yoktur.`,C:`Endurasyon biyopsi doğurur.`,D:`En yaygın sebeptir.`,E:`Doğru: klinik-biyopsi-tedavi üçlüsü tamdır.`},bilgi:[22,23],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k19-q06`,kazanim:19,zorluk:`orta`,soru:`Prostatit kategorilerinin kliniği nedir?`,secenekler:{A:`Akut serttir`,B:`Akut hassas-sepsili, kronik tekrarlayan, nonbakteriyel lökositlidir`,C:`Kronik tek ataktır`,D:`Lökosit olmaz`,E:`Dizüri olmaz`},dogru:`B`,aciklama:`Akut bakteriyel dizürili, hassas-yumuşak prostat ve sepsis risklidir. Kronik bakteriyel tekrarlayan İYE-bel-sırt ve perineal rahatsızlık; nonbakteriyelde alanda 10'dan fazla lökosit vardır.`,sik_aciklamalari:{A:`Hassas ve yumuşaktır.`,B:`Doğru: üç kategorinin kliniği birlikte doğru verilmiştir.`,C:`Tekrarlayan İYE yapar.`,D:`10'dan fazla lökosit görülür.`,E:`Dizüri birliktedir.`},bilgi:[23],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k19-q07`,kazanim:19,zorluk:`orta`,soru:`Granülomatöz prostatitte biyopsi endikasyonu nedir?`,secenekler:{A:`Biyopsi her prostatitte yapılır`,B:`Endurasyon biyopsiyi dışlar`,C:`Granülomatöz endurasyon biyopsi gerektirir; BCG en yaygın sebeptir`,D:`BCG ilişkisizdir`,E:`Sepsis riski yoktur`},dogru:`C`,aciklama:`Akut-kronik prostatitte bulgular nonspesifik ve sepsis riskiyle biyopsi genellikle yapılmaz. Granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar; ABD'de en yaygın sebebi mesane içi BCG aşısıdır.`,sik_aciklamalari:{A:`Nonspesifik bulgu ve sepsis riskiyle genellikle yapılmaz.`,B:`Endurasyon biyopsi endikasyonu doğurur.`,C:`Doğru: endikasyon ve BCG nedeni birlikte doğru verilmiştir.`,D:`ABD'de en yaygın sebeptir.`,E:`Akut bakteriyelde sepsis gelişebilir.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k19-q08`,kazanim:19,zorluk:`kolay`,soru:`"Granülomatöz orşit (tüberküloz)" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,B:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,D:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,E:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,C:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`},dogru:`A`,aciklama:`Doğru: Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,sik_aciklamalari:{A:`Doğru. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,B:`Yanlış. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,D:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,E:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,C:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k19-q09`,kazanim:19,zorluk:`orta`,soru:`"Spermatosel ve varikosel" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,B:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,C:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,E:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,D:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`},dogru:`A`,aciklama:`Doğru: Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,sik_aciklamalari:{A:`Doğru. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,B:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,C:`Yanlış. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,E:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,D:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k19-q10`,kazanim:19,zorluk:`orta`,soru:`"Prostat karsinomu patogenezi ve genetiği" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{E:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,B:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,A:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,C:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,D:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`},dogru:`E`,aciklama:`Doğru: Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,sik_aciklamalari:{E:`Doğru. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,B:`Yanlış. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,A:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,C:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,D:`Yanlış. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k19-q11`,kazanim:19,zorluk:`zor`,soru:`"Penis karsinomu: sıklık ve etyoloji" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{D:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,E:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,A:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,C:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,B:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`},dogru:`D`,aciklama:`Doğru: Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,sik_aciklamalari:{D:`Doğru. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,E:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,A:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,C:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,B:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`},bilgi:[4],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:20,metin:`Benign prostat hiperplazisinin patogenezini (DHT ve 5α-redüktaz) ve morfolojisini kavramak`,sorular:[{id:`k1-66-q58`,kazanim:20,zorluk:`kolay`,soru:`Prostat dokusundaki ana androjen hangisidir?`,secenekler:{A:`Androstenedion`,B:`Testosteron`,C:`Dihidrotestosteron (DHT)`,D:`DHEA`,E:`Östradiol`},dogru:`C`,aciklama:`DHT prostatik androjenlerin %90'ını oluşturur ve testosterondan tip 2 5α-redüktaz ile üretilir.`,sik_aciklamalari:{A:`Androstenedion zayıf bir androjendir.`,B:`Testosteron DHT'nin öncülüdür.`,C:`Doğru: prostatın ana androjenidir.`,D:`DHEA adrenal kökenli öncüldür.`,E:`Östradiol östrojendir.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-66-q59`,kazanim:20,zorluk:`orta`,soru:`Prostatta tip 2 5α-redüktaz enziminin neredeyse tamamı hangi hücrelerde bulunur?`,secenekler:{A:`Lüminal epitel hücreleri`,B:`Stromal hücreler`,C:`Bazal hücreler`,D:`Nöroendokrin hücreler`,E:`Lenfositler`},dogru:`B`,aciklama:`Tip 2 5α-redüktaz stromal hücrelerde lokalizedir; androjen bağımlı prostat büyümesinden stromal hücreler sorumludur.`,sik_aciklamalari:{A:`Lüminal epitel enzimin ana yeri değildir.`,B:`Doğru: enzim stromal hücrelerdedir.`,C:`Bazal hücreler enzimin ana yeri değildir.`,D:`Nöroendokrin hücreler enzimin ana yeri değildir.`,E:`Lenfositler ilişkili değildir.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-66-q60`,kazanim:20,zorluk:`zor`,soru:`BPH patogenezi ve morfolojisi ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`DHT'nin androjen reseptörüne afinitesi testosterondan fazladır`,B:`DHT FGF ve TGF-β gibi büyüme faktörlerini uyarır`,C:`Puberteden önce kastre edilenlerde BPH gelişmez`,D:`BPH'de glandlar bazal hücreli kolumnar epitelle döşelidir ve lümende korpora amilasea bulunur`,E:`BPH hemen daima periferik zondan gelişir ve rektal muayenede sert düzensiz nodül yapar`},dogru:`E`,aciklama:`BPH hemen daima iç transisyonel zondan gelişir; periferik zon ve sert düzensiz nodül karsinomun özelliğidir.`,sik_aciklamalari:{A:`Doğru ifade: DHT 10 kat daha güçlüdür.`,B:`Doğru ifade: büyüme faktörleri stimüle edilir.`,C:`Doğru ifade: androjen bağımlılığını gösterir.`,D:`Doğru ifade: BPH'nin mikroskopisidir.`,E:`Yanlış ifade (aranan cevap): bu karsinomun özelliğidir.`},bilgi:[24,26,27],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k20-q04`,kazanim:20,zorluk:`orta`,soru:`BPH'ın androjen bağımlılığı ve enzim kaynağı soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`BPH androjenden bağımsızdır`,B:`Kastrasyonda BPH çıkar`,C:`BPH stromal tip 2 5α-redüktazla üretilen DHT'ye (testosterondan 10 kat güçlü, %90'lık androjen) bağlıdır; kastrede çıkmaz ve yaşla %90'a ulaşır`,D:`Tip 1 prostatta baskındır`,E:`DHT %10'dur`},dogru:`C`,aciklama:`40 yaş üstü-sekizinci dekat %90, epitelyal-stromal androjen-bağımlı; kastrasyonda çıkmaz; DHT %90, stromal tip2 5α-redüktazla testosterondan, 10 kat güçlü.`,sik_aciklamalari:{A:`Bağımlıdır.`,B:`Çıkmaz.`,C:`Doğru: enzim-güç-epidemiyoloji üçlüsü tamdır.`,D:`Tip 2 stromaldadır.`,E:`%90'dır.`},bilgi:[24,25,26],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k20-q05`,kazanim:20,zorluk:`zor`,soru:`BPH'ın moleküler sinyali ve makroskopisi birlikte soruluyor. Hangi bütün doğrudur?`,secenekler:{A:`DHT apoptozu artırır`,B:`BPH periferiktir`,C:`Nodüller maligndir`,D:`DHT reseptöründe FGF-TGFβ uyarısıyla stromal çoğalma yapan BPH iç transisyonelden 60-100 g nodüllerle üretrayı basıklaştırır; glandlar bazal hücreli-korpora amilasealıdır`,E:`Üretra genişler`},dogru:`D`,aciklama:`DHT reseptöre bağlanıp FGF-TGFβ büyüme-sağkalım genlerini uyarır (stromal proliferasyon-epitelyal ölüm azalması); morfoloji transisyonel 60-100 g nodüller, basık üretra, korpora amilasealı glandlar.`,sik_aciklamalari:{A:`Sağkalımı destekler.`,B:`Transisyoneldir.`,C:`Benign nodüllerdir.`,D:`Doğru: sinyal-morfoloji ikilisi tamdır.`,E:`Yarık halini alır.`},bilgi:[26,27],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k20-q06`,kazanim:20,zorluk:`orta`,soru:`DHT etkisi ve alfa1 katkısı nedir?`,secenekler:{A:`DHT 10 kat güçlü uyarır; alfa1 tonus katkı yapar`,B:`DHT zayıftır`,C:`FGF baskılanır`,D:`Alfa1 gevşektir`,E:`Reseptör yoktur`},dogru:`A`,aciklama:`DHT reseptöre testosterondan sıkı ve 10 kat güçlü bağlanıp FGF-TGF-beta genlerini uyararak büyüme-sağkalımı destekler. Alfa1 düz kas tonusu da obstrüksiyona katılır.`,sik_aciklamalari:{A:`Doğru: afinite farkı ve stromal-epitelyal uyarım birlikte doğru verilmiştir.`,B:`10 kat güçlüdür.`,C:`FGF-TGF-beta stimüle edilir.`,D:`Alfa1 düz kas katkısı vardır.`,E:`Androjen reseptörlerine bağlanır.`},bilgi:[26],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k20-q07`,kazanim:20,zorluk:`orta`,soru:`BPH morfolojisi ve klinik oranı nedir?`,secenekler:{A:`BPH periferiktir`,B:`Üretra geniştir`,C:`BPH nodüler 60-100 gram, üretra basıktır; %10 semptomatiktir`,D:`Amilasea maligndir`,E:`Bazal yoktur`},dogru:`C`,aciklama:`BPH transisyonel nodüllerle 60-100 gram, üretra basık yarıktır; mikroskopta fibromüsküler stromada bazal hücreli kolumnar glandlar ve korpora amilasea vardır. %10'u klinik bulgu verir.`,sik_aciklamalari:{A:`İç transisyoneldir.`,B:`Dar yarık halini alır.`,C:`Doğru: makro-mikro ve klinik oran birlikte doğru verilmiştir.`,D:`Lümen içeriğidir.`,E:`Basıklaşmış bazal hücre vardır.`},bilgi:[27,28],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k20-q08`,kazanim:20,zorluk:`kolay`,soru:`Aşağıdakilerden "BPH: DHT etkisi ve α1-adrenerjik düz kas" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{E:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,D:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,C:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,A:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`},dogru:`E`,aciklama:`Doğru: DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,sik_aciklamalari:{E:`Doğru. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,D:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,C:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,A:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`},bilgi:[26],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k20-q09`,kazanim:20,zorluk:`orta`,soru:`"Peyronie hastalığı" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,C:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,D:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,A:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,E:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`},dogru:`B`,aciklama:`Doğru: Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,sik_aciklamalari:{B:`Doğru. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,C:`Yanlış. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,D:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,A:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,E:`Yanlış. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`},bilgi:[8],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k20-q10`,kazanim:20,zorluk:`orta`,soru:`"Kriptorşidizm: sterilite ve kanser riski" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{C:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,A:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,E:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,D:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,B:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`},dogru:`C`,aciklama:`Doğru: İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,sik_aciklamalari:{C:`Doğru. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,A:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,E:`Yanlış. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,D:`Yanlış. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,B:`Yanlış. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k20-q11`,kazanim:20,zorluk:`zor`,soru:`"Gleason derecelendirmesi" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,D:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,B:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,C:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,A:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`},dogru:`E`,aciklama:`Doğru: Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,sik_aciklamalari:{E:`Doğru. Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,D:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,B:`Yanlış. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,C:`Yanlış. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,A:`Yanlış. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`},bilgi:[32],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:21,metin:`Benign prostat hiperplazisinin klinik özelliklerini ve tedavisini açıklayabilmek`,sorular:[{id:`k1-66-q61`,kazanim:21,zorluk:`kolay`,soru:`BPH'de en yaygın klinik bulgular hangi sorunla ilişkilidir?`,secenekler:{A:`Jinekomasti`,B:`Ağrısız hematüri`,C:`Kemik metastazı`,D:`Alt idrar yolu tıkanıklığı`,E:`Skrotal şişlik`},dogru:`D`,aciklama:`BPH iç tabakada geliştiğinden idrar başlatmada zorluk, kesintili akış, sık ve gece işeme gibi tıkanıklık bulguları yapar.`,sik_aciklamalari:{A:`Jinekomasti östrojen fazlalığına bağlıdır.`,B:`Ağrısız hematüri ürotelyal karsinomu düşündürür.`,C:`Kemik metastazı prostat karsinomunda görülür.`,D:`Doğru: obstrüktif semptomlar ön plandadır.`,E:`Skrotal şişlik hidrosel vb. ile ilişkilidir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-66-q62`,kazanim:21,zorluk:`orta`,soru:`BPH'nin başlangıç farmakolojik tedavisinde kullanılan ilaç–mekanizma eşleştirmesi hangisinde doğrudur?`,secenekler:{A:`LHRH agonisti – düz kas gevşemesi`,B:`Finasterid – α1 reseptör blokajı`,C:`Alfa blokör – 5α-redüktaz inhibisyonu`,D:`Trastuzumab – HER2 blokajı`,E:`Finasterid – DHT sentezinin inhibisyonu; alfa blokör – düz kas gevşemesi`},dogru:`E`,aciklama:`Başlangıç tedavisi DHT inhibisyonu (finasterid) veya α-adrenerjik blokajla düz kas gevşemesidir; dirençli olgularda cerrahi yapılır.`,sik_aciklamalari:{A:`LHRH agonistleri androjen yoksunluğu yaratır.`,B:`Finasterid 5α-redüktaz inhibitörüdür.`,C:`Alfa blokörler α1 reseptörlerini bloke eder.`,D:`Trastuzumab meme kanserinde kullanılır.`,E:`Doğru: iki ilaç grubu doğru eşleştirilmiştir.`},bilgi:[26,28],benzer_cikmis:[]},{id:`k1-66-q63`,kazanim:21,zorluk:`zor`,soru:`BPH ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Patolojik BPH'li erkeklerin yalnızca ~%10'unda klinik bulgu vardır`,B:`Tam tıkanıklık ağrılı mesane distansiyonu yapar`,C:`Tedavi edilmezse hidronefroza yol açabilir`,D:`Obstrüksiyon semptomları α1-adrenerjik düz kas kontraksiyonu ile şiddetlenir`,E:`BPH prekanseröz bir lezyondur ve prostat karsinomuna dönüşür`},dogru:`E`,aciklama:`BPH benign hiperplazidir; karsinom farklı zondan (periferik) gelişir ve BPH prekanseröz kabul edilmez.`,sik_aciklamalari:{A:`Doğru ifade: çoğu olgu asemptomatiktir.`,B:`Doğru ifade: tam tıkanıklık retansiyon yapar.`,C:`Doğru ifade: uzun süreli obstrüksiyon hidronefroz yapar.`,D:`Doğru ifade: alfa blokörlerin kullanım gerekçesidir.`,E:`Yanlış ifade (aranan cevap): BPH prekanseröz değildir.`},bilgi:[20,26,28],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k21-q04`,kazanim:21,zorluk:`orta`,soru:`Alt idrar yolu yakınmalı yaşlıda BPH tedavisi soruluyor. Hangi plan doğrudur?`,secenekler:{A:`BPH'lıların çoğu semptomatiktir`,B:`BPH üst yolak yapar`,C:`Tam tıkanıklık zararsızdır`,D:`İlk tedavi cerrahidir`,E:`Gece sık idrar-kesintili akımlı hastada BPH'a bağlı alt yolak tıkanıklığı düşünülür (%10 klinik); ilk tedavi DHT inhibisyonu (finasterid) veya alfa blokördür (flomax)`},dogru:`E`,aciklama:`Patolojiklerin %10'u klinik; alt idrar yolu tıkanıklığı (başlatma zorluğu-kesinti-sık-gece); tam tıkanıklık ağrılı distansiyon-hidronefroz; tedavi finasterid-flomax, dirençte cerrahi.`,sik_aciklamalari:{A:`%10'udur.`,B:`Alt yolaktır.`,C:`Hidronefroz yapar.`,D:`Farmakolojiktir.`,E:`Doğru: klinik-tedavi ikilisi tamdır.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k21-q05`,kazanim:21,zorluk:`zor`,soru:`Tam tıkanıklıklı hastada iki ilaç sınıfının mantığı soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`Alfa blokör kontraksiyonu artırır`,B:`İdrar yapamayan-ağrılı globlu hastada tam tıkanıklık vardır; α1 aracılı düz kas kontraksiyonu tabloyu şiddetlendirir ve alfa blokör gevşetir, finasterid DHT'yi baskılar`,C:`Finasterid α1 bloke eder`,D:`Flomax hacmi küçültür`,E:`Cerrahi ilk seçenektir`},dogru:`B`,aciklama:`α1 düz kas kontraksiyonu obstrüksiyonu şiddetlendirir; flomax gevşetir, finasterid hacmi küçültür; tam tıkanıklıkta kateter-cerrahi gerekir.`,sik_aciklamalari:{A:`Gevşetir.`,B:`Doğru: mekanizma-ilaç ikilisi tamdır.`,C:`DHT inhibe eder.`,D:`Finasterid küçültür.`,E:`Dirençtedir.`},bilgi:[26,28],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k21-q06`,kazanim:21,zorluk:`orta`,soru:`BPH semptomları ve komplikasyonu nedir?`,secenekler:{A:`BPH irritatif değildir`,B:`Obstrüktif işeme + noktüri yapar; tam tıkanıklık hidronefroz eder`,C:`Distansiyon ağrısızdır`,D:`Hidronefroz olmaz`,E:`Tedavi antibiyotiktir`},dogru:`B`,aciklama:`İç tabaka yerleşimiyle alt idrar yolu tıkanıklığı: başlatma güçlüğü, kesinti, sık-gece işeme; tam tıkanıklık ağrılı distansiyon ve hidronefroz yapar. Tedavi alfa1 blokajı, 5-alfa redüktaz inhibisyonu ve cerrahidir.`,sik_aciklamalari:{A:`Tıkanıklık bulguları tipiktir.`,B:`Doğru: semptomlar ve komplikasyon birlikte doğru verilmiştir.`,C:`Ağrılı mesane distansiyonudur.`,D:`Tedavisiz hidronefroz olur.`,E:`Alfa blokör-redüktaz inhibitörü-cerrahi kullanılır.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k21-q07`,kazanim:21,zorluk:`orta`,soru:`BPH epidemiyolojisi ve tedavisi nedir?`,secenekler:{A:`BPH gençte sıktır`,B:`Androjensiz gelişir`,C:`Tedavi antibiyotiktir`,D:`Kastrasyonda gelişir`,E:`BPH yaşla androjen bağımlıdır; alfa blokör-redüktaz-cerrahi uygulanır`},dogru:`E`,aciklama:`BPH 40 yaş üstünde yaşla artar, sekizinci dekatta %90'a ulaşır; epitel-stroma artışıdır ve prepubertal kastrasyonda gelişmez. Tedavide alfa1 blokörler, 5-alfa redüktaz inhibitörleri ve cerrahi kullanılır.`,sik_aciklamalari:{A:`40 üstü yaşla artar.`,B:`Kastrasyonda ortaya çıkmaz.`,C:`Alfa blokör ve redüktaz inhibitörü kullanılır.`,D:`Androjen bağımlıdır.`,E:`Doğru: epidemiyoloji ve tedavi birlikte doğru verilmiştir.`},bilgi:[24,28],benzer_cikmis:[`30990b3fbc41`]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k21-q08`,kazanim:21,zorluk:`kolay`,soru:`"Granülomatöz orşit (tüberküloz)" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,E:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,B:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,D:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,A:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`},dogru:`C`,aciklama:`Doğru: Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,sik_aciklamalari:{C:`Doğru. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,E:`Yanlış. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,B:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,D:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,A:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`},bilgi:[17],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k21-q09`,kazanim:21,zorluk:`orta`,soru:`"Kriptorşidizm: sterilite ve kanser riski" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,B:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,C:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,A:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,D:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`},dogru:`E`,aciklama:`Doğru: İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,sik_aciklamalari:{E:`Doğru. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,B:`Yanlış. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,C:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,A:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,D:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`},bilgi:[13],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k21-q10`,kazanim:21,zorluk:`orta`,soru:`"Non-seminomatöz germ hücre tümörleri" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,B:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,E:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,D:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,C:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`},dogru:`A`,aciklama:`Doğru: Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,sik_aciklamalari:{A:`Doğru. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,B:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,E:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,D:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,C:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`},bilgi:[39],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k21-q11`,kazanim:21,zorluk:`zor`,soru:`"Verrüköz karsinom" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{C:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,B:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,A:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,E:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,D:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`},dogru:`C`,aciklama:`Doğru: Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,sik_aciklamalari:{C:`Doğru. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,B:`Yanlış. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,A:`Yanlış. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,E:`Yanlış. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,D:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`},bilgi:[7],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:22,metin:`Prostat karsinomunun epidemiyolojisini ve patogenezini açıklayabilmek`,sorular:[{id:`k1-66-q64`,kazanim:22,zorluk:`kolay`,soru:`Erkeklerde en sık görülen kanser hangisidir?`,secenekler:{A:`Mesane ürotelyal karsinomu`,B:`Testis seminomu`,C:`Penis SCC`,D:`Prostat adenokarsinomu`,E:`Renal hücreli karsinom`},dogru:`D`,aciklama:`Prostat adenokarsinomu erkeklerde en sık kanserdir ve esas olarak 50 yaş üstünde görülür.`,sik_aciklamalari:{A:`Mesane kanseri prostat kanseri kadar sık değildir.`,B:`Seminom genç erkeklerde görülür ve daha seyrektir.`,C:`Penis karsinomu nadirdir.`,D:`Doğru: erkeklerde en sık kanserdir.`,E:`RHK daha seyrektir: renal hücreli karsinom.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-66-q65`,kazanim:22,zorluk:`orta`,soru:`Prostat karsinomu patogenezi ile ilgili hangisi doğrudur?`,secenekler:{A:`Esas olarak 30 yaş altında görülür`,B:`Androjenlerin rolü yoktur`,C:`Risk Asyalılarda en yüksektir`,D:`Yalnızca kalıtsal mutasyonlarla gelişir`,E:`Androjenler merkezi önemdedir; puberteden önce kastre edilenlerde gelişmez`},dogru:`E`,aciklama:`Patogenezde edinsel somatik mutasyonlar ve androjenler rol oynar; risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,sik_aciklamalari:{A:`50 yaş üstü erkeklerin hastalığıdır.`,B:`Androjenler merkezi önemdedir.`,C:`Risk Asyalılarda en düşüktür.`,D:`Edinsel somatik mutasyonlar rol oynar.`,E:`Doğru: androjen bağımlılığı temeldir.`},bilgi:[29,30],benzer_cikmis:[]},{id:`k1-66-q66`,kazanim:22,zorluk:`zor`,soru:`Prostat karsinomunun doğal seyri ile ilgili hangisi doğrudur?`,secenekler:{A:`Ölüm oranı akciğer kanserinden yüksektir`,B:`Her olguda hızla ölümcül seyreder`,C:`Çok agresif olabildiği gibi klinik olarak önemsiz, ılımlı bir seyir de gösterebilir; çoğu erkek prostat kanseriyle ölür, ondan değil`,D:`Tüm kanser ölümlerinin yarısından sorumludur`,E:`Hiçbir zaman metastaz yapmaz`},dogru:`C`,aciklama:`Prostat karsinomunun doğal seyri çok değişkendir; tüm kanser ölümlerinin ~%9'undan sorumludur.`,sik_aciklamalari:{A:`Ölüm oranı akciğer kanserinden düşüktür.`,B:`Birçok olgu ılımlı seyreder.`,C:`Doğru: değişken doğal seyir tedavi seçimini etkiler.`,D:`Kanser ölümlerinin ~%9'undan sorumludur.`,E:`Özellikle kemiğe metastaz yapabilir.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k22-q04`,kazanim:22,zorluk:`orta`,soru:`Prostat kanserinin sıklık-seyir-hormon ilişkisi soruluyor. Hangi özet doğrudur?`,secenekler:{A:`Gençlerin en sık kanseridir`,B:`Ölümde akciğeri geçer`,C:`Seyri daima agresiftir`,D:`50 üstü en sık kanserdir; seyri ılımlı-agresif arası değişir ve androjen bağımlıdır (prepubertal kastrasyonda gelişmez)`,E:`Androjen ilişkisizdir`},dogru:`D`,aciklama:`50 üstü en sık kanser; ölüm akciğerden az-kolorektalle eşit (%9); agresiften ılımlıya değişir; çoğu kanserle değil kanserle ölür; androjen merkezi (prepubertal kastrasyonda çıkmaz).`,sik_aciklamalari:{A:`50 üstüdür.`,B:`Akciğerden azdır.`,C:`Değişkendir.`,D:`Doğru: sıklık-seyir-androjen üçlüsü tamdır.`,E:`Merkezidir.`},bilgi:[29,30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k22-q05`,kazanim:22,zorluk:`zor`,soru:`Irk riski ve hormon direnci mekanizması soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`Siyah ırkta risk en yüksek, Asyalılarda en düşüktür; antiandrojen direncinde androjen reseptörünü hedef genleri aktive edecek şekilde çalıştıran mutasyonlar gelişir`,B:`Irk riski etkilemez`,C:`Dirençte reseptör kaybolur`,D:`Asyalılarda en yüksektir`,E:`Mutasyon dirençte yoktur`},dogru:`A`,aciklama:`Risk siyahlarda en yüksek-Asyalılarda en düşük; antiandrojene cevapsızda reseptörü aktive eden edinsel mutasyonlar vardır.`,sik_aciklamalari:{A:`Doğru: ırk-direnç ikilisi tamdır.`,B:`Belirleyicidir.`,C:`Aktive edici mutasyonlardır.`,D:`En düşüktür.`,E:`Vardır.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k22-q06`,kazanim:22,zorluk:`orta`,soru:`Prostat kanseri sıklığı ve androjen rolü nedir?`,secenekler:{A:`Gençte sıktır`,B:`Ölüm ilk sıradadır`,C:`Androjensiz gelişir`,D:`50 üstü en sık kanserdir; androjen bağımlıdır`,E:`Kadında sıktır`},dogru:`D`,aciklama:`Prostat adenokarsinomu 50 üstü erkeklerin en sık kanseridir; ölüm akciğerden az, kolorektalle eşit ve tüm kanser ölümlerinin %9'udur. Androjenler merkezidir; prepubertal kastrasyonda hastalık gelişmez.`,sik_aciklamalari:{A:`50 üstü oluşur.`,B:`Akciğerden az, kolorektalle eşittir.`,C:`Kastrasyonda gelişmez.`,D:`Doğru: sıklık ve androjen rolü birlikte doğru verilmiştir.`,E:`Erkek kanseridir.`},bilgi:[29,30],benzer_cikmis:[`3a7e8b4ccc33`]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k22-q07`,kazanim:22,zorluk:`orta`,soru:`Prostat kanseri somatik genetiği ve etnik risk nedir?`,secenekler:{A:`Germline baskındır`,B:`Somatik TMPRSS2-PTEN yolakları ve etnik risk farkı vardır`,C:`Füzyon nadirdir`,D:`PTEN aktive olur`,E:`Etnik fark yoktur`},dogru:`B`,aciklama:`Patogenezde edinsel somatik mutasyonlar rol oynar; TMPRSS2-ETS füzyonu beyazların %40-60'ında, PTEN inaktivasyonuyla PI3K-AKT aktivasyonu sıktır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,sik_aciklamalari:{A:`Edinsel somatik mutasyonlar rol oynar.`,B:`Doğru: moleküler yolaklar ve etnik fark birlikte doğru verilmiştir.`,C:`%40-60'ta bulunur.`,D:`İnaktive eden mutasyonlardır.`,E:`Siyahlarda yüksek, Asyalılarda düşüktür.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k22-q08`,kazanim:22,zorluk:`kolay`,soru:`"Granülomatöz prostatit ve biyopsi endikasyonu" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{D:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,B:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,A:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,C:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,E:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`},dogru:`D`,aciklama:`Doğru: Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,sik_aciklamalari:{D:`Doğru. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,B:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,A:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,C:`Yanlış. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,E:`Yanlış. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k22-q09`,kazanim:22,zorluk:`orta`,soru:`"DHT ve 5α-redüktaz tip 2" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,E:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,C:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,B:`Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,D:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`},dogru:`A`,aciklama:`Doğru: Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,sik_aciklamalari:{A:`Doğru. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,E:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,C:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,B:`Yanlış. Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,D:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k22-q10`,kazanim:22,zorluk:`orta`,soru:`"BPH klinik özellikleri ve tedavi" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,D:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,C:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,E:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`},dogru:`A`,aciklama:`Doğru: Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,sik_aciklamalari:{A:`Doğru. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,D:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,C:`Yanlış. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,E:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k22-q11`,kazanim:22,zorluk:`zor`,soru:`"Balanit, balanopostit ve fimozis" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{E:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,B:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,D:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,A:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,C:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`},dogru:`E`,aciklama:`Doğru: Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,sik_aciklamalari:{E:`Doğru. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,B:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,D:`Yanlış. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,A:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,C:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`},bilgi:[3],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:23,metin:`Prostat karsinomunun moleküler özelliklerini (TMPRSS2-ETS füzyonu, PTEN) bilmek`,sorular:[{id:`k1-66-q67`,kazanim:23,zorluk:`kolay`,soru:`Beyaz ırktaki prostat kanserlerinin %40–60'ında bulunan genetik değişiklik hangisidir?`,secenekler:{A:`BCR-ABL füzyonu`,B:`TMPRSS2-ETS füzyon genleri`,C:`VHL kaybı`,D:`MET amplifikasyonu`,E:`i(12p)`},dogru:`B`,aciklama:`TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40–60'ında bulunur.`,sik_aciklamalari:{A:`BCR-ABL KML'de görülür.`,B:`Doğru: prostat kanserinin karakteristik füzyonudur.`,C:`VHL kaybı berrak hücreli RHK'da görülür.`,D:`MET papiller RHK ile ilişkilidir.`,E:`i(12p) germ hücreli tümörlerde görülür.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-q68`,kazanim:23,zorluk:`orta`,soru:`Prostat kanserinde PI3K/AKT yolunu aktive eden en yaygın mutasyon hangisidir?`,secenekler:{A:`PTEN'i inaktive eden mutasyonlar`,B:`KRAS aktive edici mutasyon`,C:`FGFR3 mutasyonu`,D:`BRAF mutasyonu`,E:`TP53 kazanımı`},dogru:`A`,aciklama:`PI3K/AKT yolunu aktive eden mutasyonların en yaygını PTEN inaktivasyonudur.`,sik_aciklamalari:{A:`Doğru: PTEN kaybı PI3K/AKT yolunu aktive eder.`,B:`KRAS bu yolun ana prostat mutasyonu olarak verilmemiştir.`,C:`FGFR3 mesane düşük dereceli papiller tümörlerle ilişkilidir.`,D:`BRAF düşük dereceli seröz over karsinomuyla ilişkilidir.`,E:`TP53 bir tümör baskılayıcıdır; kazanım ifadesi uygun değildir.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-q69`,kazanim:23,zorluk:`zor`,soru:`Prostat karsinomunun moleküler özellikleri ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Patogenezde edinsel somatik mutasyonlar rol oynar`,B:`TMPRSS2-ETS füzyonu sık görülür`,C:`PTEN inaktivasyonu PI3K/AKT yolunu aktive eder`,D:`Androjen sinyali patogenezde merkezi önemdedir`,E:`Prostat karsinomlarının çoğu kalıtsal VHL mutasyonuyla gelişir`},dogru:`E`,aciklama:`VHL mutasyonu berrak hücreli RHK ve VHL hastalığıyla ilişkilidir; prostat karsinomunda değildir.`,sik_aciklamalari:{A:`Doğru ifade: somatik mutasyonlar rol oynar.`,B:`Doğru ifade: füzyon sıktır.`,C:`Doğru ifade: PTEN kaybı yolu aktive eder.`,D:`Doğru ifade: androjenler merkezi rol oynar.`,E:`Yanlış ifade (aranan cevap): VHL prostat kanserinin temel mutasyonu değildir.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k23-q04`,kazanim:23,zorluk:`orta`,soru:`Prostat kanserinin iki sık moleküler olayı soruluyor. Hangi çift doğrudur?`,secenekler:{A:`Füzyon %1'dir`,B:`PTEN aktivasyonu sıktır`,C:`Mutasyonlar germlinedir`,D:`PI3K yolu baskılanır`,E:`Beyaz ırktaki kanserlerin %40-60'ında TMPRSS2-ETS füzyonu ve PTEN inaktivasyonuyla PI3K-AKT aktivasyonu görülür`},dogru:`E`,aciklama:`TMPRSS2-ETS beyaz ırkta %40-60; PI3K-AKT aktivasyonu, en yaygın PTEN inaktivasyonu; somatik edinsel mutasyonlar patogenezde.`,sik_aciklamalari:{A:`%40-60'tır.`,B:`İnaktivasyon sıktır.`,C:`Somatiktir.`,D:`Aktive olur.`,E:`Doğru: füzyon-yolak ikilisi tamdır.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k23-q05`,kazanim:23,zorluk:`zor`,soru:`Dirençli tümörün moleküler raporu yorumlanıyor. Hangi yorum doğrudur?`,secenekler:{A:`Moleküler bulgu tedaviyi etkilemez`,B:`Hormon dirençli tümörde reseptör-mutant aktivasyonu ile füzyon-yolak değişikliklerinin birlikte saptanması direnç-tedavi ilişkisini açıklar`,C:`Füzyon dirençte kaybolur`,D:`PTEN kaybı koruyucudur`,E:`Dirençte mutasyon yoktur`},dogru:`B`,aciklama:`Edinsel mutasyonlar antiandrojen direncini açıklar; füzyon-yolak birlikteliği hedef tedaviye zemin hazırlar.`,sik_aciklamalari:{A:`Zemin hazırlar.`,B:`Doğru: direnç-moleküler ikilisi tamdır.`,C:`Sürer.`,D:`Yolak aktive eder.`,E:`Vardır.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k23-q06`,kazanim:23,zorluk:`orta`,soru:`TMPRSS2-ETS ve PTEN anlamı nedir?`,secenekler:{A:`Füzyon %5'tir`,B:`TMPRSS2-ETS %40-60, PTEN PI3K-AKT'ı aktive eder`,C:`PTEN aktive olur`,D:`Yolak baskılanır`,E:`Androjen ilişkisizdir`},dogru:`B`,aciklama:`TMPRSS2-ETS beyazların %40-60'ındadır; PTEN inaktivasyonu PI3K-AKT'ı aktive eder. Bu yolaklar androjen bağımlılığıyla birlikte hedeflenir.`,sik_aciklamalari:{A:`%40-60'ta bulunur.`,B:`Doğru: iki moleküler olay birlikte doğru verilmiştir.`,C:`İnaktive eden mutasyonlardır.`,D:`PI3K-AKT aktive olur.`,E:`Androjenler merkezidir.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k23-q07`,kazanim:23,zorluk:`orta`,soru:`PTEN-PI3K-AKT yolağının anlamı nedir?`,secenekler:{A:`PTEN aktive olur`,B:`Yolak baskılanır`,C:`Füzyon yolaktan bağımsızdır`,D:`PTEN kaybı PI3K-AKT'ı aktive eder; androjenle birlikte hedeflenir`,E:`Mutasyon nadirdir`},dogru:`D`,aciklama:`PTEN inaktivasyonu PI3K-AKT yolunu aktive eder ve en yaygın yolak mutasyonudur. Füzyon-yolak birlikteliği androjen bağımlılığıyla kastrasyon duyarlılığını açıklar.`,sik_aciklamalari:{A:`İnaktive eden mutasyonlardır.`,B:`PI3K-AKT aktive olur.`,C:`Birlikte androjen bağımlılığını açıklar.`,D:`Doğru: yolak etkisi ve tedavi ilişkisi birlikte doğru verilmiştir.`,E:`En yaygın mutasyonlardır.`},bilgi:[30],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k23-q08`,kazanim:23,zorluk:`kolay`,soru:`"Testis tümörü belirteçleri, klinik ve tedavi" kavramının tanımı aşağıdakilerden hangisidir?`,secenekler:{D:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,E:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,A:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,C:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,B:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`},dogru:`D`,aciklama:`Doğru: hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,sik_aciklamalari:{D:`Doğru. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,E:`Yanlış. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,A:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,C:`Yanlış. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,B:`Yanlış. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k23-q09`,kazanim:23,zorluk:`orta`,soru:`"Kriptorşidizm: tanım, iniş ve sıklık" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,D:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,A:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,B:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,C:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`},dogru:`E`,aciklama:`Doğru: Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,sik_aciklamalari:{E:`Doğru. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,D:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,A:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,B:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,C:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`},bilgi:[12],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k23-q10`,kazanim:23,zorluk:`orta`,soru:`"BPH klinik özellikleri ve tedavi" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,D:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,E:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,B:`Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,C:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`},dogru:`A`,aciklama:`Doğru: Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,sik_aciklamalari:{A:`Doğru. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,D:`Yanlış. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,E:`Yanlış. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,B:`Yanlış. Seminomlar germ hücreli neoplazilerin ~%50'sini oluşturur; büyük, yumuşak, iyi sınırlı, homojen gri-beyaz kitle olup glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içerir; %15'inde sinsityotrofoblast bulunur. Spermatositik seminom ise genellikle 65 yaş ve üstünde görülür.`,C:`Yanlış. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k23-q11`,kazanim:23,zorluk:`zor`,soru:`"Kriptorşidizm: sterilite ve kanser riski" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{D:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,A:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,B:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,C:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,E:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`},dogru:`D`,aciklama:`Doğru: İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,sik_aciklamalari:{D:`Doğru. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,A:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,B:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,C:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,E:`Yanlış. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`},bilgi:[13],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:24,metin:`Prostat karsinomunun morfolojik özelliklerini ve prekürsör lezyonlarını (PİN) tanımlayabilmek`,sorular:[{id:`k1-66-q70`,kazanim:24,zorluk:`kolay`,soru:`Prostat karsinomu için çıkarılan dokuların ~%80'inde bulunan prekürsör lezyon hangisidir?`,secenekler:{A:`Yüksek dereceli prostatik intraepitelyal neoplazi (PİN)`,B:`BPH`,C:`Granülomatöz prostatit`,D:`Korpora amilasea`,E:`Bazal hücre hiperplazisi`},dogru:`A`,aciklama:`Olguların ~%80'inde karsinomla birlikte yüksek dereceli PİN bulunur.`,sik_aciklamalari:{A:`Doğru: PİN prekürsör lezyondur.`,B:`BPH prekürsör lezyon değildir.`,C:`Granülomatöz prostatit inflamatuardır.`,D:`Korpora amilasea normal/BPH glandlarında görülen salgı birikimidir.`,E:`Bazal hücre hiperplazisi prekürsör olarak verilmemiştir.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-66-q71`,kazanim:24,zorluk:`orta`,soru:`Prostat adenokarsinomunu benign glandlardan ayıran en önemli histolojik özellik hangisidir?`,secenekler:{A:`Bazal hücre tabakasının olmaması`,B:`Belirgin nükleer pleomorfizm ve çok sayıda mitoz`,C:`Lümende korpora amilasea`,D:`İki tabakalı epitel`,E:`Fibromüsküler stroma varlığı`},dogru:`A`,aciklama:`Karsinom glandları tek sıralı küboidal/alçak kolumnar epitelle döşelidir ve bazal tabaka yoktur; pleomorfizm belirgin değil, mitoz nadirdir.`,sik_aciklamalari:{A:`Doğru: bazal tabaka kaybı tanısal ipucudur.`,B:`Prostat karsinomunda pleomorfizm genellikle belirgin değildir ve mitoz nadirdir.`,C:`Korpora amilasea benign glandlarda görülür.`,D:`İki tabakalı epitel benign glandın özelliğidir.`,E:`Fibromüsküler stroma normal prostatta vardır.`},bilgi:[20,31],benzer_cikmis:[]},{id:`k1-66-q72`,kazanim:24,zorluk:`zor`,soru:`Prostat karsinomunun morfolojik özellikleri ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Lezyonların çoğu orta derecede diferansiye adenokarsinomlardır`,B:`Glandlar benign glandlardan daha küçüktür`,C:`Nükleuslar büyümüş ve belirgin nükleollüdür`,D:`Glandlar tek sıralı üniform epitelle döşelidir`,E:`Belirgin pleomorfizm ve sık mitoz tanı için zorunludur`},dogru:`E`,aciklama:`Prostat karsinomunda pleomorfizm genellikle belirgin değildir ve mitoz nadirdir.`,sik_aciklamalari:{A:`Doğru ifade: çoğu orta diferansiyedir.`,B:`Doğru ifade: glandlar daha küçüktür.`,C:`Doğru ifade: belirgin nükleol önemli bulgudur.`,D:`Doğru ifade: tek sıralı epitel ve bazal tabaka yokluğu vardır.`,E:`Yanlış ifade (aranan cevap): pleomorfizm ve mitoz belirgin değildir.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k24-q04`,kazanim:24,zorluk:`orta`,soru:`Prostat biyopsisi morfolojisi ve eşlikçi lezyon soruluyor. Hangi tanı doğrudur?`,secenekler:{A:`Biyopside küçük-bir arada, tek sıralı, bazal tabakasız, belirgin nükleollü glandlar adenokarsinomu düşündürür; olguların ~%80'inde yüksek dereceli PİN eşlik eder`,B:`Bazal tabaka malignitede korunur`,C:`Pleomorfizm belirgindir`,D:`Mitoz sıktır`,E:`PİN benign hilerdir`},dogru:`A`,aciklama:`Küçük-bir arada glandlar, tek sıralı üniform epitel, bazal tabaka yok, büyük-belirgin nükleol, pleomorfizm belirsiz-mitoz nadir; %80 yüksek dereceli PİN eşlik eder.`,sik_aciklamalari:{A:`Doğru: morfoloji-prekürsör ikilisi tamdır.`,B:`İzlenmez.`,C:`Belirgin değildir.`,D:`Nadirdir.`,E:`Prekürsördür.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k24-q05`,kazanim:24,zorluk:`zor`,soru:`Benign-malign gland ayrımı ve PİN'in yeri soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`Bazal tabaka her ikisinde vardır`,B:`PİN invazivdir`,C:`Benign glandda bazal tabaka korunurken malignde kaybolması ayırıcıdır ve yüksek dereceli PİN prekürsör lezyondur`,D:`Nükleol tanıdışıdır`,E:`Gland boyutu ayırmaz`},dogru:`C`,aciklama:`Benignde iki tabaka-bazal korunur, malignde kaybolur; PİN prekürsör olarak çıkarılan dokuda bulunur.`,sik_aciklamalari:{A:`Malignde kaybolur.`,B:`İn situ prekürsördür.`,C:`Doğru: tabaka-prekürsör ikilisi tamdır.`,D:`Belirginliği tanısaldır.`,E:`Küçüklük-biraradalık tanısaldır.`},bilgi:[20,31],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k24-q06`,kazanim:24,zorluk:`orta`,soru:`Karsinom morfolojisi ve PİN nedir?`,secenekler:{A:`Küçük bazalsiz gland, belirgin nükleol ve PİN prekürsördür`,B:`Glandlar büyüktür`,C:`Bazal korunur`,D:`PİN invazivdir`,E:`Mitoz sıktır`},dogru:`A`,aciklama:`Glandlar benignlerden küçük, üniform küboidal-alçak kolumnar tek sıralı, bazalsizdir. Nükleus büyük nükleollü, pleomorfizm belirsiz, mitoz nadirdir; PİN prekürsör kabul edilir.`,sik_aciklamalari:{A:`Doğru: morfoloji ve prekürsör birlikte doğru verilmiştir.`,B:`Daha küçüktür.`,C:`Bazal tabaka izlenmez.`,D:`Prekürsör lezyondur.`,E:`Nadirdir.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k24-q07`,kazanim:24,zorluk:`orta`,soru:`PİN ve bazal tabaka kaybının tanı değeri nedir?`,secenekler:{A:`PİN invazivdir`,B:`Bazal korunur`,C:`PİN prekürsördür; bazal kaybı maligniteyi destekler`,D:`Nükleol önemsizdir`,E:`Glandlar büyüktür`},dogru:`C`,aciklama:`PİN prostat karsinomunun prekürsör lezyonu kabul edilir; benign glandlardaki bazal tabakanın kaybı maligniteyi destekler. Küçük üniform glandlarda bazal yokluğu ve belirgin nükleol tanı koydurucudur.`,sik_aciklamalari:{A:`Prekürsör lezyondur.`,B:`Benigndeki bazal tabaka izlenmez.`,C:`Doğru: prekürsör ve tanı ölçütü birlikte doğru verilmiştir.`,D:`Büyümüş belirgin nükleol tipiktir.`,E:`Benignlerden daha küçüktür.`},bilgi:[31],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k24-q08`,kazanim:24,zorluk:`kolay`,soru:`Aşağıdakilerden "PSA ölçümü ve sınırlamaları" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{D:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,E:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,C:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,B:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,A:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`},dogru:`D`,aciklama:`Doğru: PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,sik_aciklamalari:{D:`Doğru. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,E:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,C:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,B:`Yanlış. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,A:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k24-q09`,kazanim:24,zorluk:`orta`,soru:`"Prostat karsinomu tedavisi ve LHRH flare" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,D:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,C:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,B:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,A:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`},dogru:`E`,aciklama:`Doğru: Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,sik_aciklamalari:{E:`Doğru. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,D:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,C:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,B:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,A:`Yanlış. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k24-q10`,kazanim:24,zorluk:`orta`,soru:`"Testiküler torsiyon: mekanizma ve tipler" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,D:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,A:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,C:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`},dogru:`E`,aciklama:`Doğru: Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,sik_aciklamalari:{E:`Doğru. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,D:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,A:`Yanlış. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,C:`Yanlış. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`},bilgi:[18],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k24-q11`,kazanim:24,zorluk:`zor`,soru:`"Torsiyon: klinik ve tedavi" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,B:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,E:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,C:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,D:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`},dogru:`A`,aciklama:`Doğru: Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,sik_aciklamalari:{A:`Doğru. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,B:`Yanlış. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,E:`Yanlış. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,C:`Yanlış. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,D:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`},bilgi:[19],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:25,metin:`Gleason derecelendirme sistemini açıklayabilmek`,sorular:[{id:`k1-66-q73`,kazanim:25,zorluk:`kolay`,soru:`Gleason skoru nasıl hesaplanır?`,secenekler:{A:`Primer (dominant) ve sekonder (ikinci sık) patern derecelerinin toplamıyla`,B:`Mitoz sayısının iki katıyla`,C:`Tümör boyutuna göre`,D:`PSA düzeyine göre`,E:`Lenf nodu sayısına göre`},dogru:`A`,aciklama:`Gleason skoru dominant ve ikinci en sık glandüler paternin derecelerinin toplamıdır; tek paternli tümörde derece ikiyle çarpılır.`,sik_aciklamalari:{A:`Doğru: Gleason skorunun hesaplanma yöntemidir.`,B:`Mitoz sayısı Gleason sisteminde kullanılmaz.`,C:`Boyut evrelemenin konusudur.`,D:`PSA ayrı bir belirteçtir.`,E:`Lenf nodu evrelemede kullanılır.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-66-q74`,kazanim:25,zorluk:`orta`,soru:`Gleason sisteminde en kötü diferansiye tümörün skoru hangisidir?`,secenekler:{A:`10 (5+5)`,B:`2 (1+1)`,C:`6 (3+3)`,D:`7 (3+4)`,E:`5 (5+0)`},dogru:`A`,aciklama:`En iyi diferansiye tümörde skor 2 (1+1), en kötü diferansiye tümörde 10 (5+5)'tir.`,sik_aciklamalari:{A:`Doğru: en yüksek skordur.`,B:`2 en iyi diferansiye tümörün skorudur.`,C:`6 ara bir skordur: 6 (3+3).`,D:`7 ara bir skordur: 7 (3+4).`,E:`Sistemde 0 derecesi yoktur.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-66-q75`,kazanim:25,zorluk:`zor`,soru:`Prostat iğne biyopsisinde tümörün çoğunluğu Gleason derece 4, daha az kısmı derece 3 patern gösteriyor.

Gleason skoru ne olarak raporlanır?`,secenekler:{A:`4+3=7`,B:`3+4=7`,C:`4+4=8`,D:`3+3=6`,E:`7+0=7`},dogru:`A`,aciklama:`Primer derece dominant paterni (4), sekonder derece ikinci en sık paterni (3) belirtir; skor 4+3=7'dir.`,sik_aciklamalari:{A:`Doğru: dominant patern önce yazılır.`,B:`Sıralama ters verilmiştir; dominant patern 4'tür.`,C:`Derece 3 komponent göz ardı edilmiştir.`,D:`Derece 4 komponent göz ardı edilmiştir.`,E:`Gleason derecesi 1–5 arasıdır.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k25-q04`,kazanim:25,zorluk:`orta`,soru:`3+4=7 raporunun anlamı ve skor aralığı soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`Gleason nükleer derecedir`,B:`Skor tektir`,C:`En iyi skor 10'dur`,D:`Tek paternde sayı tektir`,E:`3+4=7 skorlu tümörde primer patern 3 (dominant), sekonder 4'tür; en iyi 2 (1+1), en kötü 10 (5+5)'dur`},dogru:`E`,aciklama:`1967-2005 revizyon, glandüler patern 5 derece; primer dominant+sekonder toplam; 2 (1+1) en iyi, 10 (5+5) en kötü; tek paternde ikiyle çarpılır.`,sik_aciklamalari:{A:`Glandüler paterndir.`,B:`İki grade toplamıdır.`,C:`En kötüdür.`,D:`İkiyle çarpılır.`,E:`Doğru: bileşen-aralık ikilisi tamdır.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k25-q05`,kazanim:25,zorluk:`zor`,soru:`Grade uçları ve tek patern kuralı soruluyor. Hangi bilgi doğrudur?`,secenekler:{A:`Grade5 iyi diferansiyedir`,B:`Sekonder ilk paterndir`,C:`Revizyon yoktur`,D:`Grade 1 iyi diferansiye-glandüler, grade 5 diferansiasyonsuzdur (1967-2005 revizyon); skor primer+sekonder toplamıdır ve tek paternde sayı ikiyle çarpılır`,E:`Skor prognozu etkilemez`},dogru:`D`,aciklama:`Grade1 iyi diferansiye, grade5 diferansiasyonsuz; primer-sonra en çok patern; rapor standardizasyonu prognoz-tedaviyi yönlendirir.`,sik_aciklamalari:{A:`En kötüdür.`,B:`Sonra en çoktur.`,C:`2005 revizyonudur.`,D:`Doğru: uçlar-kural üçlüsü tamdır.`,E:`Yönlendirir.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k25-q06`,kazanim:25,zorluk:`orta`,soru:`Gleason primer-sekonder ve skor nedir?`,secenekler:{A:`Primer minör alandır`,B:`Primer dominant, sekonder ikinci; skor toplamdır`,C:`Skor çarpmadır`,D:`Yüksek skor iyidir`,E:`Patern sitolojiktir`},dogru:`B`,aciklama:`Beş glandüler patern; primer en geniş alan, sekonder ikinci alandır. Skor örneğin 3+4=7 gibi toplanır; yüksek skor kötü diferansiasyonu gösterir.`,sik_aciklamalari:{A:`Dominant paterndir.`,B:`Doğru: tanımlamalar ve skor birlikte doğru verilmiştir.`,C:`İki grade toplamıdır.`,D:`Kötü diferansiasyonu gösterir.`,E:`Glandüler paternlere göredir.`},bilgi:[32],benzer_cikmis:[`3dad2d38e6c6`]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k25-q07`,kazanim:25,zorluk:`orta`,soru:`Gleason uç gradeleri ve revizyon nedir?`,secenekler:{A:`Grade 1 glandsizdir`,B:`Grade 5 iyidir`,C:`Revizyon 1967'dir`,D:`Patern önemsizdir`,E:`Grade 1 iyi, grade 5 glandsizdir; 2005 revizyonludur`},dogru:`E`,aciklama:`Grade 1 iyi diferansiye glandlar, grade 5 glandsiz tabakalardır; ara gradeler füzyon-kribriformite gösterir. Revizyon 2005'te prognostik uyumu artırmıştır.`,sik_aciklamalari:{A:`İyi diferansiyedir.`,B:`Diferansiasyonsuzdur.`,C:`2005'te revize edilmiştir.`,D:`Patern prognostiktir.`,E:`Doğru: uç gradeler ve tarih birlikte doğru verilmiştir.`},bilgi:[32],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k25-q08`,kazanim:25,zorluk:`kolay`,soru:`"DHT ve 5α-redüktaz tip 2" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,B:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,C:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,A:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,D:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`},dogru:`E`,aciklama:`Doğru: Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,sik_aciklamalari:{E:`Doğru. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,B:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,C:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,A:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,D:`Yanlış. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`},bilgi:[25],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k25-q09`,kazanim:25,zorluk:`orta`,soru:`"Spermatosel ve varikosel" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,C:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,E:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,D:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`},dogru:`A`,aciklama:`Doğru: Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,sik_aciklamalari:{A:`Doğru. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,C:`Yanlış. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,E:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,D:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k25-q10`,kazanim:25,zorluk:`orta`,soru:`"Prostat karsinomu: epidemiyoloji" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,E:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,D:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,C:`Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,B:`Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`},dogru:`A`,aciklama:`Doğru: Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,sik_aciklamalari:{A:`Doğru. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,E:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,D:`Yanlış. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,C:`Yanlış. Prostatın en önemli bölümleri periferik zon ve geçiş (transisyonel) zonudur; hiperplastik lezyonlar en çok iç transisyonel zondan, karsinomlar (%70-80) periferik zondan gelişir. Normal prostat basıklaşmış bazal tabaka üzerine kolumnar sekretuar epitelin oturduğu iki hücre tabakalı glandlar içerir.`,B:`Yanlış. Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k25-q11`,kazanim:25,zorluk:`zor`,soru:`"Testiküler torsiyon: mekanizma ve tipler" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,B:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,E:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,D:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,A:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`},dogru:`C`,aciklama:`Doğru: Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,sik_aciklamalari:{C:`Doğru. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,B:`Yanlış. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,E:`Yanlış. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,D:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,A:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`},bilgi:[18],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:26,metin:`PSA'nın prostat kanserindeki rolünü ve sınırlamalarını bilmek`,sorular:[{id:`k1-66-q76`,kazanim:26,zorluk:`kolay`,soru:`PSA için hangisi doğrudur?`,secenekler:{A:`Organa spesifiktir ancak kansere spesifik değildir`,B:`Yalnızca prostat kanserinde yükselir`,C:`Testis tümörü belirtecidir`,D:`Mesane kanseri belirtecidir`,E:`Seminal sıvıda bulunmaz`},dogru:`A`,aciklama:`PSA prostat epiteli ürünüdür; organa spesifik olup BPH, prostatit, infarkt ve işlemlerle de yükselebilir.`,sik_aciklamalari:{A:`Doğru: PSA'nın temel sınırlamasıdır.`,B:`Benign durumlarda da yükselir.`,C:`Testis tümörlerinde hCG, AFP ve LDH kullanılır.`,D:`PSA mesane belirteci değildir.`,E:`PSA seminal koagulumu eritir.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-66-q77`,kazanim:26,zorluk:`orta`,soru:`PSA'nın tanısal sınırlamaları ile ilgili hangisi doğrudur?`,secenekler:{A:`Prostata sınırlı kanserli olguların %20–40'ında PSA normal olabilir`,B:`Ejakülasyon PSA'yı etkilemez`,C:`Prostat infarktında PSA düşer`,D:`Kanserde serbest/total PSA oranı yüksektir`,E:`Eşik değer tüm rehberlerde 10 ng/ml'dir`},dogru:`A`,aciklama:`Organa sınırlı kanserlerin %20–40'ında PSA normaldir; kanserde serbest/total PSA oranı daha düşüktür.`,sik_aciklamalari:{A:`Doğru: duyarlılık sınırlıdır.`,B:`Ejakülasyon PSA'yı artırabilir.`,C:`İnfarkt PSA'yı artırır.`,D:`Kanserde serbest/total oran düşüktür.`,E:`Eşik çoğunlukla 4 ng/ml (bazen 2,5) kabul edilir.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-66-q78`,kazanim:26,zorluk:`zor`,soru:`PSA'yı yükselttiği halde prostat kanseri olmayan durumlar arasında aşağıdakilerden hangisi yer almaz?`,secenekler:{A:`Prostatik infarkt`,B:`Prostata uygulanan işlemler`,C:`Ejakülasyon`,D:`Prostatit`,E:`Testiküler hidrosel`},dogru:`E`,aciklama:`Prostatik infarkt, prostat işlemleri, ejakülasyon ve prostatit PSA'yı artırabilir; hidrosel prostatla ilişkili değildir.`,sik_aciklamalari:{A:`PSA'yı artırır: prostatik infarkt.`,B:`Biyopsi/rezeksiyon PSA'yı artırır.`,C:`Ejakülasyon bile PSA'yı artırabilir.`,D:`Prostat inflamasyonu PSA'yı artırır.`,E:`Doğru: hidrosel PSA'yı etkilemez.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k26-q04`,kazanim:26,zorluk:`orta`,soru:`PSA yüksekliği ve normal PSA'lı kanser olasılığı soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`PSA kansere spesifiktir`,B:`Eşik 10'dur`,C:`PSA prostatik serin proteazdır; tanı-takipte en önemlidir ancak kansere spesifik değildir (eşik 4 ng/ml); %20-40 sınırlı kanserde normaldir ve serbest/total oranı kanserde düşüktür`,D:`PSA yalnızca taramadadır`,E:`Yükseklik daima kanserdir`},dogru:`C`,aciklama:`PSA serin proteaz, koagulumu eritir; en önemli tanı-takip testi ama organa spesifik-kansere değil; eşik 4 (bazı 2,5); infarkt-işlem-ejakülasyon artırır; %20-40 normal PSA'lı sınırlı kanser.`,sik_aciklamalari:{A:`Organa spesifiktir.`,B:`4 (bazı 2,5)'tir.`,C:`Doğru: rol-sınır-oran üçlüsü tamdır.`,D:`Takipte de esastır.`,E:`Benignde de yükselir.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k26-q05`,kazanim:26,zorluk:`zor`,soru:`Ejakülasyon sonrası PSA yüksekliğinin yorumu soruluyor. Hangi yaklaşım doğrudur?`,secenekler:{A:`Ejakülasyon sonrası PSA bakılan hastada yükseklik benign nedenli olabilir; serbest/total oranı düşükse kanser şüphesi artar ve çoğu küçük kanser PSA taramasında biyopsiyle saptanır`,B:`Ejakülasyon PSA'yı düşürür`,C:`Oran yüksekliği kanserdir`,D:`Küçük kanser palpe edilir`,E:`Biyopsi PSA'dan üstündür`},dogru:`A`,aciklama:`Ejakülasyon-infakt-işlem yükseltir; serbest/total düşük kanser lehine; küçük-nonpalpabl çoğu PSA araştırmasında iğne biyopsisiyle saptanır.`,sik_aciklamalari:{A:`Doğru: yükselten-oran-saptanma üçlüsü tamdır.`,B:`Artırır.`,C:`Düşüklüğü lehindedir.`,D:`Nonpalpabldir.`,E:`PSA tetikler.`},bilgi:[33,34],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k26-q06`,kazanim:26,zorluk:`orta`,soru:`PSA rolü ve sınırlaması nedir?`,secenekler:{A:`PSA tanı-takipte önemli ama benignde de yükselir`,B:`PSA tanı koydurur`,C:`Eşik 40'tır`,D:`Prostatit düşürür`,E:`Takipte kullanılmaz`},dogru:`A`,aciklama:`PSA tanı-takipte en önemli testtir ancak BPH-prostatitte de yükselir. 4 ng/ml eşikle duyarlılık-özgüllük dengelenir; 2,5 eşiği bazı rehberlercedir.`,sik_aciklamalari:{A:`Doğru: rol ve sınırlama birlikte doğru verilmiştir.`,B:`Kansere spesifik değildir.`,C:`4 ng/ml kabul edilir.`,D:`Benign durumlarda da yükselir.`,E:`En önemli takip testidir.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k26-q07`,kazanim:26,zorluk:`orta`,soru:`PSA eşiği ve benign yükselme nedenleri nelerdir?`,secenekler:{A:`Eşik 40'tır`,B:`Benign yükseltmez`,C:`Eşik altı biyopsidir`,D:`Eşik 4 ng/ml'dir; benign nedenler de yükseltir`,E:`Tek eşik 2,5'tir`},dogru:`D`,aciklama:`Çoğu laboratuvarda 4 ng/ml eşik kabul edilir, bazı rehberlerde 2,5 ng/ml'dir. BPH ve prostatit de PSA'yı yükseltir; bu yüzden eşik üstü değer biyopsi ve izlemle yorumlanır.`,sik_aciklamalari:{A:`4 ng/ml kabul edilir.`,B:`BPH-prostatitte de yükselir.`,C:`Eşik üstü biyopsi-izlem gerektirir.`,D:`Doğru: eşik ve benign yükselme birlikte doğru verilmiştir.`,E:`Bazı rehberlerde 2,5'tir.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k26-q08`,kazanim:26,zorluk:`kolay`,soru:`"Prostatit sınıflaması" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{C:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,D:`DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,B:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,E:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,A:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`},dogru:`C`,aciklama:`Doğru: Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,sik_aciklamalari:{C:`Doğru. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,D:`Yanlış. DHT'nin androjen reseptörlerine afinitesi testosterondan fazladır ve daha stabil kompleks oluşturarak 10 kat daha güçlü etki gösterir; reseptöre bağlanıp prostat epitel ve stroma hücrelerinin büyüme/sağ kalımını destekleyen genleri (FGF, TGF-β gibi) stimüle eder.`,B:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,E:`Yanlış. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`,A:`Yanlış. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`},bilgi:[21],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k26-q09`,kazanim:26,zorluk:`orta`,soru:`"Spermatosel ve varikosel" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,D:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,A:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,B:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,C:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`},dogru:`E`,aciklama:`Doğru: Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,sik_aciklamalari:{E:`Doğru. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,D:`Yanlış. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,A:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,B:`Yanlış. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,C:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`},bilgi:[11],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k26-q10`,kazanim:26,zorluk:`orta`,soru:`"Hipospadias" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,B:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,D:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,E:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,C:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`},dogru:`A`,aciklama:`Doğru: Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,sik_aciklamalari:{A:`Doğru. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,B:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,D:`Yanlış. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,E:`Yanlış. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,C:`Yanlış. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`},bilgi:[1],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k26-q11`,kazanim:26,zorluk:`zor`,soru:`"BPH: epidemiyoloji ve androjen bağımlılığı" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{A:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,C:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,D:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,E:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},dogru:`A`,aciklama:`Doğru: Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,sik_aciklamalari:{A:`Doğru. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,B:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,C:`Yanlış. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,D:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,E:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},bilgi:[24],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:27,metin:`Prostat karsinomunun tedavi yaklaşımlarını ve androjen yoksunluğu tedavisini açıklayabilmek`,sorular:[{id:`k1-66-q79`,kazanim:27,zorluk:`kolay`,soru:`Lokalize prostat karsinomunda en yaygın tedavi seçenekleri hangileridir?`,secenekler:{A:`Radikal prostatektomi ve radyoterapi`,B:`Yalnızca antibiyotik`,C:`Orşiopeksi`,D:`Trastuzumab`,E:`Kemoterapi ile tam kür`},dogru:`A`,aciklama:`Lokalize hastalıkta radikal prostatektomi ve radyoterapi en yaygındır; yaşlılarda aktif gözetim uygundur.`,sik_aciklamalari:{A:`Doğru: lokalize hastalığın standart tedavileridir.`,B:`Antibiyotik kanser tedavisi değildir.`,C:`Orşiopeksi kriptorşidizm tedavisidir.`,D:`Trastuzumab HER2 pozitif meme kanserinde kullanılır.`,E:`Kemoterapi lokalize hastalıkta ana tedavi değildir.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-66-q80`,kazanim:27,zorluk:`orta`,soru:`Metastatik prostat karsinomunda LHRH agonistleri ile tedavi başlandığında görülebilen başlangıç fenomeni hangisidir?`,secenekler:{A:`Testosteronda geçici artış (flare fenomeni)`,B:`Testosteronun ilk gün sıfıra inmesi`,C:`PSA'nın kalıcı yükselmesi`,D:`Kemik metastazlarının anında kaybolması`,E:`Hiperkalemi`},dogru:`A`,aciklama:`LHRH agonistleri başlangıçta testosteronu geçici artırarak kemik ağrısı, obstrüksiyon ve kord kompresyonu riskini artırır; 2–4 haftada kastre düzeye iner.`,sik_aciklamalari:{A:`Doğru: flare fenomeni başlangıçta görülür.`,B:`Testosteron önce artar, 2–4 haftada düşer.`,C:`Tedaviyle PSA beklenen şekilde düşer.`,D:`Metastazlar anında kaybolmaz.`,E:`Hiperkalemi bu fenomene ait değildir.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-66-q81`,kazanim:27,zorluk:`zor`,soru:`80 yaşında, düşük Gleason skorlu, organa sınırlı küçük prostat karsinomu saptanan ve ciddi komorbiditeleri olan hasta için en uygun yaklaşım hangisidir?`,secenekler:{A:`Aktif gözetim (uyanık bekleme)`,B:`Acil radikal sistektomi`,C:`Bilateral orşiopeksi`,D:`Trastuzumab tedavisi`,E:`Hiçbir izlem yapmadan taburculuk`},dogru:`A`,aciklama:`Prostat karsinomunun yavaş seyri nedeniyle yaşlı erkeklerde aktif gözetim uygundur.`,sik_aciklamalari:{A:`Doğru: yavaş seyirli hastalıkta uygun yaklaşımdır.`,B:`Sistektomi mesane tedavisidir.`,C:`Orşiopeksi kriptorşidizmde yapılır.`,D:`Trastuzumab prostat kanserinde kullanılmaz.`,E:`Aktif gözetim düzenli izlem gerektirir.`},bilgi:[29,35],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k27-q04`,kazanim:27,zorluk:`orta`,soru:`Üç evrede üç farklı hastanın tedavisi soruluyor. Hangi eşleşme doğrudur?`,secenekler:{A:`Tüm evrelerde prostatektomi şarttır`,B:`Lokalize genç hastada prostatektomi-radyoterapi, yavaş seyirli yaşlıda aktif gözetim ve metastatikte LHRH agonistiyle androjen yoksunluğu uygulanır`,C:`Gözetim gençte ilk tercihtir`,D:`LHRH lokalizede ilk tercihtir`,E:`Radyoterapi kullanılmaz`},dogru:`B`,aciklama:`Lokalizede prostatektomi-radyoterapi; yaşlı-yavaş seyirde aktif gözetim; metastatikte LHRH agonisti farmakolojik orşiektomi.`,sik_aciklamalari:{A:`Evreye göredir.`,B:`Doğru: evre-tedavi üçlüsü tamdır.`,C:`Yaşlı-yavaştadır.`,D:`Metastatiktedir.`,E:`Yaygın tedavidir.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k27-q05`,kazanim:27,zorluk:`zor`,soru:`LHRH sonrası ağrısı artan hastada mekanizma soruluyor. Hangi açıklama doğrudur?`,secenekler:{A:`LHRH hemen kastre eder`,B:`Flare yaralı değildir`,C:`Testosteron düşmez`,D:`Kord kompresyonu flarede azalmaz`,E:`LHRH başlanan metastatik hastada ilk günlerde kemik ağrısı artışı flare nedeniyledir; 2-4 haftada down regülasyonla testosteron kastre düzeye iner`},dogru:`E`,aciklama:`LHRH başlangıçta testosteronu artırır (flare: kemik ağrısı-obstrüksiyon-kord kompresyonu), sürekli uyarı down regülasyonla 2-4 haftada kastre düzeye düşürür.`,sik_aciklamalari:{A:`Önce artırır.`,B:`Ağrı-kompresyon yapar.`,C:`Kastre düzeye iner.`,D:`Riski artırır.`,E:`Doğru: flare-süre ikilisi tamdır.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k27-q06`,kazanim:27,zorluk:`orta`,soru:`LHRH agonisti mekanizması nedir?`,secenekler:{A:`LHRH androjeni artırır`,B:`LHRH duyarsızlaştırıp kastrasyon etkisi yapar`,C:`Lokal LHRH ilk`,D:`Cerrahi metastatiktedir`,E:`Yoksunluk etkisizdir`},dogru:`B`,aciklama:`LHRH agonistleri sürekli uyarımla reseptörü duyarsızlaştırıp farmakolojik orşiektomi yapar. Lokalize cerrahi-radyoterapi, ileri LHRH-kastrasyon ilkeleridir.`,sik_aciklamalari:{A:`Yoksunluk yaratır.`,B:`Doğru: mekanizma ve endikasyon birlikte doğru verilmiştir.`,C:`Lokalizede cerrahi-radyoterapi yaygındır.`,D:`İlerlemiş metastatiktedir.`,E:`İlerlemişte etkilidir.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k27-q07`,kazanim:27,zorluk:`orta`,soru:`Evreye göre tedavi seçenekleri nelerdir?`,secenekler:{A:`Metastatikte cerrahi küratiftir`,B:`Gözetim gençtedir`,C:`Lokal küratif, yaşlıda gözetim, ilerlemişte yoksunluk uygulanır`,D:`Radyoterapi metastatiktedir`,E:`Yoksunluk lokalizededir`},dogru:`C`,aciklama:`Lokalize hastalıkta radikal prostatektomi ve radyoterapi küratif seçeneklerdir; yavaş seyirli yaşlıda aktif gözetim uygundur. İlerlemiş metastatikte LHRH ile androjen yoksunluğu başlanır.`,sik_aciklamalari:{A:`İlerlemişte yoksunluk standarttır.`,B:`Yaşlı yavaş seyirde uygundur.`,C:`Doğru: üç evre stratejisi birlikte doğru verilmiştir.`,D:`Lokalizede yaygındır.`,E:`İlerlemiş metastatiktedir.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k27-q08`,kazanim:27,zorluk:`kolay`,soru:`"Testis neoplazileri: genel özellikler ve risk faktörleri" ifadesi ile ilgili aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,C:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,D:`BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,A:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,E:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`},dogru:`B`,aciklama:`Doğru: Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,sik_aciklamalari:{B:`Doğru. Yaklaşık 100.000 erkekte 6 görülür ve 15-34 yaşta en sıktır; postpubertal erkeklerde testiküler tümörlerin %95'i germ hücre kaynaklıdır ve hepsi maligndir, seks kord-stromal tümörler az ve genellikle benigndir. Kriptorşidizm riski 3-5 kat artırır, vakaların %10'unda hikâye vardır ve kardeşte germ hücreli tümör riski 8-10 kat artırır.`,C:`Yanlış. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,D:`Yanlış. BPH hemen hemen daima iç transisyonel zondan orijin alır; prostat büyümüş ve tipik olarak 60-100 gram olup iyi sınırlı nodüller içerir, üretra basıklaşarak dar bir yarık halini alır. Mikroskopide glandüler yapılar fibromüsküler stroma içinde olup glandlar basıklaşmış bazal hücreli uzun kolumnar epitelle döşelidir ve lümen korpora amilasea içerir.`,A:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,E:`Yanlış. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`},bilgi:[36],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k27-q09`,kazanim:27,zorluk:`orta`,soru:`"BPH klinik özellikleri ve tedavi" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{A:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,B:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,E:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,D:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,C:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`},dogru:`A`,aciklama:`Doğru: Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,sik_aciklamalari:{A:`Doğru. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,B:`Yanlış. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,E:`Yanlış. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,D:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,C:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`},bilgi:[28],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k27-q10`,kazanim:27,zorluk:`orta`,soru:`"PSA ölçümü ve sınırlamaları" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,E:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,D:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,B:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,C:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`},dogru:`A`,aciklama:`Doğru: PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,sik_aciklamalari:{A:`Doğru. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`,E:`Yanlış. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,D:`Yanlış. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,B:`Yanlış. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,C:`Yanlış. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`},bilgi:[34],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k27-q11`,kazanim:27,zorluk:`zor`,soru:`"Testis tümörü belirteçleri, klinik ve tedavi" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{D:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,A:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,E:`Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,B:`Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,C:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`},dogru:`D`,aciklama:`Doğru: hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,sik_aciklamalari:{D:`Doğru. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,A:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,E:`Yanlış. Penis neoplazilerinin %95'ten fazlası skuamöz epitelden kaynaklanır; gelişmekte olan ülkelerde daha sık görülür ve çoğu vaka 40 yaş üstü sünnetsiz hastalarda ortaya çıkar. Patogenezde kötü hijyen (smegma) ve HPV (özellikle tip 16 ve 18) rol oynar.`,B:`Yanlış. Testisin iltihabi lezyonları çoğunlukla epididimde bulunur; nonspesifik epididimit/orşit primer idrar yolu enfeksiyonu olarak başlar ve başlıca nötrofilli infiltrat içerir. Kabakulak enfeksiyonu geçiren erişkin erkeklerin ortalama %20'sinde orşitis görülür ve lenfoplazmositik infiltrasyon yapar.`,C:`Yanlış. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`},bilgi:[40],benzer_cikmis:[]}],ilgili_cikmis:[]},{no:28,metin:`Testis neoplazilerinin sınıflandırmasını ve risk faktörlerini özetlemek`,sorular:[{id:`k1-66-q82`,kazanim:28,zorluk:`kolay`,soru:`Postpubertal erkeklerde testiküler tümörlerin yaklaşık %95'i hangi kökenlidir?`,secenekler:{A:`Germ hücreli`,B:`Seks kord-stromal`,C:`Lenfoma`,D:`Metastatik`,E:`Mezenkimal`},dogru:`A`,aciklama:`Postpubertal erkeklerde testis tümörlerinin %95'i germ hücre kaynaklıdır ve hepsi maligndir.`,sik_aciklamalari:{A:`Doğru: germ hücreli tümörler baskındır.`,B:`Seks kord-stromal tümörler azdır ve genellikle benigndir.`,C:`Lenfoma ileri yaşta görülür, sık değildir.`,D:`Metastazlar nadirdir.`,E:`Mezenkimal tümörler nadirdir.`},bilgi:[36],benzer_cikmis:[`7775ec3ba776`]},{id:`k1-66-q83`,kazanim:28,zorluk:`orta`,soru:`Aşağıdakilerden hangisi testiküler germ hücreli tümör risk faktörü değildir?`,secenekler:{A:`Vazektomi öyküsü`,B:`Kriptorşidizm`,C:`Kardeşte germ hücreli tümör öyküsü`,D:`İnterseks sendromları`,E:`Beyaz ırk`},dogru:`A`,aciklama:`Kriptorşidizm 3–5 kat, kardeşte tümör 8–10 kat riski artırır; interseks sendromları ve beyaz ırk da risklidir.`,sik_aciklamalari:{A:`Doğru: vazektomi bu derste risk faktörü olarak sayılmaz.`,B:`Riski 3–5 kat artırır.`,C:`Riski 8–10 kat artırır.`,D:`Artmış sıklıkla birliktedir.`,E:`Beyaz ırkta daha yaygındır.`},bilgi:[36],benzer_cikmis:[]},{id:`k1-66-q84`,kazanim:28,zorluk:`zor`,soru:`Testiküler germ hücreli tümörlerin genetik ve öncül lezyonu ile ilgili hangisi doğrudur?`,secenekler:{A:`Histolojik tipten bağımsız olarak i(12p) bulunur; çoğu intratübüler germ hücre neoplazisinden gelişir`,B:`i(12p) yalnızca seminomda bulunur`,C:`Öncül lezyon BPH'dir`,D:`İntratübüler germ hücre neoplazisi kriptorşid testislerde görülmez`,E:`Spermatositik seminom i(12p) taşır ve sık metastaz yapar`},dogru:`A`,aciklama:`i(12p) tüm germ hücreli tümörlerde bulunur; çoğu tümör intratübüler germ hücre neoplazisinden gelişir ve bu lezyon kriptorşid/disgenetik gonadlarda görülür.`,sik_aciklamalari:{A:`Doğru: ortak genetik ve öncül lezyon doğru verilmiştir.`,B:`Tüm histolojik tiplerde bulunur.`,C:`BPH prostat lezyonudur.`,D:`Kriptorşid testislerde bulunabilir.`,E:`Spermatositik seminom i(12p) içermez ve metastaz yapmaz.`},bilgi:[37,38],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k28-q04`,kazanim:28,zorluk:`orta`,soru:`Genç erişkinde testis kitlesinin ön tanısı ve risk sorgusu soruluyor. Hangi yaklaşım doğrudur?`,secenekler:{A:`Testis tümörü yaşlıda en sıktır`,B:`Postpubertal çoğu benigndir`,C:`Kriptorşidizm korumaz`,D:`20 yaşında testis kitlesinde ilk akla germ hücreli malign tümör gelir (%95); kriptorşidizm 3-5 kat, kardeş öyküsü 8-10 kat artırır`,E:`Seks kord sıktır`},dogru:`D`,aciklama:`100.000'de 6, 15-34 yaşta en sık; postpubertal %95 germ hücreli-malign, seks kord-stromal az-benign; kriptorşidizm 3-5 kat (%10 öykü), kardeşte 8-10 kat; beyaz ırk-interseks riskli.`,sik_aciklamalari:{A:`15-34'tedir.`,B:`Maligndir.`,C:`Artırır.`,D:`Doğru: sıklık-risk ikilisi tamdır.`,E:`Az-benigndir.`},bilgi:[36],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k28-q05`,kazanim:28,zorluk:`zor`,soru:`Germ hücreli tümörün sitogenetik imzası soruluyor. Hangi bilgi doğrudur?`,secenekler:{A:`i(12p) yalnızca seminomdadır`,B:`i(12p) izokromozomu tüm germ hücreli tümörlerde histolojiden bağımsız bulunur ve çoğu intratubuler in situ lezyondan gelişir`,C:`Prekürsör yoktur`,D:`Komşu doku daima normaldir`,E:`i(12p) benigndir`},dogru:`B`,aciklama:`i(12p) tüm germ hücrelilerde histolojiden bağımsız; çoğu intratubuler germ hücre neoplazisinden gelişir; kriptorşid-disgenetikte yüksek risk.`,sik_aciklamalari:{A:`Tümündedir.`,B:`Doğru: sitogenetik-prekürsör ikilisi tamdır.`,C:`IGCN'dir.`,D:`In situ bulunabilir.`,E:`Malign belirtecidir.`},bilgi:[37],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k28-q06`,kazanim:28,zorluk:`orta`,soru:`Nonseminomatöz tipler nasıl ayrılır?`,secenekler:{A:`Nonseminomatöz dört tip morfolojik-belirteçle ayrılır`,B:`Embriyonal benigndir`,C:`Yolk sak erişkindir`,D:`Koryo AFP'lidir`,E:`Teratom benigndir`},dogru:`A`,aciklama:`Germ-seminomatöz ve nonseminomatöz, stromal tümörler diye ayrılır. Embriyonal hemorajik-nekrotik invaziv (%2-3 saf), yolk sak 3 yaş altı Schiller-Duval-AFP'li, koryo HCG'li, teratom somatik diferansiyonludur.`,sik_aciklamalari:{A:`Doğru: dört tipin ayırt edicileri birlikte doğru verilmiştir.`,B:`İnvaziv maligndir.`,C:`3 yaş altı en sıktır.`,D:`HCG yükselir.`,E:`Postpubertalde malign kabul edilir.`},bilgi:[39],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k28-q07`,kazanim:28,zorluk:`orta`,soru:`Testis tümörü köken oranı ve risk faktörleri nelerdir?`,secenekler:{A:`Germ hücreli benigndir`,B:`Stromal maligndir`,C:`%95 malign germ hücreli; kriptorşidizm-kardeşlik risklidir`,D:`Risk artmaz`,E:`Hikâye %50'dir`},dogru:`C`,aciklama:`Postpubertal testis tümörlerinin %95'i germ hücrelidir ve hepsi maligndir; seks kord-stromaller az ve genellikle benigndir. Kriptorşidizm 3-5 kat, kardeşte germ hücreli tümör 8-10 kat artırır; vakaların %10'unda hikâye vardır.`,sik_aciklamalari:{A:`Hepsi maligndir.`,B:`Genellikle benigndir.`,C:`Doğru: köken oranı ve riskler birlikte doğru verilmiştir.`,D:`3-5 ve 8-10 kat artar.`,E:`%10'unda hikâye vardır.`},bilgi:[36],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k28-q08`,kazanim:28,zorluk:`kolay`,soru:`Aşağıdakilerden "Epispadias" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{C:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,E:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,D:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,A:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`},dogru:`C`,aciklama:`Doğru: Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,sik_aciklamalari:{C:`Doğru. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,B:`Yanlış. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,E:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,D:`Yanlış. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,A:`Yanlış. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`},bilgi:[2],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k28-q09`,kazanim:28,zorluk:`orta`,soru:`"Testis atrofisi nedenleri" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{C:`Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,D:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,B:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,A:`Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,E:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`},dogru:`C`,aciklama:`Doğru: Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,sik_aciklamalari:{C:`Doğru. Yaşlılarda aterosklerotik kan akımı azalması, inflamatuar orşitin ileri evreleri, radyasyon, ilerlemiş prostat kanserinde antiandrojenlerin uzun süreli kullanımı, tükenme atrofisi (yüksek FSH ile sürekli uyarım), siroz gibi östrojenin yükseldiği durumlar ve Klinefelter sendromu gibi genetik durumlar.`,D:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,B:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,A:`Yanlış. Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,E:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`},bilgi:[15],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k28-q10`,kazanim:28,zorluk:`orta`,soru:`"Gleason derecelendirmesi" ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,E:`12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,D:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,C:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,B:`PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`},dogru:`A`,aciklama:`Doğru: Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,sik_aciklamalari:{A:`Doğru. Prostat kanseri 1967'de ortaya konmuş, 2005'te revize edilmiş Gleason sistemi ile glandüler paternlere göre beş dereceye ayrılır; grade 1 iyi diferansiye, grade 5 glandüler diferansiasyon göstermeyendir. Primer grade dominant paterni, sekonder grade sonra en çok görülen paterni belirler ve skor iki grade'in toplamıdır.`,E:`Yanlış. 12. kromozomun kısa kolundaki izokromozom i(12p), histolojik tip ayırt etmeksizin bütün germ hücreli tümörlerde bulunmuştur. Çoğu testis tümörü postpubertal erkeklerde in situ lezyon olan intratubuler germ hücre neoplazisinden gelişir.`,D:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`,C:`Yanlış. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,B:`Yanlış. PSA prostatik epitelin ürünü olan ve ejakülasyon sonrası seminal koagulumun eritilmesini sağlayan bir serin proteazdır; en önemli tanı ve takip testidir ancak organa spesifik olup kansere spesifik değildir. Çoğu laboratuvarda 4 ng/ml eşik değer kabul edilir (bazı rehberlerde 2,5 ng/ml).`},bilgi:[32],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k28-q11`,kazanim:28,zorluk:`zor`,soru:`"Prostat karsinomu patogenezi ve genetiği" ile ilgili bir hastada bulunacak aşağıdaki bulgulardan hangisi beklenmez?`,secenekler:{A:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,B:`İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,D:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,C:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,E:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`},dogru:`A`,aciklama:`Doğru: Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,sik_aciklamalari:{A:`Doğru. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,B:`Yanlış. İnmemiş testisin atrofik hale gelmesi bilateral kriptorşidizmde steriliteye neden olur; tek taraflı olguda kontralateral inmiş testiste de atrofi gelişebilir. İnişteki yetmezlik 3-5 kat artmış testiküler kanser riski ile birliktelik gösterir.`,D:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,C:`Yanlış. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,E:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`},bilgi:[30],benzer_cikmis:[]}],ilgili_cikmis:[{id:`7775ec3ba776`,soru:`Testis tümörleri ile ilgili hangisi doğrudur?`,secenekler:{A:`En sık 50 yaşından sonra görülür`,B:`Postpubertal erkeklerde testiküler tümörlerin %95'i germ hücrelerinden kaynaklanır ve hepsi benigndir`,C:`Seks kord-stromal tümörler az görülür ve genellikle maligndir`,D:`Seminomlar sekskord stromal tümörlerin yaklaşık yarısını oluşturur`,E:`Sertoli ya da Leydig hücrelerinden kaynaklananlar genellikle benigndir`},cevap:`B`}]},{no:29,metin:`Germ hücreli tümör tiplerinin morfolojik özelliklerini ve tümör belirteçlerini ayırt edebilmek`,sorular:[{id:`k1-66-q85`,kazanim:29,zorluk:`kolay`,soru:`Glikojenden zengin berrak sitoplazmalı büyük üniform hücreler, fibröz septumlar ve lenfositik infiltrasyon içeren testis tümörü hangisidir?`,secenekler:{A:`Seminom`,B:`Embriyonal karsinom`,C:`Yolk sak tümörü`,D:`Koryokarsinom`,E:`Teratom`},dogru:`A`,aciklama:`Seminom germ hücreli neoplazilerin ~%50'sidir; homojen gri-beyaz kitle ve tipik histolojisi vardır.`,sik_aciklamalari:{A:`Doğru: seminomun klasik histolojisidir.`,B:`Embriyonal karsinom kanamalı-nekrotik, kötü sınırlıdır.`,C:`Yolk sak tümöründe Schiller-Duval cisimleri vardır.`,D:`Koryokarsinom trofoblastik hücrelerden oluşur.`,E:`Teratom somatik dokular içerir.`},bilgi:[38],benzer_cikmis:[`f16bbc2e4bd0`]},{id:`k1-66-q86`,kazanim:29,zorluk:`orta`,soru:`Germ hücreli tümör ile serum belirteci eşleştirmelerinden hangisi doğrudur?`,secenekler:{A:`Yolk sak tümörü – AFP; koryokarsinom – hCG`,B:`Seminom – AFP belirgin yüksek`,C:`Koryokarsinom – AFP`,D:`Teratom – hCG her zaman yüksek`,E:`Yolk sak tümörü – PSA`},dogru:`A`,aciklama:`AFP yolk sak komponentini, hCG koryokarsinomu gösterir; LDH tümör yüküyle ilişkilidir.`,sik_aciklamalari:{A:`Doğru: belirteç eşleşmeleri doğrudur.`,B:`Seminomda AFP yükselmez; sinsityotrofoblast varsa minimal hCG artışı olabilir.`,C:`Koryokarsinomda hCG yükselir.`,D:`Teratomda hCG tipik değildir.`,E:`PSA prostat belirtecidir.`},bilgi:[38,39,40],benzer_cikmis:[]},{id:`k1-66-q87`,kazanim:29,zorluk:`zor`,soru:`Testis germ hücreli tümörleri ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir`,B:`Seminomların ~%15'inde sinsityotrofoblast bulunur ve minimal hCG artışı yapar`,C:`Spermatositik seminom genellikle 65 yaş üstünde görülür`,D:`Teratom postpubertal erkeklerde malign kabul edilir`,E:`Seminomdaki sinsityotrofoblastlar prognozu belirgin kötüleştirir`},dogru:`E`,aciklama:`Seminomdaki sinsityotrofoblastlar minimal hCG yükselmesinden sorumludur ve prognozu etkilemez.`,sik_aciklamalari:{A:`Doğru ifade: küçük çocuklarda en sık testis tümörüdür.`,B:`Doğru ifade: %15'inde sinsityotrofoblast vardır.`,C:`Doğru ifade: spermatositik seminom ileri yaştadır.`,D:`Doğru ifade: postpubertal teratom maligndir.`,E:`Yanlış ifade (aranan cevap): prognozu etkilemez.`},bilgi:[38,39],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k29-q04`,kazanim:29,zorluk:`orta`,soru:`İki seminom varyantı karşılaştırılıyor. Hangi ayırım doğrudur?`,secenekler:{A:`Homojen gri-beyaz, lenfositik septalı, berrak sitoplazmalı kitle seminomdur (%15 sinsityotrofoblast minimal hCG yapar); ≥65 yaş infiltratsız kitle spermatositik seminomdur (metastazsız)`,B:`Seminom %5'tir`,C:`Sinsityotrofoblast prognozu bozar`,D:`Spermatositik gençtedir`,E:`Spermatositik metastazlıdır`},dogru:`A`,aciklama:`Seminom ~%50, berrak glikojenli üniform-septalı-lenfositli; %15 sinsityotrofoblast (minimal hCG, prognoz etkilemez); spermatositik ≥65, infiltratsız-metastazsız-i(12p)siz.`,sik_aciklamalari:{A:`Doğru: iki seminom varyantı tamdır.`,B:`~%50'dir.`,C:`Etkilemez.`,D:`≥65'tedir.`,E:`Yapmaz.`},bilgi:[38],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k29-q05`,kazanim:29,zorluk:`zor`,soru:`Çocuk ve erişkin non-seminomatöz tümörleri karşılaştırılıyor. Hangi eşleşme doğrudur?`,secenekler:{A:`Yolk sak erişkin tümörüdür`,B:`Koryokarsinom hCG negatiftir`,C:`Teratom postpubertal benigndir`,D:`2 yaşındaki AFP yüksek-Schiller-Duval cisimli tümör yolk sak, hCG yüksek hemorajik tümör koryokarsinomdur; postpubertal teratom malign kabul edilir`,E:`Embriyonal iyi sınırlıdır`},dogru:`D`,aciklama:`Embriyonal kanamalı-nekrotik (saf %2-3); yolk sak <3 yaş en sık, Schiller-Duval-AFP; koryokarsinom hCG daima yüksek; teratom postpubertal malign, malign transformasyon kemoterapisiz.`,sik_aciklamalari:{A:`<3 yaş en sıktır.`,B:`Daima yüksektir.`,C:`Maligndir.`,D:`Doğru: yaş-belirteç-malignite üçlüsü tamdır.`,E:`Kötü sınırlı-nekrotiktir.`},bilgi:[39],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k29-q06`,kazanim:29,zorluk:`orta`,soru:`Germ hücreli tiplerin makroskopisi nedir?`,secenekler:{A:`Seminom hemorajiktir`,B:`Yolk AFP negatiftir`,C:`Koryo tek hücrelidir`,D:`Teratom germ dışıdır`,E:`Seminom homojen, embriyonal hemorajik, yolk Schiller-Duvallidir`},dogru:`E`,aciklama:`Seminom homojen gri-beyaz yumuşak sınırlı kitledir. Embriyonal kötü sınırlı hemorajik, yolk sak Schiller-Duval globüllü, koryo iki hücreli trofoblastik, teratom üç germ yapraklıdır.`,sik_aciklamalari:{A:`Homojen gri-beyazdır.`,B:`AFP içeren globuller vardır.`,C:`Sito-sinsityotrofoblastiktir.`,D:`Somatik diferansiyon gösterir.`,E:`Doğru: üç tipin makrosu birlikte doğru verilmiştir.`},bilgi:[38,39],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k29-q07`,kazanim:29,zorluk:`orta`,soru:`hCG ve AFP tümör eşleşmesi nedir?`,secenekler:{A:`LDH tip belirler`,B:`Seminom hCG negatiftir`,C:`Koryo hCG düşüktür`,D:`hCG trofoblastik, AFP yolk sak belirtecidir`,E:`Belirteçler izlemez`},dogru:`D`,aciklama:`hCG trofoblastik, AFP yolk sak, LDH yük belirtecidir. Koryoda hCG daima yüksek; seminomda %15 sinsityotrofoblast hCG'yi hafif yükseltebilir.`,sik_aciklamalari:{A:`Tümör yüküyle ilişkilidir.`,B:`%15 sinsityotrofoblast yükseltebilir.`,C:`Daima yüksektir.`,D:`Doğru: iki belirteç-tümör eşleşmesi doğru verilmiştir.`,E:`Yanıt izlemede kullanılır.`},bilgi:[38,40],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k29-q08`,kazanim:29,zorluk:`kolay`,soru:`Aşağıdakilerden "Prostat karsinomu: epidemiyoloji" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{E:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,B:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,A:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,D:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,C:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`},dogru:`E`,aciklama:`Doğru: Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,sik_aciklamalari:{E:`Doğru. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`,B:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,A:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,D:`Yanlış. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,C:`Yanlış. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`},bilgi:[29],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k29-q09`,kazanim:29,zorluk:`orta`,soru:`"Prostatit sınıflaması" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{A:`Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,D:`Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,E:`Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,B:`Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,C:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},dogru:`A`,aciklama:`Doğru: Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,sik_aciklamalari:{A:`Doğru. Dört kategori: akut bakteriyel (%2-5), kronik bakteriyel (%2-5), kronik nonbakteriyel/kronik pelvik ağrı sendromu (%90-95) ve asemptomatik inflamatuar prostatit. Akut ve kronik bakteriyel prostatit sık rastlanan üropatojenlerce oluşur.`,D:`Yanlış. Puberteden önce inmemiş testisin cerrahi yolla skrotuma yerleştirilmesi (orşiopeksi) atrofi ihtimalini azaltır. Histolojik değişiklikler 2 yaş gibi erken başlar: germ hücre gelişiminde arrest, bazal membranda hiyalinizasyon ve kalınlaşma, interstisyel stromada artış ve leydig hücre belirginliği.`,E:`Yanlış. Balanit glans penisin, balanopostit glans ve prepisyumun lokal inflamasyonudur; Candida albicans, anaerob bakteriler, Gardnerella ve piyojenik bakteriler etkendir ve çoğu olgu smegma birikimine bağlıdır. Fimozis prepisyumun glans üzerinde kolayca geri çekilememesidir.`,B:`Yanlış. Spermatosel semenin dilate efferent duktusta veya rete testis duktuslarında kistik birikimidir; varikosel spermatik kordda genişlemiş venöz yapılardır.`,C:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},bilgi:[21],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k29-q10`,kazanim:29,zorluk:`orta`,soru:`"Prostatit klinik özellikleri ve tedavi" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,C:`Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,E:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,D:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,A:`Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`},dogru:`B`,aciklama:`Doğru: Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,sik_aciklamalari:{B:`Doğru. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,C:`Yanlış. Skrotal kese neoplazilerine az rastlanır; en çok görülen skuamöz hücreli karsinom, Sir Percival Pott tarafından baca temizleyicilerinde yüksek oranda gözlenen, çevresel etkilerle ilgili ilk insan malignitesini temsil eder.`,E:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`,D:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,A:`Yanlış. Spermatik kordun kıvrılması kalın duvarlı arterleri açık bırakır ancak tipik olarak venöz drenajın obstrüksiyonuna yol açar; düzelmezse venöz infarkt gelişir. Neonatal torsiyonda anatomik defekt yoktur; yetişkin tip torsiyon adolesanlarda görülür ve "çan tokmağı anomalisi" adlı bilateral defektle birliktedir.`},bilgi:[23],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k29-q11`,kazanim:29,zorluk:`zor`,soru:`"DHT ve 5α-redüktaz tip 2" bilgisini içeren doğru kurulum aşağıdakilerden hangisidir?`,secenekler:{E:`Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,D:`hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,C:`Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,A:`En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,B:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`},dogru:`E`,aciklama:`Doğru: Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,sik_aciklamalari:{E:`Doğru. Prostat dokusundaki ana androjen, prostatik androjenlerin %90'ını oluşturan DHT'dir; testosterondan tip 2 5α-redüktaz ile üretilir ve bu enzimin neredeyse tamamı stromal hücrelerde lokalizedir. Tip 1 5α-redüktaz prostatta bulunmaz veya çok düşük düzeydedir.`,D:`Yanlış. hCG koryokarsinomda serumda daima yüksektir, AFP yolk sak komponentini gösterir, LDH tümör yüküyle ilişkilidir; belirteçler tanıda yardımcı olup esas olarak tedaviye cevabı izlemede kullanılır. Klinikte sıklıkla translüsens vermeyen ağrısız kitle vardır ve solid testis kitlelerinde standart tedavi radikal orşiektomidir.`,C:`Yanlış. Enfeksiyonlar ve otoimmün hastalıklar testiste granülomatöz reaksiyon oluşturabilir; en sık görüleni tüberkülozdur ve genellikle epididimit ile başlar, testis sekonder tutulur.`,A:`Yanlış. En çok glans penis ya da prepisyum üzerinde gri, pürtüklü, papüler lezyon; ileri olgularda ortası ülsere, sınırları düzensiz, endure lezyon oluşur ve histolojik olarak tipik keratinize skuamöz hücreli karsinom görünümü vardır. Prognoz evreye bağlıdır.`,B:`Yanlış. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`},bilgi:[25],benzer_cikmis:[]}],ilgili_cikmis:[{id:`f16bbc2e4bd0`,soru:`Glikojenden zengin, belirgin nukleoluslu yuvarlak çekirdekli hücrelerden oluşan tümör hangisidir?`,secenekler:{A:`Koryokarsinom`,B:`Embriyonal karsinom`,C:`Yolk sak tümörü`,D:`Seminom`,E:`Teratom`},cevap:`D`}]},{no:30,metin:`Testis tümörlerinin klinik özelliklerini ve tedavi yaklaşımını açıklayabilmek`,sorular:[{id:`k1-66-q88`,kazanim:30,zorluk:`kolay`,soru:`Solid testis kitlesinde standart tedavi hangisidir?`,secenekler:{A:`Radikal orşiektomi`,B:`Transskrotal biyopsi`,C:`Yalnızca antibiyotik`,D:`Orşiopeksi`,E:`Aspirasyon`},dogru:`A`,aciklama:`Solid testis kitlelerinde standart yaklaşım radikal orşiektomidir.`,sik_aciklamalari:{A:`Doğru: tanı ve tedavi için standarttır.`,B:`Transskrotal biyopsi standart yaklaşım değildir.`,C:`Antibiyotik tümörü tedavi etmez.`,D:`Orşiopeksi kriptorşidizm tedavisidir.`,E:`Aspirasyon solid tümör için uygun değildir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-66-q89`,kazanim:30,zorluk:`orta`,soru:`28 yaşında erkekte translüminasyon vermeyen, ağrısız testis kitlesi var.

Bu hastada testis tümörü belirteçlerinin temel kullanım amacı hangisidir?`,secenekler:{A:`Tanıya yardımcı olmak ve esas olarak tedaviye yanıtı izlemek`,B:`Kitlenin benign olduğunu kesin göstermek`,C:`Orşiektomi gerekliliğini ortadan kaldırmak`,D:`Prostat kanserini dışlamak`,E:`Hidrosel tanısı koymak`},dogru:`A`,aciklama:`hCG, AFP ve LDH tanıya yardımcıdır ancak esas olarak tedaviye yanıtın izlenmesinde kullanılır.`,sik_aciklamalari:{A:`Doğru: belirteçlerin temel rolüdür.`,B:`Belirteçler benignliği kanıtlamaz.`,C:`Solid kitlede orşiektomi standarttır.`,D:`Prostat kanseri PSA ile değerlendirilir.`,E:`Hidrosel translüminasyon verir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-66-q90`,kazanim:30,zorluk:`zor`,soru:`Testis tümörlerinin tedavisi ve prognozu ile ilgili aşağıdakilerden hangisi yanlıştır?`,secenekler:{A:`Seminom radyoterapiye duyarlıdır ve en iyi prognoza sahiptir`,B:`Non-seminomatöz tümörlerin ~%90'ı agresif kemoterapiyle komplet remisyona girer`,C:`Nüksler genellikle ilk 2 yılda görülür`,D:`LDH tümör yüküyle ilişkilidir`,E:`Non-seminomatöz tümörler radyoterapiye seminomdan daha duyarlıdır ve prognozları daha iyidir`},dogru:`E`,aciklama:`Seminom radyoterapiye duyarlı ve en iyi prognozludur; non-seminomatöz tümörler kemoterapiyle tedavi edilir.`,sik_aciklamalari:{A:`Doğru ifade: seminomun prognozu en iyidir.`,B:`Doğru ifade: kemoterapi yanıtı yüksektir.`,C:`Doğru ifade: izlem ilk 2 yılda yoğundur.`,D:`Doğru ifade: LDH tümör yükünü yansıtır.`,E:`Yanlış ifade (aranan cevap): radyosensitivite ve en iyi prognoz seminoma aittir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k30-q04`,kazanim:30,zorluk:`orta`,soru:`Solid testis kitlesinde ilk cerrahi ve belirteçlerin rolü soruluyor. Hangi plan doğrudur?`,secenekler:{A:`Belirteçler tanı koydurur`,B:`Translüsens veren kitle tümördür`,C:`Translüsens vermeyen ağrısız solid kitlede radikal orşiektomi standarttır; hCG-AFP-LDH tedaviye cevabı izlemede esastır`,D:`Orşiektomi kontrendikedir`,E:`LDH belirteç değildir`},dogru:`C`,aciklama:`hCG koryokarsinomda daima yüksek, AFP yolk sak, LDH yük; belirteçler tedaviye cevabı izler; solid kitlede standart radikal orşiektomi; translüsens vermeyen ağrısız kitle tipiktir.`,sik_aciklamalari:{A:`İzlemde esastır.`,B:`Hidroseldir.`,C:`Doğru: klinik-cerrahi-izlem üçlüsü tamdır.`,D:`Standarttır.`,E:`Yükle ilişkilidir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k30-q05`,kazanim:30,zorluk:`zor`,soru:`Seminom ve non-seminomatöz tedavi sonuçları karşılaştırılıyor. Hangi özet doğrudur?`,secenekler:{A:`Seminom kemoterapiye dirençlidir`,B:`Non-seminomatöz izlenir`,C:`Nüks geç olur`,D:`Prognoz histolojiden bağımsızdır`,E:`Seminom radyoterapiye duyarlı-en iyi prognozludur; non-seminomatöz ~%90 kemoterapiyle remisyona girer ve nüksler ilk 2 yılda uzak metastaz olarak görülür`},dogru:`E`,aciklama:`Seminom radyoduyarlı-en iyi prognoz; non-seminomatöz ~%90 agresif kemoterapiyle remisyon; nüks ilk 2 yıl uzak metastaz.`,sik_aciklamalari:{A:`Duyarlıdır.`,B:`Agresif kemoterapi gerekir.`,C:`İlk 2 yıldadır.`,D:`Belirleyicidir.`,E:`Doğru: duyarlılık-remisyon-nüks üçlüsü tamdır.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k30-q06`,kazanim:30,zorluk:`orta`,soru:`Testis kitlesinde klinik ve cerrahi standart nedir?`,secenekler:{A:`Ağrısız solid kitlede radikal orşiektomi standarttır`,B:`Skrotal eksizyon yapılır`,C:`Ağrı maligndir`,D:`Translüminens maligndir`,E:`İzlem yeterlidir`},dogru:`A`,aciklama:`Solid kitlede standart radikal orşiektomidir; skrotal yaklaşımdan kaçınılır. Translüsens vermeyen ağrısız kitle maligniteyi düşündürür; hidrosel translüminens verir.`,sik_aciklamalari:{A:`Doğru: klinik bulgu ve cerrahi standart birlikte doğru verilmiştir.`,B:`Radikal orşiektomi standarttır.`,C:`Ağrısız kitle tipiktir.`,D:`Translüsens vermez.`,E:`Solid kitlede cerrahi gerekir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k30-q07`,kazanim:30,zorluk:`orta`,soru:`Belirteçlerin izlem rolü ve LDH anlamı nedir?`,secenekler:{A:`Belirteç tanı koydurur`,B:`LDH tip belirler`,C:`Belirteçler yanıt izlemede kullanılır; LDH yükü gösterir`,D:`Takip gerekmez`,E:`LDH düşüklüğü nükstür`},dogru:`C`,aciklama:`LDH tümör yüküyle ilişkilidir; hCG-AFP-LDH belirteçleri tanıda yardımcı, esas olarak tedaviye cevabı izlemede kullanılır. Radikal orşiektomi sonrası belirteç takibi nüksü erken yakalar.`,sik_aciklamalari:{A:`Tanıda yardımcıdır.`,B:`Tümör yüküyle ilişkilidir.`,C:`Doğru: belirteçlerin rolü ve LDH anlamı birlikte doğru verilmiştir.`,D:`Tedaviye cevap izlenir.`,E:`Yükselme yük-nüks lehinedir.`},bilgi:[40],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k30-q08`,kazanim:30,zorluk:`kolay`,soru:`Aşağıdakilerden "Prostat karsinomu morfolojisi ve PİN" ile ilgili doğru olan seçeneği işaretleyiniz.`,secenekler:{A:`Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,E:`Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,C:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,B:`Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,D:`Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},dogru:`A`,aciklama:`Doğru: Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,sik_aciklamalari:{A:`Doğru. Lezyonların çoğu belirgin gland yapılarından oluşan orta derecede diferansiye adenokarsinomlardır; glandlar benignlerden daha küçük, tek sıralı üniform küboidal/alçak kolumnar epitelle döşelidir ve benign glandlardaki bazal tabaka izlenmez. Nükleuslar büyümüş, belirgin nükleollü; pleomorfizm belirgin değil ve mitoz nadirdir.`,E:`Yanlış. Yaşlı sünnetsiz erkeklerin penis şaftında soliter plak lezyon olarak görülür; epidermisi tam kat tutan, morfolojik olarak malign ancak alttaki stromaya invazyon yapmayan hücreler vardır.`,C:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`,B:`Yanlış. Skuamöz hücreli karsinomun papiller yapılanma gösteren, gerçekte sitolojik atipi içermeyen, derin ve sınırları yuvarlak, itici tarzda bir varyantıdır.`,D:`Yanlış. Anormal üretral orifis penisin dorsal kısmındadır; yaklaşık 120.000 erkekte bir görülür ve sıklıkla mesane ekstrofisi ile birliktedir (ekstrofi ve epispadias kompleksi).`},bilgi:[31],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k30-q09`,kazanim:30,zorluk:`orta`,soru:`"Granülomatöz prostatit ve biyopsi endikasyonu" kavramı hakkında verilen aşağıdakilerden hangisi doğrudur?`,secenekler:{E:`Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,B:`Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,D:`Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,C:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,A:`Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`},dogru:`E`,aciklama:`Doğru: Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,sik_aciklamalari:{E:`Doğru. Akut/kronik prostatitte bulgular nonspesifik ve sepsis riski nedeniyle biyopsi genellikle yapılmaz; ancak granülomatöz prostatit endurasyon yaptığından biyopsi endikasyonu doğar. ABD'de en yaygın sebep mesane içine uygulanan BCG aşısıdır.`,B:`Yanlış. Patolojik olarak BPH'lı erkeklerin sadece %10'unda klinik bulgular görülür; BPH iç tabakada geliştiği için en yaygın bulgular alt idrar yolu tıkanıklığı ile ilişkilidir (idrar başlatmada zorluk, kesintili akış, sık ve gece işemeleri). Tam tıkanıklık ağrılı mesane distansiyonu ve tedavi edilmezse hidronefroza neden olur.`,D:`Yanlış. Karsinomların %70-80'i periferik glandlardan kaynaklanır ve rektal dijital muayenede sert düzensiz nodüller olarak palpe edilir; çoğu küçük, nonpalpabl ve asemptomatik olduğundan PSA yüksekliği araştırılırken iğne biyopsisiyle saptanır.`,C:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,A:`Yanlış. Korpus kavernozumda oluşan fibröz bantlar sonucu gelişir; etiyolojisi tam bilinmemekle birlikte fibromatozisin bir varyantı olarak sınıflayan kaynaklar vardır.`},bilgi:[22],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k30-q10`,kazanim:30,zorluk:`orta`,soru:`"Prostat karsinomu tedavisi ve LHRH flare" ile ilgili eşleştirmelerden hangisi doğrudur?`,secenekler:{E:`Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,D:`Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,B:`Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,C:`Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,A:`Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`},dogru:`E`,aciklama:`Doğru: Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,sik_aciklamalari:{E:`Doğru. Lokalize hastalıkta en yaygın tedaviler radikal prostatektomi ve radyoterapidir; yavaş seyir nedeniyle yaşlı erkeklerde aktif gözetim (uyanık bekleme) uygundur. İlerlemiş metastatik karsinomda farmakolojik orşiektomi etkisi oluşturan LHRH agonistleri ile androjen yoksunluğu yaratılır.`,D:`Yanlış. Patogenezde edinsel somatik mutasyonlar rol oynar; androjenler merkezi önemdedir (puberteden önce kastre edilenlerde hastalık gelişmez). TMPRSS2-ETS füzyon genleri beyaz ırktaki prostat kanserlerinin %40-60'ında bulunur; diğer mutasyonlar PI3K/AKT yolunu aktive eder ve en yaygını PTEN'i inaktive eden mutasyonlardır. Risk siyahlarda en yüksek, Asyalılarda en düşüktür.`,B:`Yanlış. Benign prostat hiperplazisi 40 yaş üzerinde ve yaşla artan sıklıkta görülür, sekizinci dekatta %90'lara ulaşır; hem epitelyal hem stromal elemanların artışı ile karakterizedir. Puberteden önce kastre edilen erkeklerde ve androjen aktivitesi bloke olan genetik hastalıklı erkeklerde ortaya çıkmaz.`,C:`Yanlış. Hidrosel tunika vajinalis içinde seröz sıvı birikimidir ve skrotal büyümenin en fazla sebebidir; translüminens olduğundan püy, kan ve lenf sıvısından ayrılır. Kan birikimi hematosel, lenf sıvısı birikimi şilosel; ileri lenfatik obstrüksiyonda elefantiazis.`,A:`Yanlış. Üretranın anormal açıklığı penisin ventral yüzeyinde, şaft boyunca herhangi bir lokalizasyondadır; üretral ağız bazen konstriktedir. Erkek yenidoğanlarda 1:300 görülür ve inguinal herni ile inmemiş testis gibi anomalilerle birlikte olabilir.`},bilgi:[35],benzer_cikmis:[]},{id:`k1-66-erkek-genital-sistem-ve-prostat-hastaliklari-k30-q11`,kazanim:30,zorluk:`zor`,soru:`"Prostatit klinik özellikleri ve tedavi" klinik bağlamda aşağıdakilerden hangisi doğrudur?`,secenekler:{B:`Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,C:`Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,D:`Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,A:`Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,E:`Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`},dogru:`B`,aciklama:`Doğru: Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,sik_aciklamalari:{B:`Doğru. Akut bakteriyel prostatit dizüri ile birliktedir ve sepsis komplikasyonu gelişebilir; rektal incelemede prostat hassas ve yumuşaktır. Kronik bakteriyel prostatit tekrarlayan üriner enfeksiyon, alt sırt ağrısı ve perineal/suprapubik rahatsızlık yapar. Kronik nonbakteriyel prostatitte sekresyonda büyük büyütme alanı başına 10'dan fazla lökosit görülür.`,C:`Yanlış. Embriyonal karsinom kötü sınırlı, kanama ve nekroz içeren invaziv kitledir (saf formu tüm germ hücre tümörlerinin %2-3'ü). Yolk sak tümörü 3 yaşından küçük çocukların en sık primer testis neoplazisidir ve Schiller-Duval cisimleri ile AFP içeren globuller gösterir. Koryokarsinom sito- ve sinsityotrofoblastik diferansiasyon gösterir; HCG yükselir. Teratom somatik diferansiasyon gösterir ve postpubertal erkeklerde malign kabul edilir.`,D:`Yanlış. Torsiyon az sayıdaki ürolojik acil problemden biridir; ilk 6 saat içinde cerrahi işlem uygulanır ve kord elle düzeltilirse testisin yaşaması için bir şans olabilir.`,A:`Yanlış. Testisin skrotuma inmesindeki yetersizliğidir; normalde testisler gebeliğin üçüncü ayında solom boşluğundan pelvise, intrauterin yaşamın son 2 ayında inguinal kanal boyunca skrotuma iner. Erkek nüfusunun %1'inde 1 yaş civarında görülür, %10 bilateral ve sağda daha sıktır.`,E:`Yanlış. Prostatın adenokarsinomu esas olarak 50 yaş üstü erkeklerde oluşur ve erkeklerde en sık görülen kanserdir; ölüm oranı akciğer kanserinden daha az, kolorektal kanserle eşit olup tüm kanser ölümlerinin %9'undan sorumludur.`},bilgi:[23],benzer_cikmis:[]}],ilgili_cikmis:[]}]};export{e as default};